#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LocalPlan {
    binding: BindingId,
    name: String,
    java_ty: JavaType,
    shape: RustSlotShape,
    binding_mutable: bool,
    proven_non_null: bool,
}

impl LocalPlan {
    pub fn new(
        binding: BindingId,
        name: String,
        java_ty: JavaType,
        shape: RustSlotShape,
        binding_mutable: bool,
    ) -> Self {
        Self {
            binding,
            name,
            java_ty,
            shape,
            binding_mutable,
            proven_non_null: false,
        }
    }

    pub fn binding(&self) -> &BindingId {
        &self.binding
    }

    pub fn name(&self) -> &str {
        &self.name
    }

    pub fn java_ty(&self) -> &JavaType {
        &self.java_ty
    }

    pub fn shape(&self) -> &RustSlotShape {
        &self.shape
    }

    pub fn binding_mutable(&self) -> bool {
        self.binding_mutable
    }

    pub fn proven_non_null(&self) -> bool {
        self.proven_non_null
    }

    pub fn with_proven_non_null(mut self, proven_non_null: bool) -> Self {
        self.proven_non_null = proven_non_null;
        self
    }

    pub fn with_shape(mut self, shape: RustSlotShape) -> Self {
        self.shape = shape;
        self
    }

    pub fn set_shape(&mut self, shape: RustSlotShape) {
        self.shape = shape;
    }

    pub fn set_name(&mut self, name: String) {
        self.name = name;
    }

    pub fn set_java_ty(&mut self, java_ty: JavaType) {
        self.java_ty = java_ty;
    }

    pub fn shape_mut(&mut self) -> &mut RustSlotShape {
        &mut self.shape
    }

    pub fn mark_binding_mutable(&mut self) {
        self.binding_mutable = true;
    }

    pub(crate) fn source_name(&self) -> &str {
        self.binding.name()
    }
}

