pub struct SignatureConstraintState {
    methods: HashMap<MethodKey, MethodConstraintSet>,
    constructors: HashMap<ConstructorKey, ConstructorConstraintSet>,
    fields: HashMap<FieldKey, Vec<SignatureConstraint>>,
    method_lookup_index: Option<Arc<SignatureMethodLookupIndex>>,
    initializer_storage_edges: Vec<(SignatureDependencyNode, SignatureDependencyNode)>,
    generic_allocation_edges: Arc<Vec<crate::source_generic_allocations::GenericAllocationEdge>>,
}

impl PartialEq for SignatureConstraintState {
    fn eq(&self, other: &Self) -> bool {
        self.methods == other.methods
            && self.constructors == other.constructors
            && self.fields == other.fields
    }
}

impl Eq for SignatureConstraintState {}

#[derive(Debug)]
struct SignatureMethodLookupIndex {
    by_owner: HashMap<String, Vec<MethodKey>>,
    by_simple_owner: HashMap<String, Vec<MethodKey>>,
    by_rust_name: HashMap<String, Vec<MethodKey>>,
    fields_by_name: HashMap<String, Vec<FieldKey>>,
}

impl SignatureMethodLookupIndex {
    fn new(constraints: &SignatureConstraintState) -> Self {
        let mut by_owner = HashMap::<String, Vec<MethodKey>>::new();
        let mut by_simple_owner = HashMap::<String, Vec<MethodKey>>::new();
        let mut by_rust_name = HashMap::<String, Vec<MethodKey>>::new();
        let mut fields_by_name = HashMap::<String, Vec<FieldKey>>::new();
        for key in constraints.fields.keys() {
            fields_by_name
                .entry(key.field_name.clone())
                .or_default()
                .push(key.clone());
        }
        for key in constraints.methods.keys() {
            by_rust_name
                .entry(key.rust_name.clone())
                .or_default()
                .push(key.clone());
            by_owner
                .entry(key.type_name().to_string())
                .or_default()
                .push(key.clone());
            by_simple_owner
                .entry(type_name_simple_segment(key.type_name()).to_string())
                .or_default()
                .push(key.clone());
        }
        Self {
            by_owner,
            by_simple_owner,
            by_rust_name,
            fields_by_name,
        }
    }
}

impl SignatureConstraintState {
    fn rebuild_method_lookup_index(&mut self) {
        self.method_lookup_index = Some(Arc::new(SignatureMethodLookupIndex::new(self)));
    }

    pub fn methods(&self) -> &HashMap<MethodKey, MethodConstraintSet> {
        &self.methods
    }

    pub fn constructors(&self) -> &HashMap<ConstructorKey, ConstructorConstraintSet> {
        &self.constructors
    }

    pub fn fields(&self) -> &HashMap<FieldKey, Vec<SignatureConstraint>> {
        &self.fields
    }

    pub fn with_method_constraints(
        mut self,
        key: MethodKey,
        constraints: MethodConstraintSet,
    ) -> Self {
        self.methods.insert(key, constraints);
        self.method_lookup_index = None;
        self
    }

    pub fn with_constructor_constraints(
        mut self,
        key: ConstructorKey,
        constraints: ConstructorConstraintSet,
    ) -> Self {
        self.constructors.insert(key, constraints);
        self
    }

    pub fn with_field_constraints(
        mut self,
        key: FieldKey,
        constraints: Vec<SignatureConstraint>,
    ) -> Self {
        self.fields.insert(key, constraints);
        self.method_lookup_index = None;
        self
    }
}

