pub fn solve_signatures_with_facts(
    program: &Program,
    representations: &RepresentationPlan,
    usage: &UsageFacts,
    facts: &FactSet,
) -> SignaturePlan {
    solve_signatures_with_facts_and_support_context(program, representations, usage, facts, program)
}

pub fn solve_signatures_with_facts_and_support_context(
    program: &Program,
    representations: &RepresentationPlan,
    usage: &UsageFacts,
    facts: &FactSet,
    support_program: &Program,
) -> SignaturePlan {
    solve_signatures_with_facts_and_support_context_profiled(
        program,
        representations,
        usage,
        facts,
        support_program,
    )
    .plan
}

pub fn solve_signatures_with_facts_and_support_context_profiled(
    program: &Program,
    representations: &RepresentationPlan,
    usage: &UsageFacts,
    facts: &FactSet,
    support_program: &Program,
) -> ProfiledSignaturePlan {
    solve_signatures_with_facts_and_support_context_profiled_with_progress(
        program,
        representations,
        usage,
        facts,
        support_program,
        None,
    )
}

pub fn solve_signatures_with_facts_and_support_context_profiled_with_progress(
    program: &Program,
    representations: &RepresentationPlan,
    usage: &UsageFacts,
    facts: &FactSet,
    support_program: &Program,
    progress_sink: Option<SignatureSolverProgressSink<'_>>,
) -> ProfiledSignaturePlan {
    emit_signature_solver_progress(
        progress_sink,
        "collect_constraints",
        "running",
        0,
        "collect_signature_constraints",
    );
    let collect_start = std::time::Instant::now();
    let mut constraints =
        collect_signature_constraints_with_representations(program, representations, usage, facts);
    if !std::ptr::eq(program, support_program) {
        let support_constraints = collect_signature_constraints_with_representations(
            support_program,
            representations,
            usage,
            facts,
        );
        merge_support_context_nullability_constraints(&mut constraints, support_constraints);
    }
    let override_topology =
        build_source_override_constraint_topology(&constraints, support_program, facts);
    equalize_source_override_nullability_constraints_with_topology(
        &mut constraints,
        &override_topology,
    );
    let owner_alias_topology = build_source_owner_alias_receiver_topology(&constraints);
    constraints.rebuild_method_lookup_index();
    constraints.generic_allocation_edges = Arc::new(source_generic_allocation_edges(
        support_program,
        &constraints,
    ));
    let collect_constraints_ms = collect_start.elapsed().as_millis();
    emit_signature_solver_progress(
        progress_sink,
        "collect_constraints",
        "ok",
        collect_constraints_ms,
        "collect_signature_constraints",
    );

    let domain_stats = signature_fixpoint_domain_stats(&constraints);

    emit_signature_solver_progress(
        progress_sink,
        "dependency_graph",
        "running",
        0,
        "build_signature_dependency_graph",
    );
    let graph_start = std::time::Instant::now();
    let dependency_graph = build_signature_dependency_graph(&constraints, usage);
    let dependency_graph_ms = graph_start.elapsed().as_millis();
    emit_signature_solver_progress(
        progress_sink,
        "dependency_graph",
        "ok",
        dependency_graph_ms,
        &format!(
            "nodes={} edges={}",
            dependency_graph.nodes().len(),
            dependency_graph.edges().len()
        ),
    );

    emit_signature_solver_progress(
        progress_sink,
        "scc_analysis",
        "running",
        0,
        "analyze_signature_dependency_sccs",
    );
    let scc_start = std::time::Instant::now();
    let dependency_sccs = analyze_signature_dependency_sccs(&dependency_graph);
    let scc_analysis_ms = scc_start.elapsed().as_millis();
    emit_signature_solver_progress(
        progress_sink,
        "scc_analysis",
        "ok",
        scc_analysis_ms,
        &format!(
            "components={} cyclic={} max_component_size={}",
            dependency_sccs.stats.component_count(),
            dependency_sccs.stats.cyclic_component_count(),
            dependency_sccs.stats.max_component_size()
        ),
    );

    emit_signature_solver_progress(
        progress_sink,
        "pass_plan",
        "running",
        0,
        "plan_signature_solver_passes",
    );
    let pass_plan_start = std::time::Instant::now();
    let pass_plan = plan_signature_solver_passes(&dependency_sccs);
    let pass_plan_ms = pass_plan_start.elapsed().as_millis();
    emit_signature_solver_progress(
        progress_sink,
        "pass_plan",
        "ok",
        pass_plan_ms,
        &format!(
            "components={} mutable={}",
            pass_plan.component_order().len(),
            pass_plan.mutable_components().len()
        ),
    );

    emit_signature_solver_progress(
        progress_sink,
        "fixpoint",
        "running",
        0,
        &format!(
            "slots={} constraints={} budget={}",
            domain_stats.slot_count,
            domain_stats.unique_constraint_count,
            domain_stats.iteration_budget
        ),
    );
    let fixpoint_start = std::time::Instant::now();
    let saturation_policy = signature_fixpoint_saturation_policy(&constraints);
    let mut execution_stats = SignatureSolverExecutionStats::default();
    let mut current_iteration = 0usize;
    let result = saturation_policy.saturate(
        constraints,
        |constraints| {
            current_iteration += 1;
            // Body/call propagation can discover requirements after the seed
            // constraints were collected.  Override slots are equivalence
            // classes, so re-join them on every fixpoint iteration rather
            // than only once before propagation begins.
            let override_slots_changed =
                equalize_source_override_nullability_constraints_with_topology(
                    constraints,
                    &override_topology,
                );
            let owner_alias_receivers_changed =
                equalize_source_owner_alias_receiver_constraints_with_topology(
                    constraints,
                    &owner_alias_topology,
                );
            let (propagation_changed, stats) =
                execute_global_signature_solver_sweep_with_stats(constraints, usage);
            let changed = override_slots_changed
                || owner_alias_receivers_changed
                || propagation_changed;
            execution_stats.component_sweeps += stats.component_sweeps;
            execution_stats.changed_component_sweeps += stats.changed_component_sweeps;
            execution_stats.state_clones += stats.state_clones;
            execution_stats.state_clone_ms += stats.state_clone_ms;
            execution_stats.propagation_sweep_ms += stats.propagation_sweep_ms;
            execution_stats.component_rollback_ms += stats.component_rollback_ms;
            execution_stats.component_change_check_ms += stats.component_change_check_ms;
            execution_stats.add_propagation_arm_stats(&stats.propagation_arms);
            emit_signature_solver_progress(
                progress_sink,
                "fixpoint_iteration",
                if changed { "changed" } else { "stable" },
                fixpoint_start.elapsed().as_millis(),
                &format!(
                    "iteration={} component_sweeps={} changed_component_sweeps={}",
                    current_iteration,
                    execution_stats.component_sweeps,
                    execution_stats.changed_component_sweeps
                ),
            );
            SaturationStep::from(changed)
        },
        |max_iterations| {
            SignatureDiagnostic::new(
                "signature_fixpoint_budget_exceeded",
                format!(
                "signature constraint fixpoint exceeded finite saturation budget of {max_iterations} iterations"
            ),
            )
        },
    );
    let fixpoint_ms = fixpoint_start.elapsed().as_millis();
    let fixpoint_iterations = result.iterations();
    let fixpoint_diagnostics = result.diagnostics().len();
    emit_signature_solver_progress(
        progress_sink,
        "fixpoint",
        "ok",
        fixpoint_ms,
        &format!("iterations={fixpoint_iterations} diagnostics={fixpoint_diagnostics}"),
    );

    emit_signature_solver_progress(
        progress_sink,
        "plan_build",
        "running",
        0,
        "build_signature_plan_from_constraints",
    );
    let plan_build_start = std::time::Instant::now();
    let (constraints, _iterations, diagnostics) = result.into_parts();
    let plan = build_signature_plan_from_constraints(
        program,
        support_program,
        representations,
        &constraints,
        fixpoint_iterations,
        diagnostics,
        facts,
    );
    let plan_build_ms = plan_build_start.elapsed().as_millis();
    emit_signature_solver_progress(
        progress_sink,
        "plan_build",
        "ok",
        plan_build_ms,
        "build_signature_plan_from_constraints",
    );

    let profile = SignatureSolverProfile {
        collect_constraints_ms,
        dependency_graph_ms,
        scc_analysis_ms,
        pass_plan_ms,
        fixpoint_ms,
        plan_build_ms,
        slot_count: domain_stats.slot_count,
        unique_constraint_count: domain_stats.unique_constraint_count,
        iteration_budget: domain_stats.iteration_budget,
        graph_node_count: dependency_sccs.stats.node_count(),
        graph_edge_count: dependency_sccs.stats.edge_count(),
        component_count: dependency_sccs.stats.component_count(),
        cyclic_component_count: dependency_sccs.stats.cyclic_component_count(),
        max_component_size: dependency_sccs.stats.max_component_size(),
        planned_components: pass_plan.stats().planned_components(),
        planned_mutable_components: pass_plan.stats().planned_mutable_components(),
        fixpoint_iterations,
        diagnostics: fixpoint_diagnostics,
        component_sweeps: execution_stats.component_sweeps,
        changed_component_sweeps: execution_stats.changed_component_sweeps,
        state_clones: execution_stats.state_clones,
        state_clone_ms: execution_stats.state_clone_ms,
        propagation_sweep_ms: execution_stats.propagation_sweep_ms,
        component_rollback_ms: execution_stats.component_rollback_ms,
        component_change_check_ms: execution_stats.component_change_check_ms,
        propagation_arms: execution_stats.propagation_arms,
    };
    ProfiledSignaturePlan::new(plan, profile)
}

fn emit_signature_solver_progress(
    progress_sink: Option<SignatureSolverProgressSink<'_>>,
    phase: &'static str,
    status: &'static str,
    elapsed_ms: u128,
    detail: &str,
) {
    if let Some(progress_sink) = progress_sink {
        progress_sink(SignatureSolverProgressEvent::new(
            phase,
            status,
            elapsed_ms,
            detail.to_string(),
        ));
    }
}

pub fn collect_signature_constraints(
    program: &Program,
    usage: &UsageFacts,
    facts: &FactSet,
) -> SignatureConstraintState {
    collect_signature_constraints_with_optional_representations(program, None, usage, facts)
}

pub fn collect_signature_constraints_with_representations(
    program: &Program,
    representations: &RepresentationPlan,
    usage: &UsageFacts,
    facts: &FactSet,
) -> SignatureConstraintState {
    collect_signature_constraints_with_optional_representations(
        program,
        Some(representations),
        usage,
        facts,
    )
}

fn collect_signature_constraints_with_optional_representations(
    program: &Program,
    representations: Option<&RepresentationPlan>,
    usage: &UsageFacts,
    facts: &FactSet,
) -> SignatureConstraintState {
    let mut constraints = SignatureConstraintState::default();
    let declared_source_types = program_declared_source_type_names(program);
    let external_index = facts.external_lookup_index();
    for ty in &program.types {
        collect_type_signature_constraints(
            ty,
            program,
            representations,
            usage,
            facts,
            &external_index,
            &declared_source_types,
            &mut constraints,
        );
    }
    constraints.initializer_storage_edges = initializer_storage_edges(program, &constraints);
    seed_native_list_projection_slots(&mut constraints, usage);
    seed_native_external_returns(program, &mut constraints, usage, facts);
    constraints.generic_allocation_edges =
        Arc::new(source_generic_allocation_edges(program, &constraints));
    constraints
}

fn source_generic_allocation_edges(
    program: &Program,
    constraints: &SignatureConstraintState,
) -> Vec<crate::source_generic_allocations::GenericAllocationEdge> {
    use crate::source_generic_allocations::GenericAllocationSlot;
    fn collect(
        ty: &TypeDecl,
        constraints: &SignatureConstraintState,
        slots: &mut Vec<GenericAllocationSlot>,
    ) {
        let mut push = |node, java_ty: &JavaType, shadows: &[String], declaration| {
            slots.push(GenericAllocationSlot {
                node,
                owner: ty.name.clone(),
                ty: java_ty.clone(),
                shadows: shadows.to_vec(),
                declaration,
            });
        };
        for member in &ty.members {
            match member {
                Member::Method(method) => {
                    let key = MethodKey::source_method(ty, method);
                    let Some(set) = constraints.methods.get(&key) else {
                        continue;
                    };
                    for (index, (param, name)) in
                        method.params.iter().zip(&set.param_names).enumerate()
                    {
                        push(
                            SignatureDependencyNode::MethodParam {
                                method: key.clone(),
                                name: name.clone(),
                                index,
                            },
                            &param.ty,
                            &method.type_params,
                            true,
                        );
                    }
                    push(
                        SignatureDependencyNode::MethodReturn {
                            method: key.clone(),
                        },
                        &method.return_type,
                        &method.type_params,
                        true,
                    );
                    for local in &set.locals {
                        push(
                            SignatureDependencyNode::MethodLocal {
                                method: key.clone(),
                                name: local.name.clone(),
                                binding: Some(local.binding.clone()),
                            },
                            &local.java_ty,
                            &method.type_params,
                            false,
                        );
                    }
                }
                Member::Constructor(ctor) => {
                    let key = ConstructorKey::source_constructor(ty, ctor);
                    let Some(set) = constraints.constructors.get(&key) else {
                        continue;
                    };
                    for (index, (param, name)) in
                        ctor.params.iter().zip(&set.param_names).enumerate()
                    {
                        push(
                            SignatureDependencyNode::ConstructorParam {
                                constructor: key.clone(),
                                name: name.clone(),
                                index,
                            },
                            &param.ty,
                            &ctor.type_params,
                            true,
                        );
                    }
                    for local in &set.locals {
                        push(
                            SignatureDependencyNode::ConstructorLocal {
                                constructor: key.clone(),
                                name: local.name.clone(),
                                binding: Some(local.binding.clone()),
                            },
                            &local.java_ty,
                            &ctor.type_params,
                            false,
                        );
                    }
                }
                Member::Field(field) => {
                    let field_key = FieldKey::source_field(ty, field);
                    if constraints.fields.contains_key(&field_key) {
                        push(
                            SignatureDependencyNode::Field { field: field_key },
                            &field.ty,
                            &[],
                            true,
                        );
                    }
                }
                _ => {}
            }
        }
        for member in &ty.members {
            if let Member::Type(nested) = member {
                collect(nested, constraints, slots);
            }
        }
    }
    let mut slots = Vec::new();
    for ty in &program.types {
        collect(ty, constraints, &mut slots);
    }
    crate::source_generic_allocations::constraint_edges(program, &slots)
}

/// Native views have no source callee node to join. Seed their physical
/// return ABI at the same storage nodes used by ordinary alias propagation.
fn seed_native_external_returns(
    program: &Program,
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    facts: &FactSet,
) {
    fn requirements(
        receiver: Option<&JavaType>,
        call: Option<&ResolvedCall>,
        name: &str,
        arity: usize,
        facts: &FactSet,
    ) -> Vec<SignatureConstraint> {
        let ty = receiver.map(|ty| optional_element_type(ty).unwrap_or_else(|| ty.clone()));
        let owner = ty
            .as_ref()
            .and_then(|ty| match ty {
                JavaType::Named { name, .. } | JavaType::Unknown(name) => Some(name.as_str()),
                _ => None,
            })
            .or_else(|| call.map(|call| call.declaring_type.as_str()));
        let Some(owner) = owner else { return vec![] };
        if EffectiveFacts::new(facts).has_parsed_source_definition(&JavaType::Named {
            name: owner.into(),
            args: vec![],
        }) {
            return vec![];
        }
        facts
            .native_return_allocation_for(owner, name, arity)
            .map(|contract| {
                contract
                    .allocations
                    .iter()
                    .map(|(path, placement)| {
                        native_allocation_requirement(path.clone(), *placement)
                    })
                    .collect()
            })
            .unwrap_or_default()
    }
    let mut pending = Vec::new();
    let mut append = |caller: SignatureCallableKey, body: &MethodUsageFacts| {
        for assigned in body.assigned_call_results() {
            let Some(binding) = body.binding_facts_for_declaration_id(&assigned.binding) else {
                continue;
            };
            let node = match &caller {
                SignatureCallableKey::Method(key) => {
                    method_binding_fact_dependency_node(constraints, key, binding)
                }
                SignatureCallableKey::Constructor(key) => {
                    constructor_binding_fact_dependency_node(constraints, key, binding)
                }
            };
            if let Some(node) = node {
                for requirement in requirements(
                    assigned.call.receiver_type(),
                    assigned.call.resolved(),
                    assigned.call.name(),
                    assigned.call.arg_count(),
                    facts,
                ) {
                    pending.push((node.clone(), requirement));
                }
            }
        }
        for site in body.call_sites() {
            let Some(callee) = site
                .resolved()
                .and_then(|call| method_key_for_resolved_call(constraints, call))
            else {
                continue;
            };
            let Some(params) = constraints.methods.get(&callee) else {
                continue;
            };
            for (index, call) in site.native_return_argument_calls() {
                let Some(name) = params.param_names.get(*index) else {
                    continue;
                };
                for requirement in requirements(
                    call.receiver_type(),
                    call.resolved(),
                    call.name(),
                    call.arg_count(),
                    facts,
                ) {
                    pending.push((
                        SignatureDependencyNode::MethodParam {
                            method: callee.clone(),
                            name: name.clone(),
                            index: *index,
                        },
                        requirement,
                    ));
                }
            }
        }
        for site in body.constructor_call_sites() {
            let Some(callee) = site.resolved().map(ConstructorKey::resolved_constructor) else {
                continue;
            };
            let Some(params) = constraints.constructors.get(&callee) else {
                continue;
            };
            for (index, call) in site.native_return_argument_calls() {
                let Some(name) = params.param_names.get(*index) else {
                    continue;
                };
                for requirement in requirements(
                    call.receiver_type(),
                    call.resolved(),
                    call.name(),
                    call.arg_count(),
                    facts,
                ) {
                    pending.push((
                        SignatureDependencyNode::ConstructorParam {
                            constructor: callee.clone(),
                            name: name.clone(),
                            index: *index,
                        },
                        requirement,
                    ));
                }
            }
        }
        if let SignatureCallableKey::Method(key) = &caller {
            for returned in body.returned_call_results() {
                for requirement in requirements(
                    returned.receiver_type(),
                    returned.resolved(),
                    returned.name(),
                    returned.arg_count(),
                    facts,
                ) {
                    pending.push((
                        SignatureDependencyNode::MethodReturn {
                            method: key.clone(),
                        },
                        requirement,
                    ));
                }
            }
        }
    };
    for (key, body) in usage.method_entries() {
        if let Some(key) = method_key_for_usage(constraints, key) {
            append(SignatureCallableKey::Method(key), body);
        }
    }
    for (key, body) in usage.constructor_entries() {
        let key = ConstructorKey::from_usage_key(key);
        if constraints.constructors.contains_key(&key) {
            append(SignatureCallableKey::Constructor(key), body);
        }
    }
    fn fields(
        ty: &TypeDecl,
        constraints: &SignatureConstraintState,
        facts: &FactSet,
        pending: &mut Vec<(SignatureDependencyNode, SignatureConstraint)>,
    ) {
        let mut env = crate::types::TypeEnv::default();
        env.bind_this_type(ty);
        for member in &ty.members {
            if let Member::Field(field) = member {
                env.insert_field(field.name.clone(), field.ty.clone());
            }
        }
        fn collect(
            expr: &Expr,
            env: &crate::types::TypeEnv,
            facts: &FactSet,
        ) -> Vec<SignatureConstraint> {
            match expr {
                Expr::Call {
                    receiver,
                    name,
                    args,
                    resolved,
                    ..
                } => {
                    let receiver = receiver
                        .as_deref()
                        .map(|expr| crate::types::infer_expr_type(expr, env));
                    requirements(
                        receiver.as_ref(),
                        resolved.as_ref(),
                        name,
                        args.len(),
                        facts,
                    )
                }
                Expr::Cast { expr, .. } => collect(expr, env, facts),
                Expr::Ternary {
                    then_expr,
                    else_expr,
                    ..
                } => {
                    let mut result = collect(then_expr, env, facts);
                    result.extend(collect(else_expr, env, facts));
                    result
                }
                _ => vec![],
            }
        }
        for member in &ty.members {
            match member {
                Member::Field(field) => {
                    if let Some(initializer) = &field.initializer {
                        // Source argument boundaries in initializers have no
                        // method usage record, just like the field result.
                        crate::semantic_analysis::walk_expr_outside_lambdas(
                            initializer,
                            &mut |expr| {
                                let (args, nodes): (&[Expr], Vec<SignatureDependencyNode>) =
                                    match expr {
                                        Expr::Call {
                                            args,
                                            resolved: Some(call),
                                            ..
                                        } => {
                                            let Some(method) =
                                                method_key_for_resolved_call(constraints, call)
                                            else {
                                                return;
                                            };
                                            let Some(params) = constraints.methods.get(&method)
                                            else {
                                                return;
                                            };
                                            (
                                                args,
                                                params
                                                    .param_names
                                                    .iter()
                                                    .enumerate()
                                                    .map(|(index, name)| {
                                                        SignatureDependencyNode::MethodParam {
                                                            method: method.clone(),
                                                            name: name.clone(),
                                                            index,
                                                        }
                                                    })
                                                    .collect(),
                                            )
                                        }
                                        Expr::New {
                                            args,
                                            resolved: Some(call),
                                            ..
                                        } => {
                                            let constructor =
                                                ConstructorKey::resolved_constructor(call);
                                            let Some(params) =
                                                constraints.constructors.get(&constructor)
                                            else {
                                                return;
                                            };
                                            (
                                                args,
                                                params
                                                    .param_names
                                                    .iter()
                                                    .enumerate()
                                                    .map(|(index, name)| {
                                                        SignatureDependencyNode::ConstructorParam {
                                                            constructor: constructor.clone(),
                                                            name: name.clone(),
                                                            index,
                                                        }
                                                    })
                                                    .collect(),
                                            )
                                        }
                                        _ => return,
                                    };
                                for (arg, node) in args.iter().zip(nodes) {
                                    for requirement in collect(arg, &env, facts) {
                                        pending.push((node.clone(), requirement));
                                    }
                                }
                            },
                        );
                        for requirement in collect(initializer, &env, facts) {
                            pending.push((
                                SignatureDependencyNode::Field {
                                    field: FieldKey::source_field(ty, field),
                                },
                                requirement,
                            ));
                        }
                    }
                }
                Member::Type(child) => fields(child, constraints, facts, pending),
                _ => {}
            }
        }
    }
    for ty in &program.types {
        fields(ty, constraints, facts, &mut pending);
    }
    for (node, requirement) in pending {
        add_collection_storage_constraint_scoped(constraints, &node, requirement, None);
    }
}

/// Initializers have no method-local usage record. Cache their resolved value
/// boundaries once, then use the same graph and scoped allocation propagation
/// as ordinary assignments/call results (including enum constructor arguments).
fn initializer_storage_edges(
    program: &Program,
    constraints: &SignatureConstraintState,
) -> Vec<(SignatureDependencyNode, SignatureDependencyNode)> {
    fn flow(
        expr: &Expr,
        target: &SignatureDependencyNode,
        constraints: &SignatureConstraintState,
        edges: &mut Vec<(SignatureDependencyNode, SignatureDependencyNode)>,
    ) {
        match expr {
            Expr::Call {
                resolved: Some(call),
                ..
            } => {
                if let Some(method) = method_key_for_resolved_call(constraints, call) {
                    edges.push((
                        target.clone(),
                        SignatureDependencyNode::MethodReturn { method },
                    ));
                }
            }
            Expr::Cast { expr, .. } => flow(expr, target, constraints, edges),
            Expr::Ternary {
                then_expr,
                else_expr,
                ..
            } => {
                flow(then_expr, target, constraints, edges);
                flow(else_expr, target, constraints, edges);
            }
            _ => {}
        }
    }
    fn collect(
        ty: &TypeDecl,
        constraints: &SignatureConstraintState,
        edges: &mut Vec<(SignatureDependencyNode, SignatureDependencyNode)>,
    ) {
        for member in &ty.members {
            match member {
                Member::Field(field) => {
                    let Some(initializer) = &field.initializer else {
                        continue;
                    };
                    let field = FieldKey::source_field(ty, field);
                    if constraints.fields.contains_key(&field) {
                        flow(
                            initializer,
                            &SignatureDependencyNode::Field { field },
                            constraints,
                            edges,
                        );
                    }
                    crate::semantic_analysis::walk_expr_outside_lambdas(initializer, &mut |expr| {
                        match expr {
                            Expr::New {
                                resolved: Some(call),
                                args,
                                ..
                            } => {
                                let constructor = ConstructorKey::resolved_constructor(call);
                                if let Some(set) = constraints.constructors.get(&constructor) {
                                    for (index, (argument, name)) in
                                        args.iter().zip(&set.param_names).enumerate()
                                    {
                                        flow(
                                            argument,
                                            &SignatureDependencyNode::ConstructorParam {
                                                constructor: constructor.clone(),
                                                name: name.clone(),
                                                index,
                                            },
                                            constraints,
                                            edges,
                                        );
                                    }
                                }
                            }
                            Expr::Call {
                                resolved: Some(call),
                                args,
                                ..
                            } => {
                                if let Some(method) =
                                    method_key_for_resolved_call(constraints, call)
                                    && let Some(set) = constraints.methods.get(&method)
                                {
                                    for (index, (argument, name)) in
                                        args.iter().zip(&set.param_names).enumerate()
                                    {
                                        flow(
                                            argument,
                                            &SignatureDependencyNode::MethodParam {
                                                method: method.clone(),
                                                name: name.clone(),
                                                index,
                                            },
                                            constraints,
                                            edges,
                                        );
                                    }
                                }
                            }
                            _ => {}
                        }
                    });
                }
                Member::Type(nested) => collect(nested, constraints, edges),
                _ => {}
            }
        }
    }
    let mut edges = Vec::new();
    for ty in &program.types {
        collect(ty, constraints, &mut edges);
    }
    let mut seen = HashSet::new();
    edges.retain(|edge| seen.insert(edge.clone()));
    edges
}

fn program_declared_source_type_names(program: &Program) -> HashSet<String> {
    let mut names = HashSet::new();
    for ty in &program.types {
        collect_declared_source_type_names(ty, &mut names);
    }
    names
}

fn collect_declared_source_type_names(ty: &TypeDecl, names: &mut HashSet<String>) {
    names.insert(ty.name.clone());
    names.insert(type_name_simple_segment(&ty.name).to_string());
    if let Some(source) = &ty.source_names {
        names.insert(source.canonical.clone());
        names.insert(source.binary.clone());
    }
    for member in &ty.members {
        collect_member_declared_source_type_names(member, names);
    }
}

fn collect_member_declared_source_type_names(
    member: &crate::java_ir::Member,
    names: &mut HashSet<String>,
) {
    match member {
        crate::java_ir::Member::Type(nested) => collect_declared_source_type_names(nested, names),
        crate::java_ir::Member::Method(method) => {
            if let Some(body) = &method.body {
                collect_declared_source_type_names_from_block(body, names);
            }
        }
        crate::java_ir::Member::Constructor(ctor) => {
            if let Some(body) = &ctor.body {
                collect_declared_source_type_names_from_block(body, names);
            }
        }
        crate::java_ir::Member::Field(_) | crate::java_ir::Member::Unsupported { .. } => {}
    }
}

fn collect_declared_source_type_names_from_block(block: &Block, names: &mut HashSet<String>) {
    for stmt in &block.statements {
        match stmt {
            Stmt::LocalType(local) => collect_declared_source_type_names(local, names),
            Stmt::Block(block) | Stmt::LabeledBlock { body: block, .. } => {
                collect_declared_source_type_names_from_block(block, names);
            }
            Stmt::If {
                then_block,
                else_block,
                ..
            } => {
                collect_declared_source_type_names_from_block(then_block, names);
                if let Some(else_block) = else_block {
                    collect_declared_source_type_names_from_block(else_block, names);
                }
            }
            Stmt::While { body, .. }
            | Stmt::DoWhile { body, .. }
            | Stmt::EnhancedFor { body, .. } => {
                collect_declared_source_type_names_from_block(body, names);
            }
            Stmt::For { init, body, .. } => {
                for stmt in init {
                    if let Stmt::LocalType(local) = stmt {
                        collect_declared_source_type_names(local, names);
                    }
                }
                collect_declared_source_type_names_from_block(body, names);
            }
            Stmt::Switch { cases, .. } => {
                for case in cases {
                    collect_declared_source_type_names_from_block(
                        &Block {
                            statements: case.statements.clone(),
                        },
                        names,
                    );
                }
            }
            Stmt::Try {
                resources,
                body,
                catches,
                finally_block,
            } => {
                for stmt in resources {
                    if let Stmt::LocalType(local) = stmt {
                        collect_declared_source_type_names(local, names);
                    }
                }
                collect_declared_source_type_names_from_block(body, names);
                for catch in catches {
                    collect_declared_source_type_names_from_block(&catch.body, names);
                }
                if let Some(finally_block) = finally_block {
                    collect_declared_source_type_names_from_block(finally_block, names);
                }
            }
            Stmt::VarDecl { .. }
            | Stmt::Expr(_)
            | Stmt::Assign { .. }
            | Stmt::Return(_)
            | Stmt::Throw(_)
            | Stmt::ConstructorInvocation { .. }
            | Stmt::Break(_)
            | Stmt::Continue(_)
            | Stmt::Unsupported(_) => {}
        }
    }
}

pub fn build_signature_dependency_graph(
    constraints: &SignatureConstraintState,
    usage: &UsageFacts,
) -> SignatureDependencyGraph {
    build_signature_dependency_graph_with_facts(constraints, usage, &FactSet::default())
}

pub fn build_signature_dependency_graph_with_facts(
    constraints: &SignatureConstraintState,
    usage: &UsageFacts,
    facts: &FactSet,
) -> SignatureDependencyGraph {
    let mut graph = SignatureDependencyGraph::default();
    add_signature_slot_nodes(constraints, &mut graph);
    add_method_usage_dependency_edges(constraints, usage, &mut graph);
    add_constructor_usage_dependency_edges(constraints, usage, &mut graph);
    for (source, target) in call_result_argument_nullability_edges(constraints, usage) {
        // Nullability flows from the produced reference to the receiving slot.
        // These are not alias edges or reverse type/ownership constraints.
        add_signature_dependency_edge(
            &mut graph,
            source,
            target,
            SignatureDependencyEdgeKind::CallArgument,
        );
    }
    for (source, target) in call_result_storage_edges(constraints, usage) {
        add_bidirectional_signature_dependency_edge(
            &mut graph,
            source,
            target,
            SignatureDependencyEdgeKind::CallResult,
        );
    }
    for (source, target) in collection_argument_storage_edges(constraints, usage) {
        add_bidirectional_signature_dependency_edge(
            &mut graph,
            source,
            target,
            SignatureDependencyEdgeKind::CallArgument,
        );
    }
    for ((source, _, _, _), (target, _, _, _), _, _) in
        collection_storage_edges(constraints, usage, CollectionStorageEdgeKind::All)
    {
        add_bidirectional_signature_dependency_edge(
            &mut graph,
            source,
            target,
            SignatureDependencyEdgeKind::FieldStorage,
        );
    }
    add_capture_dependency_nodes(constraints, facts, &mut graph);
    for edge in constraints.generic_allocation_edges.iter() {
        add_signature_dependency_edge(
            &mut graph,
            edge.source.clone(),
            edge.target.clone(),
            SignatureDependencyEdgeKind::FieldStorage,
        );
    }
    graph
}

pub fn analyze_signature_dependency_sccs(
    graph: &SignatureDependencyGraph,
) -> SignatureDependencySccAnalysis {
    let mut successors = HashMap::<SignatureDependencyNode, Vec<SignatureDependencyNode>>::new();
    for edge in graph.edges() {
        successors
            .entry(edge.from.clone())
            .or_default()
            .push(edge.to.clone());
    }

    let scc = strongly_connected_components(graph.nodes().iter().cloned(), |node| {
        successors.get(node).cloned().unwrap_or_default()
    });
    let stats = SignatureDependencySccStats::new(
        graph.nodes().len(),
        graph.edges().len(),
        scc.components().len(),
        scc.components()
            .iter()
            .filter(|component| {
                component.len() > 1
                    || component.first().is_some_and(|node| {
                        successors.get(node).is_some_and(|next| next.contains(node))
                    })
            })
            .count(),
        scc.components().iter().map(Vec::len).max().unwrap_or(0),
    );
    debug_assert_eq!(scc.component_successors().len(), scc.components().len());
    let (components, component_by_node, component_successors) = scc.into_parts();
    SignatureDependencySccAnalysis {
        components,
        component_successors,
        component_by_node,
        stats,
    }
}

pub fn plan_signature_solver_passes(
    analysis: &SignatureDependencySccAnalysis,
) -> SignatureSolverPassPlan {
    let mut order = Vec::new();
    let mut visited = HashSet::new();
    for component_index in 0..analysis.components.len() {
        push_signature_component_postorder(
            component_index,
            &analysis.component_successors,
            &mut visited,
            &mut order,
        );
    }
    order.reverse();

    let cyclic_components = analysis
        .components
        .iter()
        .enumerate()
        .filter_map(|(index, component)| {
            if component.len() > 1
                || component.first().is_some_and(|node| {
                    analysis
                        .component_by_node
                        .get(node)
                        .is_some_and(|component| *component == index)
                        && analysis.component_successors[index].contains(&index)
                })
            {
                Some(index)
            } else {
                None
            }
        })
        .collect::<HashSet<_>>();
    let mutable_components = analysis
        .components
        .iter()
        .enumerate()
        .filter_map(|(index, component)| {
            component
                .iter()
                .any(signature_dependency_node_stores_constraints)
                .then_some(index)
        })
        .collect::<HashSet<_>>();
    let stats = SignatureSolverPassStats::new(
        order.len(),
        mutable_components.len(),
        analysis.stats.cyclic_component_count(),
        analysis.stats.max_component_size(),
    );

    SignatureSolverPassPlan {
        component_order: order,
        cyclic_components,
        mutable_components,
        stats,
    }
}

fn signature_dependency_node_stores_constraints(node: &SignatureDependencyNode) -> bool {
    matches!(
        node,
        SignatureDependencyNode::MethodReceiver { .. }
            | SignatureDependencyNode::MethodParam { .. }
            | SignatureDependencyNode::MethodReturn { .. }
            | SignatureDependencyNode::MethodLocal { .. }
            | SignatureDependencyNode::ConstructorParam { .. }
            | SignatureDependencyNode::ConstructorLocal { .. }
            | SignatureDependencyNode::Field { .. }
    )
}

fn push_signature_component_postorder(
    component_index: usize,
    successors: &[Vec<usize>],
    visited: &mut HashSet<usize>,
    order: &mut Vec<usize>,
) {
    if !visited.insert(component_index) {
        return;
    }
    for successor in successors.get(component_index).into_iter().flatten() {
        push_signature_component_postorder(*successor, successors, visited, order);
    }
    order.push(component_index);
}

fn add_signature_slot_nodes(
    constraints: &SignatureConstraintState,
    graph: &mut SignatureDependencyGraph,
) {
    for (method, method_constraints) in &constraints.methods {
        add_signature_dependency_node(
            graph,
            SignatureDependencyNode::MethodReceiver {
                method: method.clone(),
            },
        );
        add_signature_dependency_node(
            graph,
            SignatureDependencyNode::MethodReturn {
                method: method.clone(),
            },
        );
        for (index, name) in method_constraints.param_names.iter().enumerate() {
            add_signature_dependency_node(
                graph,
                SignatureDependencyNode::MethodParam {
                    method: method.clone(),
                    name: name.clone(),
                    index,
                },
            );
        }
        for local in &method_constraints.locals {
            let precise = SignatureDependencyNode::MethodLocal {
                method: method.clone(),
                name: local.name.clone(),
                binding: Some(local.binding.clone()),
            };
            let legacy = SignatureDependencyNode::MethodLocal {
                method: method.clone(),
                name: local.name.clone(),
                binding: None,
            };
            add_signature_dependency_node(graph, precise.clone());
            add_signature_dependency_node(graph, legacy.clone());
            add_bidirectional_signature_dependency_edge(
                graph,
                precise,
                legacy,
                SignatureDependencyEdgeKind::LocalAlias,
            );
        }
    }
    for (constructor, constructor_constraints) in &constraints.constructors {
        for (index, name) in constructor_constraints.param_names.iter().enumerate() {
            add_signature_dependency_node(
                graph,
                SignatureDependencyNode::ConstructorParam {
                    constructor: constructor.clone(),
                    name: name.clone(),
                    index,
                },
            );
        }
        for local in &constructor_constraints.locals {
            let precise = SignatureDependencyNode::ConstructorLocal {
                constructor: constructor.clone(),
                name: local.name.clone(),
                binding: Some(local.binding.clone()),
            };
            let legacy = SignatureDependencyNode::ConstructorLocal {
                constructor: constructor.clone(),
                name: local.name.clone(),
                binding: None,
            };
            add_signature_dependency_node(graph, precise.clone());
            add_signature_dependency_node(graph, legacy.clone());
            add_bidirectional_signature_dependency_edge(
                graph,
                precise,
                legacy,
                SignatureDependencyEdgeKind::LocalAlias,
            );
        }
    }
    for field in constraints.fields.keys() {
        add_signature_dependency_node(
            graph,
            SignatureDependencyNode::Field {
                field: field.clone(),
            },
        );
    }
}

fn add_method_usage_dependency_edges(
    constraints: &SignatureConstraintState,
    usage: &UsageFacts,
    graph: &mut SignatureDependencyGraph,
) {
    for (usage_key, method_usage) in usage.method_entries() {
        let Some(method) = method_key_for_usage(constraints, usage_key) else {
            continue;
        };
        let caller = SignatureCallableKey::Method(method.clone());
        for (call_index, call_site) in method_usage.call_sites().iter().enumerate() {
            let callee =
                method_key_for_call_site_in_caller(constraints, call_site, method.type_name());
            let result = SignatureDependencyNode::CallResult {
                caller: caller.clone(),
                call_index,
            };
            add_signature_dependency_node(graph, result.clone());
            if call_site.boundary() == CallArgumentBoundary::Unknown && callee.is_none() {
                add_signature_dependency_edge(
                    graph,
                    SignatureDependencyNode::UnknownBoundaryResult {
                        caller: caller.clone(),
                        call_index,
                    },
                    result.clone(),
                    SignatureDependencyEdgeKind::UnknownBoundary,
                );
            }
            if let Some(callee) = callee {
                add_signature_dependency_edge(
                    graph,
                    SignatureDependencyNode::MethodReturn {
                        method: callee.clone(),
                    },
                    result,
                    SignatureDependencyEdgeKind::CallResult,
                );
                if call_site.receiver_is_self() || call_site.receiver_targets_self_field() {
                    add_signature_dependency_edge(
                        graph,
                        SignatureDependencyNode::MethodReceiver { method: callee },
                        SignatureDependencyNode::MethodReceiver {
                            method: method.clone(),
                        },
                        SignatureDependencyEdgeKind::Receiver,
                    );
                }
            }
        }
        add_method_binding_dependency_edges(constraints, method_usage, &method, &caller, graph);
        add_method_field_dependency_edges(method_usage, &method, &caller, graph);
        for returned in method_usage.returned_call_results() {
            for (call_index, call_site) in method_usage.call_sites().iter().enumerate() {
                if call_site.name() == returned.name()
                    && call_site.boundary() == returned.boundary()
                {
                    add_signature_dependency_edge(
                        graph,
                        SignatureDependencyNode::CallResult {
                            caller: caller.clone(),
                            call_index,
                        },
                        SignatureDependencyNode::MethodReturn {
                            method: method.clone(),
                        },
                        SignatureDependencyEdgeKind::CallResult,
                    );
                }
            }
        }
    }
}

fn add_constructor_usage_dependency_edges(
    constraints: &SignatureConstraintState,
    usage: &UsageFacts,
    graph: &mut SignatureDependencyGraph,
) {
    for (usage_key, constructor_usage) in usage.constructor_entries() {
        let constructor = ConstructorKey::from_usage_key(usage_key);
        if !constraints.constructors.contains_key(&constructor) {
            continue;
        }
        let caller = SignatureCallableKey::Constructor(constructor.clone());
        for (call_index, call_site) in constructor_usage.call_sites().iter().enumerate() {
            let callee = method_key_for_call_site(constraints, call_site);
            let result = SignatureDependencyNode::CallResult {
                caller: caller.clone(),
                call_index,
            };
            add_signature_dependency_node(graph, result.clone());
            if call_site.boundary() == CallArgumentBoundary::Unknown && callee.is_none() {
                add_signature_dependency_edge(
                    graph,
                    SignatureDependencyNode::UnknownBoundaryResult {
                        caller: caller.clone(),
                        call_index,
                    },
                    result.clone(),
                    SignatureDependencyEdgeKind::UnknownBoundary,
                );
            }
            if let Some(callee) = callee {
                add_signature_dependency_edge(
                    graph,
                    SignatureDependencyNode::MethodReturn { method: callee },
                    result,
                    SignatureDependencyEdgeKind::CallResult,
                );
            }
        }
        for (call_index, call_site) in constructor_usage
            .constructor_call_sites()
            .iter()
            .enumerate()
        {
            let call_index = constructor_call_dependency_index(constructor_usage, call_index);
            if let Some(resolved) = call_site.resolved() {
                for arg_index in 0..call_site.arg_count() {
                    add_signature_dependency_edge(
                        graph,
                        SignatureDependencyNode::CallArg {
                            caller: caller.clone(),
                            call_index,
                            arg_index,
                        },
                        SignatureDependencyNode::ConstructorParam {
                            constructor: ConstructorKey::resolved_constructor(resolved),
                            name: constructor_param_name_for_resolved(
                                constraints,
                                resolved,
                                arg_index,
                            ),
                            index: arg_index,
                        },
                        SignatureDependencyEdgeKind::ConstructorDelegationArgument,
                    );
                }
            }
        }
        add_constructor_binding_dependency_edges(
            constraints,
            constructor_usage,
            &constructor,
            &caller,
            graph,
        );
        add_constructor_field_dependency_edges(constructor_usage, &constructor, &caller, graph);
    }
}

fn add_capture_dependency_nodes(
    constraints: &SignatureConstraintState,
    facts: &FactSet,
    graph: &mut SignatureDependencyGraph,
) {
    for owner in &facts.captures.owners {
        let Some(callable) = capture_owner_callable(constraints, &owner.origin) else {
            continue;
        };
        for capture in &owner.captures {
            let captured = SignatureDependencyNode::CapturedValue {
                owner: callable.clone(),
                name: capture.name.clone(),
            };
            add_signature_dependency_node(graph, captured.clone());
            if let Some(source) = capture_source_dependency_node(
                constraints,
                &callable,
                &capture.name,
                capture.source,
            ) {
                add_bidirectional_signature_dependency_edge(
                    graph,
                    source,
                    captured,
                    SignatureDependencyEdgeKind::LocalAlias,
                );
            }
        }
    }
}

fn capture_owner_callable(
    constraints: &SignatureConstraintState,
    origin: &CaptureOrigin,
) -> Option<SignatureCallableKey> {
    match origin {
        CaptureOrigin::Method {
            type_name,
            method_name,
        } => method_key_for_usage(
            constraints,
            &UsageMethodKey::current_rust_method_name(type_name, method_name),
        )
        .map(SignatureCallableKey::Method),
        CaptureOrigin::Constructor { type_name } => constraints
            .constructors
            .keys()
            .find(|constructor| constructor.type_name() == *type_name)
            .cloned()
            .map(SignatureCallableKey::Constructor),
        CaptureOrigin::Type { .. } => None,
    }
}

fn capture_source_dependency_node(
    constraints: &SignatureConstraintState,
    callable: &SignatureCallableKey,
    name: &str,
    source: CaptureSource,
) -> Option<SignatureDependencyNode> {
    match (callable, source) {
        (SignatureCallableKey::Method(method), CaptureSource::Parameter | CaptureSource::Local) => {
            method_binding_dependency_node(constraints, method, name)
        }
        (SignatureCallableKey::Method(method), CaptureSource::ThisField) => {
            Some(SignatureDependencyNode::Field {
                field: FieldKey::rust_identity(method.type_name(), name.to_string()),
            })
        }
        (
            SignatureCallableKey::Constructor(constructor),
            CaptureSource::Parameter | CaptureSource::Local,
        ) => constructor_binding_dependency_node(constraints, constructor, name),
        (SignatureCallableKey::Constructor(constructor), CaptureSource::ThisField) => {
            Some(SignatureDependencyNode::Field {
                field: FieldKey::rust_identity(constructor.type_name(), name.to_string()),
            })
        }
        (_, CaptureSource::This | CaptureSource::OuterThis) => None,
    }
}

fn add_method_binding_dependency_edges(
    constraints: &SignatureConstraintState,
    method_usage: &MethodUsageFacts,
    method: &MethodKey,
    caller: &SignatureCallableKey,
    graph: &mut SignatureDependencyGraph,
) {
    for binding in method_usage.all_binding_facts() {
        let Some(binding_node) = method_binding_fact_dependency_node(constraints, method, binding)
        else {
            continue;
        };
        for use_site in binding.uses() {
            match use_site {
                BindingUse::AssignedToLocal {
                    local_name,
                    local_binding,
                } => {
                    let local = SignatureDependencyNode::MethodLocal {
                        method: method.clone(),
                        name: local_name.clone(),
                        binding: local_binding.clone(),
                    };
                    add_bidirectional_signature_dependency_edge(
                        graph,
                        binding_node.clone(),
                        local,
                        SignatureDependencyEdgeKind::LocalAlias,
                    );
                }
                BindingUse::PassedToCall {
                    name,
                    arg_index,
                    boundary,
                    ..
                } => {
                    for call_index in matching_method_call_indexes(method_usage, name, *boundary) {
                        add_call_argument_dependency_edges(
                            graph,
                            caller,
                            call_index,
                            *arg_index,
                            *boundary,
                            binding_node.clone(),
                            method_call_param_target(
                                constraints,
                                method_usage,
                                call_index,
                                *arg_index,
                            ),
                            SignatureDependencyEdgeKind::CallArgument,
                        );
                    }
                }
                BindingUse::ReceiverForCall { name, boundary, .. } => {
                    for call_index in matching_method_call_indexes(method_usage, name, *boundary) {
                        add_signature_dependency_edge(
                            graph,
                            binding_node.clone(),
                            SignatureDependencyNode::CallArg {
                                caller: caller.clone(),
                                call_index,
                                arg_index: usize::MAX,
                            },
                            SignatureDependencyEdgeKind::Receiver,
                        );
                    }
                }
                BindingUse::AssignedFromCall { name, boundary, .. } => {
                    for call_index in matching_method_call_indexes(method_usage, name, *boundary) {
                        add_signature_dependency_edge(
                            graph,
                            SignatureDependencyNode::CallResult {
                                caller: caller.clone(),
                                call_index,
                            },
                            binding_node.clone(),
                            SignatureDependencyEdgeKind::CallResult,
                        );
                    }
                }
                BindingUse::StoredInField { field_name } => {
                    add_bidirectional_signature_dependency_edge(
                        graph,
                        binding_node.clone(),
                        SignatureDependencyNode::Field {
                            field: FieldKey::rust_identity(method.type_name(), field_name.clone()),
                        },
                        SignatureDependencyEdgeKind::FieldStorage,
                    );
                }
                BindingUse::Returned => {
                    add_bidirectional_signature_dependency_edge(
                        graph,
                        binding_node.clone(),
                        SignatureDependencyNode::MethodReturn {
                            method: method.clone(),
                        },
                        SignatureDependencyEdgeKind::MethodReturn,
                    );
                }
                BindingUse::ReturnedNullableSequenceElements => {}
                BindingUse::ContentRead
                | BindingUse::RetainedByCall
                | BindingUse::IndexedElementComparedToNull { .. }
                | BindingUse::AssignedSubtypeToLocal { .. }
                | BindingUse::AssignedSubtypeToCollectionElement { .. }
                | BindingUse::AssignedSubtypeToCallArgument { .. }
                | BindingUse::CastTarget { .. }
                | BindingUse::InstanceOfTarget { .. }
                | BindingUse::Mutated => {}
            }
        }
    }
}

fn add_constructor_binding_dependency_edges(
    constraints: &SignatureConstraintState,
    constructor_usage: &MethodUsageFacts,
    constructor: &ConstructorKey,
    caller: &SignatureCallableKey,
    graph: &mut SignatureDependencyGraph,
) {
    for binding in constructor_usage.all_binding_facts() {
        let Some(binding_node) =
            constructor_binding_fact_dependency_node(constraints, constructor, binding)
        else {
            continue;
        };
        for use_site in binding.uses() {
            match use_site {
                BindingUse::AssignedToLocal {
                    local_name,
                    local_binding,
                } => {
                    let local = SignatureDependencyNode::ConstructorLocal {
                        constructor: constructor.clone(),
                        name: local_name.clone(),
                        binding: local_binding.clone(),
                    };
                    add_bidirectional_signature_dependency_edge(
                        graph,
                        binding_node.clone(),
                        local,
                        SignatureDependencyEdgeKind::LocalAlias,
                    );
                }
                BindingUse::PassedToCall {
                    name,
                    arg_index,
                    boundary,
                    ..
                } => {
                    for call_index in
                        matching_method_call_indexes(constructor_usage, name, *boundary)
                    {
                        add_call_argument_dependency_edges(
                            graph,
                            caller,
                            call_index,
                            *arg_index,
                            *boundary,
                            binding_node.clone(),
                            method_call_param_target(
                                constraints,
                                constructor_usage,
                                call_index,
                                *arg_index,
                            ),
                            SignatureDependencyEdgeKind::CallArgument,
                        );
                    }
                    for call_index in
                        matching_constructor_call_indexes(constructor_usage, name, *boundary)
                    {
                        add_call_argument_dependency_edges(
                            graph,
                            caller,
                            call_index,
                            *arg_index,
                            *boundary,
                            binding_node.clone(),
                            None,
                            SignatureDependencyEdgeKind::ConstructorDelegationArgument,
                        );
                    }
                }
                BindingUse::AssignedFromCall { name, boundary, .. } => {
                    for call_index in
                        matching_method_call_indexes(constructor_usage, name, *boundary)
                    {
                        add_signature_dependency_edge(
                            graph,
                            SignatureDependencyNode::CallResult {
                                caller: caller.clone(),
                                call_index,
                            },
                            binding_node.clone(),
                            SignatureDependencyEdgeKind::CallResult,
                        );
                    }
                }
                BindingUse::StoredInField { field_name } => {
                    add_bidirectional_signature_dependency_edge(
                        graph,
                        binding_node.clone(),
                        SignatureDependencyNode::Field {
                            field: FieldKey::rust_identity(
                                constructor.type_name(),
                                field_name.clone(),
                            ),
                        },
                        SignatureDependencyEdgeKind::FieldStorage,
                    );
                }
                BindingUse::ContentRead
                | BindingUse::RetainedByCall
                | BindingUse::IndexedElementComparedToNull { .. }
                | BindingUse::AssignedSubtypeToLocal { .. }
                | BindingUse::AssignedSubtypeToCollectionElement { .. }
                | BindingUse::AssignedSubtypeToCallArgument { .. }
                | BindingUse::CastTarget { .. }
                | BindingUse::InstanceOfTarget { .. }
                | BindingUse::ReceiverForCall { .. }
                | BindingUse::Returned
                | BindingUse::ReturnedNullableSequenceElements
                | BindingUse::Mutated => {}
            }
        }
    }
}

fn add_method_field_dependency_edges(
    method_usage: &MethodUsageFacts,
    method: &MethodKey,
    caller: &SignatureCallableKey,
    graph: &mut SignatureDependencyGraph,
) {
    for field_use in method_usage.field_uses() {
        match field_use {
            FieldUse::AssignedToLocal {
                field_name,
                local_name,
                local_binding,
            } => {
                add_bidirectional_signature_dependency_edge(
                    graph,
                    SignatureDependencyNode::Field {
                        field: FieldKey::rust_identity(method.type_name(), field_name.clone()),
                    },
                    SignatureDependencyNode::MethodLocal {
                        method: method.clone(),
                        name: local_name.clone(),
                        binding: local_binding.clone(),
                    },
                    SignatureDependencyEdgeKind::LocalAlias,
                );
            }
            FieldUse::AssignedSubtypeToField { .. }
            | FieldUse::AssignedSubtypeToCallArgument { .. }
            | FieldUse::AssignedSubtypeToReturn { .. }
            | FieldUse::AssignedSubtypeToCollectionElement { .. }
            | FieldUse::ReceiverForCall { .. } => {}
            FieldUse::AssignedFromCall {
                field_name,
                name,
                boundary,
                ..
            } => {
                for call_index in matching_method_call_indexes(method_usage, name, *boundary) {
                    add_signature_dependency_edge(
                        graph,
                        SignatureDependencyNode::CallResult {
                            caller: caller.clone(),
                            call_index,
                        },
                        SignatureDependencyNode::Field {
                            field: FieldKey::rust_identity(method.type_name(), field_name.clone()),
                        },
                        SignatureDependencyEdgeKind::CallResult,
                    );
                }
            }
            FieldUse::PassedToCall {
                field_name,
                name,
                arg_index,
                boundary,
                ..
            } => {
                let field = SignatureDependencyNode::Field {
                    field: FieldKey::rust_identity(method.type_name(), field_name.clone()),
                };
                for call_index in matching_method_call_indexes(method_usage, name, *boundary) {
                    add_call_argument_dependency_edges(
                        graph,
                        caller,
                        call_index,
                        *arg_index,
                        *boundary,
                        field.clone(),
                        None,
                        SignatureDependencyEdgeKind::CallArgument,
                    );
                }
            }
            FieldUse::Returned { field_name } => {
                add_bidirectional_signature_dependency_edge(
                    graph,
                    SignatureDependencyNode::Field {
                        field: FieldKey::rust_identity(method.type_name(), field_name.clone()),
                    },
                    SignatureDependencyNode::MethodReturn {
                        method: method.clone(),
                    },
                    SignatureDependencyEdgeKind::MethodReturn,
                );
            }
            FieldUse::ReturnedNullableSequenceElements { .. } => {}
        }
    }
}

fn add_constructor_field_dependency_edges(
    constructor_usage: &MethodUsageFacts,
    constructor: &ConstructorKey,
    caller: &SignatureCallableKey,
    graph: &mut SignatureDependencyGraph,
) {
    for field_use in constructor_usage.field_uses() {
        match field_use {
            FieldUse::AssignedToLocal {
                field_name,
                local_name,
                local_binding,
            } => {
                add_bidirectional_signature_dependency_edge(
                    graph,
                    SignatureDependencyNode::Field {
                        field: FieldKey::rust_identity(constructor.type_name(), field_name.clone()),
                    },
                    SignatureDependencyNode::ConstructorLocal {
                        constructor: constructor.clone(),
                        name: local_name.clone(),
                        binding: local_binding.clone(),
                    },
                    SignatureDependencyEdgeKind::LocalAlias,
                );
            }
            FieldUse::AssignedSubtypeToField { .. }
            | FieldUse::AssignedSubtypeToCallArgument { .. }
            | FieldUse::AssignedSubtypeToReturn { .. }
            | FieldUse::AssignedSubtypeToCollectionElement { .. }
            | FieldUse::ReceiverForCall { .. } => {}
            FieldUse::AssignedFromCall {
                field_name,
                name,
                boundary,
                ..
            } => {
                for call_index in matching_method_call_indexes(constructor_usage, name, *boundary) {
                    add_signature_dependency_edge(
                        graph,
                        SignatureDependencyNode::CallResult {
                            caller: caller.clone(),
                            call_index,
                        },
                        SignatureDependencyNode::Field {
                            field: FieldKey::rust_identity(
                                constructor.type_name(),
                                field_name.clone(),
                            ),
                        },
                        SignatureDependencyEdgeKind::CallResult,
                    );
                }
            }
            FieldUse::PassedToCall {
                field_name,
                name,
                arg_index,
                boundary,
                ..
            } => {
                let field = SignatureDependencyNode::Field {
                    field: FieldKey::rust_identity(constructor.type_name(), field_name.clone()),
                };
                for call_index in matching_method_call_indexes(constructor_usage, name, *boundary) {
                    add_call_argument_dependency_edges(
                        graph,
                        caller,
                        call_index,
                        *arg_index,
                        *boundary,
                        field.clone(),
                        None,
                        SignatureDependencyEdgeKind::CallArgument,
                    );
                }
            }
            FieldUse::Returned { .. } | FieldUse::ReturnedNullableSequenceElements { .. } => {}
        }
    }
}

fn add_call_argument_dependency_edges(
    graph: &mut SignatureDependencyGraph,
    caller: &SignatureCallableKey,
    call_index: usize,
    arg_index: usize,
    boundary: CallArgumentBoundary,
    source: SignatureDependencyNode,
    callee_param: Option<SignatureDependencyNode>,
    kind: SignatureDependencyEdgeKind,
) {
    let call_arg = SignatureDependencyNode::CallArg {
        caller: caller.clone(),
        call_index,
        arg_index,
    };
    add_signature_dependency_edge(graph, source.clone(), call_arg.clone(), kind);
    if boundary == CallArgumentBoundary::Unknown && callee_param.is_none() {
        add_signature_dependency_edge(
            graph,
            call_arg,
            SignatureDependencyNode::UnknownBoundaryArg {
                caller: caller.clone(),
                call_index,
                arg_index,
            },
            SignatureDependencyEdgeKind::UnknownBoundary,
        );
    } else if let Some(callee_param) = callee_param {
        // Argument contracts flow both ways: the callee learns storage from
        // its producer, and the producer must satisfy the callee's eventual
        // borrow/mutation capability. Without this reverse dependency an
        // acyclic caller component can finish before a forwarding callee is
        // widened, permanently leaving the caller at an obsolete shared ABI.
        add_signature_dependency_edge(graph, callee_param.clone(), source, kind);
        add_signature_dependency_edge(graph, call_arg, callee_param, kind);
    }
}

fn method_binding_dependency_node(
    constraints: &SignatureConstraintState,
    method: &MethodKey,
    binding_name: &str,
) -> Option<SignatureDependencyNode> {
    let method_constraints = constraints.methods.get(method)?;
    if let Some(index) = method_constraints.param_index(binding_name) {
        return Some(SignatureDependencyNode::MethodParam {
            method: method.clone(),
            name: binding_name.to_string(),
            index,
        });
    }
    if method_constraints
        .idless_compatibility_local(binding_name)
        .is_some()
    {
        return Some(SignatureDependencyNode::MethodLocal {
            method: method.clone(),
            name: binding_name.to_string(),
            binding: None,
        });
    }
    None
}

fn method_binding_fact_dependency_node(
    constraints: &SignatureConstraintState,
    method: &MethodKey,
    binding: &BindingUseFacts,
) -> Option<SignatureDependencyNode> {
    match binding.binding().map(|binding| binding.kind()) {
        Some(BindingKind::Param) => {
            let method_constraints = constraints.methods.get(method)?;
            let index = method_constraints.param_index(binding.name())?;
            Some(SignatureDependencyNode::MethodParam {
                method: method.clone(),
                name: binding.name().to_string(),
                index,
            })
        }
        Some(BindingKind::Local | BindingKind::LoopVariable | BindingKind::CatchParam) => {
            let local_binding = binding.binding()?;
            let method_constraints = constraints.methods.get(method)?;
            method_constraints.local_by_binding(local_binding)?;
            Some(SignatureDependencyNode::MethodLocal {
                method: method.clone(),
                name: binding.name().to_string(),
                binding: Some(local_binding.clone()),
            })
        }
        Some(BindingKind::Field | BindingKind::StaticField) | None => {
            method_binding_dependency_node(constraints, method, binding.name())
        }
    }
}

fn constructor_binding_dependency_node(
    constraints: &SignatureConstraintState,
    constructor: &ConstructorKey,
    binding_name: &str,
) -> Option<SignatureDependencyNode> {
    let constructor_constraints = constraints.constructors.get(constructor)?;
    if let Some(index) = constructor_constraints.param_index(binding_name) {
        return Some(SignatureDependencyNode::ConstructorParam {
            constructor: constructor.clone(),
            name: binding_name.to_string(),
            index,
        });
    }
    if constructor_constraints
        .idless_compatibility_local(binding_name)
        .is_some()
    {
        return Some(SignatureDependencyNode::ConstructorLocal {
            constructor: constructor.clone(),
            name: binding_name.to_string(),
            binding: None,
        });
    }
    None
}

fn constructor_binding_fact_dependency_node(
    constraints: &SignatureConstraintState,
    constructor: &ConstructorKey,
    binding: &BindingUseFacts,
) -> Option<SignatureDependencyNode> {
    match binding.binding().map(|binding| binding.kind()) {
        Some(BindingKind::Param) => {
            let constructor_constraints = constraints.constructors.get(constructor)?;
            let index = constructor_constraints.param_index(binding.name())?;
            Some(SignatureDependencyNode::ConstructorParam {
                constructor: constructor.clone(),
                name: binding.name().to_string(),
                index,
            })
        }
        Some(BindingKind::Local | BindingKind::LoopVariable | BindingKind::CatchParam) => {
            let local_binding = binding.binding()?;
            let constructor_constraints = constraints.constructors.get(constructor)?;
            constructor_constraints.local_by_binding(local_binding)?;
            Some(SignatureDependencyNode::ConstructorLocal {
                constructor: constructor.clone(),
                name: binding.name().to_string(),
                binding: Some(local_binding.clone()),
            })
        }
        Some(BindingKind::Field | BindingKind::StaticField) | None => {
            constructor_binding_dependency_node(constraints, constructor, binding.name())
        }
    }
}

fn method_call_param_target(
    constraints: &SignatureConstraintState,
    usage: &MethodUsageFacts,
    call_index: usize,
    arg_index: usize,
) -> Option<SignatureDependencyNode> {
    let call_site = usage.call_sites().get(call_index)?;
    let method = method_key_for_call_site(constraints, call_site)?;
    let name = constraints
        .methods
        .get(&method)?
        .param_names
        .get(arg_index)?
        .clone();
    Some(SignatureDependencyNode::MethodParam {
        method,
        name,
        index: arg_index,
    })
}

fn constructor_param_name_for_resolved(
    constraints: &SignatureConstraintState,
    resolved: &crate::java_ir::ResolvedConstructor,
    arg_index: usize,
) -> String {
    constraints
        .constructors
        .get(&ConstructorKey::resolved_constructor(resolved))
        .and_then(|constructor| constructor.param_names.get(arg_index))
        .cloned()
        .unwrap_or_else(|| format!("arg{arg_index}"))
}

fn matching_method_call_indexes(
    usage: &MethodUsageFacts,
    name: &str,
    boundary: CallArgumentBoundary,
) -> Vec<usize> {
    usage
        .call_sites()
        .iter()
        .enumerate()
        .filter(|(_, call_site)| call_site.name() == name && call_site.boundary() == boundary)
        .map(|(index, _)| index)
        .collect()
}

fn matching_constructor_call_indexes(
    usage: &MethodUsageFacts,
    name: &str,
    boundary: CallArgumentBoundary,
) -> Vec<usize> {
    usage
        .constructor_call_sites()
        .iter()
        .enumerate()
        .filter(|(_, call_site)| call_site.name() == name && call_site.boundary() == boundary)
        .map(|(index, _)| constructor_call_dependency_index(usage, index))
        .collect()
}

fn constructor_call_dependency_index(usage: &MethodUsageFacts, index: usize) -> usize {
    usage.call_sites().len() + index
}

fn add_signature_dependency_node(
    graph: &mut SignatureDependencyGraph,
    node: SignatureDependencyNode,
) {
    graph.nodes.insert(node);
}

fn add_signature_dependency_edge(
    graph: &mut SignatureDependencyGraph,
    from: SignatureDependencyNode,
    to: SignatureDependencyNode,
    kind: SignatureDependencyEdgeKind,
) {
    add_signature_dependency_node(graph, from.clone());
    add_signature_dependency_node(graph, to.clone());
    let edge = SignatureDependencyEdge::new(from, to, kind);
    if graph.edge_membership.insert(edge.clone()) {
        graph.edges.push(edge);
    }
}

fn add_bidirectional_signature_dependency_edge(
    graph: &mut SignatureDependencyGraph,
    left: SignatureDependencyNode,
    right: SignatureDependencyNode,
    kind: SignatureDependencyEdgeKind,
) {
    add_signature_dependency_edge(graph, left.clone(), right.clone(), kind);
    add_signature_dependency_edge(graph, right, left, kind);
}

pub fn solve_signature_constraints_to_fixpoint(
    constraints: SignatureConstraintState,
    usage: &UsageFacts,
) -> (SignatureConstraintState, usize) {
    let result = solve_signature_constraints_to_fixpoint_result(constraints, usage);
    let (constraints, iterations, _) = result.into_constraints_iterations_diagnostics();
    (constraints, iterations)
}

pub fn solve_signature_constraints_to_fixpoint_result(
    mut constraints: SignatureConstraintState,
    usage: &UsageFacts,
) -> SignatureFixpointResult {
    constraints.rebuild_method_lookup_index();
    let dependency_graph = build_signature_dependency_graph(&constraints, usage);
    let dependency_sccs = analyze_signature_dependency_sccs(&dependency_graph);
    let pass_plan = plan_signature_solver_passes(&dependency_sccs);
    let saturation_policy = signature_fixpoint_saturation_policy(&constraints);
    let result = saturation_policy.saturate(
        constraints,
        |constraints| {
            let changed = execute_global_signature_solver_sweep(constraints, usage);
            SaturationStep::from(changed)
        },
        |max_iterations| {
            SignatureDiagnostic::new(
                "signature_fixpoint_budget_exceeded",
                format!(
                "signature constraint fixpoint exceeded finite saturation budget of {max_iterations} iterations"
            ),
            )
        },
    );
    let (constraints, iterations, diagnostics) = result.into_parts();
    SignatureFixpointResult {
        constraints,
        iterations,
        diagnostics,
        dependency_sccs,
        pass_plan,
    }
}

pub fn signature_saturation_report(
    program: &Program,
    usage: &UsageFacts,
    facts: &FactSet,
) -> SignatureSaturationReport {
    let constraints = collect_signature_constraints(program, usage, facts);
    signature_saturation_report_for_constraints(constraints, usage)
}

pub fn signature_saturation_report_for_constraints(
    constraints: SignatureConstraintState,
    usage: &UsageFacts,
) -> SignatureSaturationReport {
    let domain_stats = signature_fixpoint_domain_stats(&constraints);
    let result = solve_signature_constraints_to_fixpoint_result(constraints, usage);
    let conflict_diagnostics =
        signature_constraint_state_conflict_diagnostics(result.constraints());
    SignatureSaturationReport::new(
        domain_stats,
        result.iterations(),
        result.diagnostics().len(),
        result.dependency_sccs().stats,
        result.pass_plan().stats(),
        conflict_diagnostics.len(),
        top_signature_constraint_provenance_counts(result.constraints(), 10),
        top_signature_conflict_axis_counts(&conflict_diagnostics, 10),
    )
}

pub fn signature_constraint_state_conflict_diagnostics(
    constraints: &SignatureConstraintState,
) -> Vec<SignatureConstraintConflictDiagnostic> {
    let mut diagnostics = Vec::new();
    for slot_constraints in signature_constraint_slots(constraints) {
        diagnostics.extend(
            MergedSignatureConstraints::from_constraints(slot_constraints).conflict_diagnostics(),
        );
    }
    diagnostics
}

fn top_signature_constraint_provenance_counts(
    constraints: &SignatureConstraintState,
    limit: usize,
) -> Vec<SignatureReportCount> {
    let mut counts = BTreeMap::<String, usize>::new();
    for slot_constraints in signature_constraint_slots(constraints) {
        for constraint in slot_constraints {
            let label =
                signature_constraint_provenance_label(signature_constraint_provenance(constraint));
            *counts.entry(label.to_string()).or_default() += 1;
        }
    }
    top_signature_report_counts(counts, limit)
}

fn top_signature_conflict_axis_counts(
    diagnostics: &[SignatureConstraintConflictDiagnostic],
    limit: usize,
) -> Vec<SignatureReportCount> {
    let mut counts = BTreeMap::<String, usize>::new();
    for diagnostic in diagnostics {
        *counts
            .entry(format!("{:?}", diagnostic.axis()))
            .or_default() += 1;
    }
    top_signature_report_counts(counts, limit)
}

fn top_signature_report_counts(
    counts: BTreeMap<String, usize>,
    limit: usize,
) -> Vec<SignatureReportCount> {
    let mut counts = counts
        .into_iter()
        .map(|(label, count)| SignatureReportCount::new(label, count))
        .collect::<Vec<_>>();
    counts.sort_by(|left, right| {
        right
            .count()
            .cmp(&left.count())
            .then_with(|| left.label().cmp(right.label()))
    });
    counts.truncate(limit);
    counts
}

#[cfg(test)]
fn execute_signature_solver_pass_plan(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    analysis: &SignatureDependencySccAnalysis,
    pass_plan: &SignatureSolverPassPlan,
) -> bool {
    execute_signature_solver_pass_plan_with_stats(constraints, usage, analysis, pass_plan, None).0
}

/// Apply one monotone propagation sweep over the complete constraint state.
///
/// The SCC pass plan remains useful for dependency diagnostics, but its
/// mutation scope does not currently index the usage facts consumed by each
/// propagation arm. Running every arm once per mutable SCC therefore rescans
/// the complete program thousands of times. The outer finite-saturation loop
/// already repeats until the same least fixpoint is reached, so one global
/// sweep per iteration preserves the solver semantics without those redundant
/// scans.
fn execute_global_signature_solver_sweep(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
) -> bool {
    execute_global_signature_solver_sweep_with_stats(constraints, usage).0
}

fn execute_global_signature_solver_sweep_with_stats(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
) -> (bool, SignatureSolverExecutionStats) {
    let before = constraints.clone();
    let propagation_start = std::time::Instant::now();
    let (reported_changed, propagation_arms) =
        apply_signature_propagation_sweep_with_stats(constraints, usage, None);
    let mut stats = SignatureSolverExecutionStats {
        component_sweeps: 1,
        state_clones: 1,
        propagation_sweep_ms: propagation_start.elapsed().as_millis(),
        propagation_arms,
        ..SignatureSolverExecutionStats::default()
    };
    let changed = reported_changed && *constraints != before;
    if changed {
        stats.changed_component_sweeps = 1;
    }
    (changed, stats)
}

#[derive(Clone, Copy)]
#[cfg(test)]
struct SignatureSolverPassProgress<'a> {
    progress_sink: Option<SignatureSolverProgressSink<'a>>,
    fixpoint_start: std::time::Instant,
    iteration: usize,
}

#[cfg(test)]
fn execute_signature_solver_pass_plan_with_stats(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    analysis: &SignatureDependencySccAnalysis,
    pass_plan: &SignatureSolverPassPlan,
    progress: Option<SignatureSolverPassProgress<'_>>,
) -> (bool, SignatureSolverExecutionStats) {
    let mut changed = false;
    let mut stats = SignatureSolverExecutionStats::default();
    let mut mutable_component_count = 0usize;
    let total_mutable_components = pass_plan.mutable_components().len();
    for component_index in pass_plan.component_order() {
        if !pass_plan.mutable_components().contains(component_index) {
            continue;
        }
        mutable_component_count += 1;
        if let Some(progress) = progress
            && (mutable_component_count == 1
                || mutable_component_count % 250 == 0
                || mutable_component_count == total_mutable_components)
        {
            emit_signature_solver_progress(
                progress.progress_sink,
                "fixpoint_component",
                "running",
                progress.fixpoint_start.elapsed().as_millis(),
                &format!(
                    "iteration={} component={}/{} scc={}",
                    progress.iteration,
                    mutable_component_count,
                    total_mutable_components,
                    component_index
                ),
            );
        }
        let mut component_changed = true;
        while component_changed {
            stats.component_sweeps += 1;
            if let Some(progress) = progress
                && (stats.component_sweeps == 1 || stats.component_sweeps % 500 == 0)
            {
                emit_signature_solver_progress(
                    progress.progress_sink,
                    "fixpoint_component_sweep",
                    "running",
                    progress.fixpoint_start.elapsed().as_millis(),
                    &format!(
                        "iteration={} component_sweeps={} current_scc={}",
                        progress.iteration, stats.component_sweeps, component_index
                    ),
                );
            }
            let clone_start = std::time::Instant::now();
            let before = constraints.clone();
            stats.state_clones += 1;
            stats.state_clone_ms += clone_start.elapsed().as_millis();
            let propagation_start = std::time::Instant::now();
            let scope = SignatureMutationScope {
                analysis,
                component_index: *component_index,
            };
            let (reported_changed, propagation_stats) =
                apply_signature_propagation_sweep_with_stats(constraints, usage, Some(scope));
            stats.propagation_sweep_ms += propagation_start.elapsed().as_millis();
            stats.add_propagation_arm_stats(&propagation_stats);
            let check_start = std::time::Instant::now();
            component_changed = reported_changed && *constraints != before;
            stats.component_change_check_ms += check_start.elapsed().as_millis();
            if component_changed {
                stats.changed_component_sweeps += 1;
            }
            changed |= component_changed;
            if !pass_plan.cyclic_components().contains(component_index) {
                break;
            }
        }
    }
    (changed, stats)
}

#[derive(Debug, Clone, Copy)]
struct SignatureMutationScope<'a> {
    analysis: &'a SignatureDependencySccAnalysis,
    component_index: usize,
}

impl SignatureMutationScope<'_> {
    fn permits(&self, node: &SignatureDependencyNode) -> bool {
        self.analysis
            .component_by_node
            .get(node)
            .is_some_and(|actual| *actual == self.component_index)
    }

    fn has_method_binding_target(&self) -> bool {
        self.analysis.components[self.component_index]
            .iter()
            .any(|node| {
                matches!(
                    node,
                    SignatureDependencyNode::MethodParam { .. }
                        | SignatureDependencyNode::MethodLocal { .. }
                )
            })
    }

    fn has_method_receiver_target(&self) -> bool {
        self.analysis.components[self.component_index]
            .iter()
            .any(|node| matches!(node, SignatureDependencyNode::MethodReceiver { .. }))
    }

    fn has_constructor_binding_target(&self) -> bool {
        self.analysis.components[self.component_index]
            .iter()
            .any(|node| {
                matches!(
                    node,
                    SignatureDependencyNode::ConstructorParam { .. }
                        | SignatureDependencyNode::ConstructorLocal { .. }
                )
            })
    }

    fn has_method_local_target(&self) -> bool {
        self.analysis.components[self.component_index]
            .iter()
            .any(|node| matches!(node, SignatureDependencyNode::MethodLocal { .. }))
    }

    fn has_constructor_local_target(&self) -> bool {
        self.analysis.components[self.component_index]
            .iter()
            .any(|node| matches!(node, SignatureDependencyNode::ConstructorLocal { .. }))
    }

    fn has_method_return_target(&self) -> bool {
        self.analysis.components[self.component_index]
            .iter()
            .any(|node| matches!(node, SignatureDependencyNode::MethodReturn { .. }))
    }

    fn has_field_target(&self) -> bool {
        self.analysis.components[self.component_index]
            .iter()
            .any(|node| matches!(node, SignatureDependencyNode::Field { .. }))
    }
}

fn scope_permits_method_local_target(
    constraints: &SignatureConstraintState,
    scope: Option<SignatureMutationScope<'_>>,
    method_key: &MethodKey,
    local_name: &str,
) -> bool {
    let Some(scope) = scope else {
        return true;
    };
    if constraints
        .methods
        .get(method_key)
        .and_then(|method_constraints| method_constraints.idless_compatibility_local(local_name))
        .is_none()
    {
        return false;
    }
    scope.permits(&SignatureDependencyNode::MethodLocal {
        method: method_key.clone(),
        name: local_name.to_string(),
        binding: None,
    })
}

fn scope_permits_method_return_target(
    scope: Option<SignatureMutationScope<'_>>,
    method_key: &MethodKey,
) -> bool {
    scope.is_none_or(|scope| {
        scope.permits(&SignatureDependencyNode::MethodReturn {
            method: method_key.clone(),
        })
    })
}

fn scope_permits_constructor_local_target(
    constraints: &SignatureConstraintState,
    scope: Option<SignatureMutationScope<'_>>,
    constructor_key: &ConstructorKey,
    local_name: &str,
) -> bool {
    let Some(scope) = scope else {
        return true;
    };
    if constraints
        .constructors
        .get(constructor_key)
        .and_then(|constructor_constraints| {
            constructor_constraints.idless_compatibility_local(local_name)
        })
        .is_none()
    {
        return false;
    }
    scope.permits(&SignatureDependencyNode::ConstructorLocal {
        constructor: constructor_key.clone(),
        name: local_name.to_string(),
        binding: None,
    })
}

fn scope_permits_field_target(
    scope: Option<SignatureMutationScope<'_>>,
    type_name: &str,
    field_name: &str,
) -> bool {
    scope.is_none_or(|scope| {
        scope.permits(&SignatureDependencyNode::Field {
            field: FieldKey::rust_identity(type_name.to_string(), field_name.to_string()),
        })
    })
}

fn apply_signature_propagation_sweep_with_stats(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> (bool, BTreeMap<String, SignaturePropagationArmProfile>) {
    let mut stats = BTreeMap::new();
    let changed =
        record_signature_propagation_arm(&mut stats, "call_site", || {
            propagate_call_site_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "constructor_call_site", || {
            propagate_constructor_call_site_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(
            &mut stats,
            "resolved_source_mutable_argument_binding",
            || {
                propagate_resolved_source_mutable_argument_binding_constraints(
                    constraints,
                    usage,
                    scope,
                )
            },
        ) | record_signature_propagation_arm(
            &mut stats,
            "resolved_source_mutable_receiver_binding",
            || {
                propagate_resolved_source_mutable_receiver_binding_constraints(
                    constraints,
                    usage,
                    scope,
                )
            },
        ) | record_signature_propagation_arm(&mut stats, "constructor_delegation", || {
            propagate_constructor_delegation_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "call_argument_to_callee", || {
            propagate_call_argument_constraints_to_callees(constraints, usage, scope)
        }) | record_signature_propagation_arm(
            &mut stats,
            "call_result_argument_nullability",
            || propagate_call_result_argument_nullability(constraints, usage, scope),
        ) | record_signature_propagation_arm(
            &mut stats,
            "call_argument_collection_carrier_to_callee",
            || {
                propagate_call_argument_collection_carrier_java_types_to_callees(
                    constraints,
                    usage,
                    scope,
                )
            },
        ) | record_signature_propagation_arm(
            &mut stats,
            "constructor_argument_collection_carrier_to_callee",
            || {
                propagate_constructor_argument_collection_carrier_java_types_to_callees(
                    constraints,
                    usage,
                    scope,
                )
            },
        ) | record_signature_propagation_arm(
            &mut stats,
            "constructor_call_argument_to_callee",
            || {
                propagate_constructor_call_argument_constraints_to_callees(
                    constraints,
                    usage,
                    scope,
                )
            },
        ) | record_signature_propagation_arm(
            &mut stats,
            "constructor_delegation_argument_to_callee",
            || {
                propagate_constructor_delegation_argument_constraints_to_callees(
                    constraints,
                    usage,
                    scope,
                )
            },
        ) | record_signature_propagation_arm(&mut stats, "null_call_argument_to_callee", || {
            propagate_null_call_argument_constraints_to_callees(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "nullable_map_key_carrier", || {
            propagate_nullable_map_key_carriers(constraints, usage, scope)
        }) | record_signature_propagation_arm(
            &mut stats,
            "nullable_collection_element_carrier",
            || propagate_nullable_collection_element_carriers(constraints, usage, scope),
        ) | record_signature_propagation_arm(
            &mut stats,
            "nested_nullable_collection_element_carrier",
            || propagate_nested_nullable_collection_element_carriers(constraints, usage, scope),
        ) | record_signature_propagation_arm(
            &mut stats,
            "collection_argument_origin_storage",
            || propagate_collection_argument_origin_storage(constraints, usage, scope),
        ) | record_signature_propagation_arm(
            &mut stats,
            "collection_element_transfer_nullability",
            || propagate_collection_element_transfer_nullability(constraints, usage, scope),
        ) | record_signature_propagation_arm(&mut stats, "call_result_to_binding", || {
            propagate_call_result_constraints_to_bindings(constraints, usage, scope)
        }) | record_signature_propagation_arm(
            &mut stats,
            "assigned_call_native_allocation",
            || propagate_assigned_call_native_allocation(constraints, usage, scope),
        ) | record_signature_propagation_arm(
            &mut stats,
            "native_collection_child_allocation",
            || propagate_native_collection_child_allocations(constraints, usage, scope),
        ) | record_signature_propagation_arm(&mut stats, "source_generic_allocation", || {
            propagate_source_generic_allocations(constraints, scope)
        }) | record_signature_propagation_arm(
            &mut stats,
            "constructor_call_result_to_binding",
            || propagate_constructor_call_result_constraints_to_bindings(constraints, usage, scope),
        ) | record_signature_propagation_arm(&mut stats, "call_result_to_field", || {
            propagate_call_result_constraints_to_fields(constraints, usage, scope)
        }) | record_signature_propagation_arm(
            &mut stats,
            "constructor_call_result_to_field",
            || propagate_constructor_call_result_constraints_to_fields(constraints, usage, scope),
        ) | record_signature_propagation_arm(&mut stats, "call_result_to_return", || {
            propagate_call_result_constraints_to_returns(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "method_field_storage", || {
            propagate_method_field_storage_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "constructor_field_storage", || {
            propagate_constructor_field_storage_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "method_field_local_alias", || {
            propagate_method_field_local_alias_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "constructor_field_local_alias", || {
            propagate_constructor_field_local_alias_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "method_local_alias", || {
            propagate_method_local_alias_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "method_local_alias_source", || {
            propagate_method_local_alias_source_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "constructor_local_alias", || {
            propagate_constructor_local_alias_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "constructor_local_alias_source", || {
            propagate_constructor_local_alias_source_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(
            &mut stats,
            "method_binding_field_nullability",
            || propagate_method_binding_field_nullability(constraints, usage, scope),
        ) | record_signature_propagation_arm(
            &mut stats,
            "constructor_binding_field_nullability",
            || propagate_constructor_binding_field_nullability(constraints, usage, scope),
        ) | record_signature_propagation_arm(&mut stats, "method_return_binding", || {
            propagate_method_return_binding_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "method_binding_return", || {
            propagate_method_binding_return_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "method_return_field", || {
            propagate_method_return_field_constraints(constraints, usage, scope)
        }) | record_signature_propagation_arm(&mut stats, "method_field_return", || {
            propagate_method_field_return_constraints(constraints, usage, scope)
        });
    (changed, stats)
}

fn record_signature_propagation_arm(
    stats: &mut BTreeMap<String, SignaturePropagationArmProfile>,
    label: &str,
    propagate: impl FnOnce() -> bool,
) -> bool {
    let start = std::time::Instant::now();
    let changed = propagate();
    let arm = stats.entry(label.to_string()).or_default();
    arm.record_sweep(changed, start.elapsed().as_nanos());
    changed
}

pub fn signature_fixpoint_saturation_policy(
    constraints: &SignatureConstraintState,
) -> FiniteSaturationPolicy {
    let slot_count = signature_constraint_slot_count(constraints);
    let unique_constraint_count = unique_signature_constraints(constraints).len();
    FiniteSaturationPolicy::new(slot_count, unique_constraint_count)
}

pub fn signature_fixpoint_iteration_budget(constraints: &SignatureConstraintState) -> usize {
    signature_fixpoint_saturation_policy(constraints).iteration_budget()
}

pub fn signature_fixpoint_domain_stats(
    constraints: &SignatureConstraintState,
) -> SignatureFixpointDomainStats {
    let slot_count = signature_constraint_slot_count(constraints);
    let unique_constraint_count = unique_signature_constraints(constraints).len();
    let iteration_budget =
        FiniteSaturationPolicy::new(slot_count, unique_constraint_count).iteration_budget();
    SignatureFixpointDomainStats::new(slot_count, unique_constraint_count, iteration_budget)
}

fn signature_constraint_slot_count(constraints: &SignatureConstraintState) -> usize {
    signature_constraint_slots(constraints).len()
}

fn unique_signature_constraints(
    constraints: &SignatureConstraintState,
) -> Vec<SignatureConstraint> {
    let mut unique = Vec::new();
    for slot_constraints in signature_constraint_slots(constraints) {
        push_unique_signature_constraints(&mut unique, slot_constraints);
    }
    unique
}

fn signature_constraint_slots(
    constraints: &SignatureConstraintState,
) -> Vec<&Vec<SignatureConstraint>> {
    let mut slots = Vec::new();
    for method in constraints.methods.values() {
        slots.extend(method.params.iter());
        slots.push(&method.return_constraints);
        slots.extend(method.locals.iter().map(|local| &local.constraints));
    }
    for constructor in constraints.constructors.values() {
        slots.extend(constructor.params.iter());
        slots.extend(constructor.locals.iter().map(|local| &local.constraints));
    }
    slots.extend(constraints.fields.values());
    slots
}

fn push_unique_signature_constraints(
    unique: &mut Vec<SignatureConstraint>,
    constraints: &[SignatureConstraint],
) {
    for constraint in constraints {
        if !unique.contains(constraint) {
            unique.push(constraint.clone());
        }
    }
}

/// Nullability is part of a Java override slot's value domain. Join it across
/// the declaration and every implementation on every fixpoint iteration, just
/// as fallibility is equalized across the same groups. Ownership and view
/// constraints intentionally remain local: generated trait adapters can bridge
/// `String`/`&str` and `Vec<T>`/`&[T]`, but they cannot safely erase `null`.
/// Native allocation qualifiers also join at proven native storage paths:
/// adapters cannot bridge those by copying without changing Java aliases.
#[derive(Debug, Clone)]
struct SourceOverrideConstraintGroup {
    keys: Vec<MethodKey>,
    group_has_interface: bool,
    interface_keys: HashSet<MethodKey>,
}

#[derive(Debug, Clone, Default)]
struct SourceOverrideConstraintTopology {
    groups: Vec<SourceOverrideConstraintGroup>,
    native_slots: HashMap<MethodKey, SourceOverrideNativeSlots>,
}

#[derive(Debug, Clone, Default)]
struct SourceOverrideNativeSlots {
    returned: SourceOverrideNativePaths,
    params: Vec<SourceOverrideNativePaths>,
}

#[derive(Debug, Clone, Default)]
struct SourceOverrideNativePaths {
    native: HashSet<Vec<usize>>,
    type_variables: HashSet<Vec<usize>>,
}

impl SourceOverrideNativePaths {
    fn contains(&self, path: &[usize]) -> bool {
        self.native.contains(path)
            || self
                .type_variables
                .iter()
                .any(|root| path.starts_with(root))
    }
}

fn source_override_native_paths(
    ty: &JavaType,
    facts: &FactSet,
    type_params: &[String],
) -> SourceOverrideNativePaths {
    fn visit(
        ty: &JavaType,
        path: &mut Vec<usize>,
        facts: &FactSet,
        type_params: &[String],
        paths: &mut SourceOverrideNativePaths,
    ) {
        let ty = optional_element_type(ty).unwrap_or_else(|| ty.clone());
        match &ty {
            JavaType::Array(element) => {
                paths.native.insert(path.clone());
                path.push(0);
                visit(element, path, facts, type_params, paths);
                path.pop();
            }
            JavaType::Named { args, .. }
                if crate::stdlib::java_collection_kind_for_type(&ty).is_some()
                    && !EffectiveFacts::new(facts).parsed_source_controls_native_carrier(&ty) =>
            {
                paths.native.insert(path.clone());
                for (index, arg) in args.iter().enumerate() {
                    path.push(index);
                    visit(arg, path, facts, type_params, paths);
                    path.pop();
                }
            }
            JavaType::Named { .. }
                if EffectiveFacts::new(facts)
                    .native_functional_carrier(&ty)
                    .is_some() =>
            {
                paths.native.insert(path.clone());
            }
            JavaType::Named { name, args } if args.is_empty() && type_params.contains(name) => {
                // Specialization can make this value (or a child below it)
                // a native allocation. Keep the declaration's physical
                // requirement in the same override join as its implementors.
                // Concrete non-native slots still reject these qualifiers.
                paths.type_variables.insert(path.clone());
            }
            _ => {}
        }
    }
    let mut paths = SourceOverrideNativePaths::default();
    visit(ty, &mut Vec::new(), facts, type_params, &mut paths);
    paths
}

fn override_slot_constraint(
    constraint: &SignatureConstraint,
    paths: Option<&SourceOverrideNativePaths>,
) -> bool {
    if override_nullability_constraint(constraint) {
        return true;
    }
    let path = match constraint {
        SignatureConstraint::RequiredNativeAllocation(_) => &[][..],
        SignatureConstraint::RequiredNestedNativeAllocation { path, .. } => path.as_slice(),
        _ => return false,
    };
    paths.is_some_and(|paths| paths.contains(path))
}

/// Build the immutable relationships used while joining source override
/// constraints. The saturation loop changes slot facts, but not method
/// identity, hierarchy membership, or generic interface implementations.
fn build_source_override_constraint_topology(
    constraints: &SignatureConstraintState,
    program: &Program,
    facts: &FactSet,
) -> SourceOverrideConstraintTopology {
    fn collect(
        ty: &TypeDecl,
        constraints: &SignatureConstraintState,
        facts: &FactSet,
        slots: &mut HashMap<MethodKey, SourceOverrideNativeSlots>,
    ) {
        for member in &ty.members {
            match member {
                Member::Method(method) => {
                    let key = MethodKey::source_method(ty, method);
                    if constraints.methods.contains_key(&key) {
                        let type_params = ty
                            .type_params
                            .iter()
                            .chain(&method.type_params)
                            .cloned()
                            .collect::<Vec<_>>();
                        slots.insert(
                            key,
                            SourceOverrideNativeSlots {
                                returned: source_override_native_paths(
                                    &method.return_type,
                                    facts,
                                    &type_params,
                                ),
                                params: method
                                    .params
                                    .iter()
                                    .map(|param| {
                                        source_override_native_paths(&param.ty, facts, &type_params)
                                    })
                                    .collect(),
                            },
                        );
                    }
                }
                Member::Type(nested) => collect(nested, constraints, facts, slots),
                _ => {}
            }
        }
    }
    let mut native_slots = HashMap::new();
    for ty in &program.types {
        collect(ty, constraints, facts, &mut native_slots);
    }
    let mut groups = Vec::new();
    for group in crate::exception_plan::override_groups_for_program(program) {
        let group_has_interface = group.iter().any(|callable| {
            callable
                .method_identity_parts()
                .and_then(|(owner, _)| find_signature_type_decl(program, owner))
                .is_some_and(|ty| ty.kind == TypeKind::Interface)
        });
        let keys = group
            .iter()
            .filter_map(|callable| callable.method_identity_parts())
            .map(|(owner, rust_name)| MethodKey::rust_identity(owner, rust_name))
            .filter(|key| constraints.methods.contains_key(key))
            .collect::<Vec<_>>();
        if keys.len() < 2 {
            continue;
        }
        let interface_keys = keys
            .iter()
            .filter(|key| {
                find_signature_type_decl(program, key.type_name())
                    .is_some_and(|ty| ty.kind == TypeKind::Interface)
            })
            .cloned()
            .collect::<HashSet<_>>();
        groups.push(SourceOverrideConstraintGroup {
            keys,
            group_has_interface,
            interface_keys,
        });
    }

    let interface_implementations = constraints
        .methods
        .keys()
        .filter_map(|key| {
            let interface = find_signature_type_decl(program, key.type_name())?;
            if interface.kind != TypeKind::Interface {
                return None;
            }
            let interface_method = interface.members.iter().find_map(|member| {
                let Member::Method(method) = member else {
                    return None;
                };
                (crate::java_signature::source_method_rust_name(method) == key.rust_name)
                    .then_some(method)
            })?;
            let implementations =
                crate::representation_lowering::source_interface_method_implementations(
                    interface,
                    interface_method,
                    program,
                )
                .into_iter()
                .map(|(owner, method)| {
                    MethodKey::rust_identity(
                        &owner.name,
                        crate::java_signature::source_method_rust_name(method),
                    )
                })
                .filter(|implementation_key| constraints.methods.contains_key(implementation_key))
                .collect::<Vec<_>>();
            Some((key.clone(), implementations))
        })
        .collect::<Vec<_>>();

    // Generic implementations can have different erased Java spellings from
    // their interface declaration (T versus String). They still share the
    // same null-capable value domain. Feed the already-specialized source
    // implementation relation into the ordinary override join, rather than
    // widening the emitted trait only after callers have been solved.
    for (interface_key, implementations) in interface_implementations {
        let mut keys = vec![interface_key];
        keys.extend(implementations);
        keys.sort_by(|left, right| {
            left.type_name()
                .cmp(right.type_name())
                .then_with(|| left.rust_name.cmp(&right.rust_name))
        });
        keys.dedup();
        if keys.len() < 2 {
            continue;
        }
        let interface_keys = keys
            .iter()
            .filter(|key| {
                find_signature_type_decl(program, key.type_name())
                    .is_some_and(|ty| ty.kind == TypeKind::Interface)
            })
            .cloned()
            .collect();
        groups.push(SourceOverrideConstraintGroup {
            keys,
            group_has_interface: true,
            interface_keys,
        });
    }
    let mut seen = HashSet::new();
    groups.retain_mut(|group| {
        group.keys.sort_by(|left, right| {
            left.type_name()
                .cmp(right.type_name())
                .then_with(|| left.rust_name.cmp(&right.rust_name))
        });
        seen.insert(group.keys.clone())
    });
    SourceOverrideConstraintTopology {
        groups,
        native_slots,
    }
}

fn equalize_source_override_nullability_constraints_with_topology(
    constraints: &mut SignatureConstraintState,
    topology: &SourceOverrideConstraintTopology,
) -> bool {
    let mut changed = false;
    for group in &topology.groups {
        let mut return_constraints = Vec::new();
        // Concrete class overrides share one physical receiver representation,
        // so a mutating override must widen the class hierarchy slot.  An
        // interface, however, is emitted as a Rust trait: its adapter can widen
        // the trait receiver to `&mut self` while a read-only concrete method
        // keeps `&self`.  Widening every concrete interface implementation made
        // otherwise read-only Java methods unusable from `toString`/Display.
        let mutable_receiver = group.keys.iter().any(|key| {
            constraints.methods.get(key).is_some_and(|method| {
                method
                    .receiver
                    .contains(&ReceiverConstraint::MutableReceiver)
            })
        });
        let max_params = group
            .keys
            .iter()
            .filter_map(|key| constraints.methods.get(key))
            .map(|method| method.params.len())
            .max()
            .unwrap_or(0);
        let mut param_constraints = vec![Vec::new(); max_params];
        for key in &group.keys {
            let method = constraints
                .methods
                .get(key)
                .expect("filtered source override method");
            push_unique_signature_constraints(
                &mut return_constraints,
                &method
                    .return_constraints
                    .iter()
                    .filter(|constraint| {
                        override_slot_constraint(
                            constraint,
                            topology.native_slots.get(key).map(|slots| &slots.returned),
                        )
                    })
                    .cloned()
                    .collect::<Vec<_>>(),
            );
            for (index, slot) in method.params.iter().enumerate() {
                push_unique_signature_constraints(
                    &mut param_constraints[index],
                    &slot
                        .iter()
                        .filter(|constraint| {
                            override_slot_constraint(
                                constraint,
                                topology
                                    .native_slots
                                    .get(key)
                                    .and_then(|slots| slots.params.get(index)),
                            )
                        })
                        .cloned()
                        .collect::<Vec<_>>(),
                );
            }
        }

        for key in &group.keys {
            let method = constraints
                .methods
                .get_mut(key)
                .expect("filtered source override method");
            let return_len = method.return_constraints.len();
            push_unique_signature_constraints(
                &mut method.return_constraints,
                &return_constraints
                    .iter()
                    .filter(|constraint| {
                        override_slot_constraint(
                            constraint,
                            topology.native_slots.get(key).map(|slots| &slots.returned),
                        )
                    })
                    .cloned()
                    .collect::<Vec<_>>(),
            );
            changed |= method.return_constraints.len() != return_len;
            for (index, (slot, joined)) in
                method.params.iter_mut().zip(&param_constraints).enumerate()
            {
                let slot_len = slot.len();
                push_unique_signature_constraints(
                    slot,
                    &joined
                        .iter()
                        .filter(|constraint| {
                            override_slot_constraint(
                                constraint,
                                topology
                                    .native_slots
                                    .get(key)
                                    .and_then(|slots| slots.params.get(index)),
                            )
                        })
                        .cloned()
                        .collect::<Vec<_>>(),
                );
                changed |= slot.len() != slot_len;
            }
            // The trait slot must expose the strongest receiver capability of
            // its implementations, while concrete implementations keep their
            // independently solved receiver. This also makes calls through an
            // interface field see the same `&mut self` ABI as trait emission.
            let key_is_interface = group.interface_keys.contains(key);
            if mutable_receiver
                && (!group.group_has_interface || key_is_interface)
                && !method
                    .receiver
                    .contains(&ReceiverConstraint::MutableReceiver)
            {
                method.receiver.push(ReceiverConstraint::MutableReceiver);
                changed = true;
            }
        }
    }
    changed
}

/// Batch normalization can retain the same nested source declaration under
/// both Java's dotted owner (`Outer.Inner`) and the emitted Rust owner
/// (`Outer_Inner`). Package summaries can likewise retain a qualified owner
/// beside an emitted simple owner. Receiver capability is one property of the
/// Java callable slot, so join a mutable receiver across those aliases before
/// call propagation. Ambiguous bare owners shared by multiple packages remain
/// isolated.
#[derive(Debug, Clone, Default)]
struct SourceOwnerAliasReceiverTopology {
    aliases_by_target: Vec<(MethodKey, Vec<MethodKey>)>,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct SourceOwnerAliasSlotKey {
    rust_name: String,
    param_java_types: Vec<JavaType>,
    is_static: bool,
}

fn build_source_owner_alias_receiver_topology(
    constraints: &SignatureConstraintState,
) -> SourceOwnerAliasReceiverTopology {
    let mut methods_by_slot = HashMap::<SourceOwnerAliasSlotKey, Vec<MethodKey>>::new();
    for (key, method) in &constraints.methods {
        methods_by_slot
            .entry(SourceOwnerAliasSlotKey {
                rust_name: key.rust_name.clone(),
                param_java_types: method.param_java_types.clone(),
                is_static: method
                    .receiver
                    .contains(&ReceiverConstraint::StaticReceiver),
            })
            .or_default()
            .push(key.clone());
    }
    let mut aliases_by_target = Vec::new();
    for (slot, methods) in methods_by_slot {
        if slot.is_static {
            continue;
        }
        let slot_owners = methods
            .iter()
            .map(|key| key.type_name())
            .collect::<Vec<_>>();
        for target in &methods {
            let aliases = methods
                .iter()
                .filter(|candidate| {
                    signature_owner_alias_matches(
                        target.type_name(),
                        candidate.type_name(),
                        &slot_owners,
                    )
                })
                .cloned()
                .collect::<Vec<_>>();
            aliases_by_target.push((target.clone(), aliases));
        }
    }
    SourceOwnerAliasReceiverTopology { aliases_by_target }
}

fn equalize_source_owner_alias_receiver_constraints_with_topology(
    constraints: &mut SignatureConstraintState,
    topology: &SourceOwnerAliasReceiverTopology,
) -> bool {
    let pending = topology
        .aliases_by_target
        .iter()
        .filter(|(target, aliases)| {
            !constraints.methods.get(target).is_some_and(|method| {
                method
                    .receiver
                    .contains(&ReceiverConstraint::MutableReceiver)
            }) && aliases.iter().any(|candidate| {
                constraints.methods.get(candidate).is_some_and(|method| {
                    method
                        .receiver
                        .contains(&ReceiverConstraint::MutableReceiver)
                })
            })
        })
        .map(|(target, _)| target.clone())
        .collect::<Vec<_>>();
    let mut changed = false;
    for key in pending {
        let Some(method) = constraints.methods.get_mut(&key) else {
            continue;
        };
        if !method
            .receiver
            .contains(&ReceiverConstraint::MutableReceiver)
        {
            method.receiver.push(ReceiverConstraint::MutableReceiver);
            changed = true;
        }
    }
    changed
}

#[cfg(test)]
fn equalize_source_owner_alias_receiver_constraints(
    constraints: &mut SignatureConstraintState,
) -> bool {
    let topology = build_source_owner_alias_receiver_topology(constraints);
    equalize_source_owner_alias_receiver_constraints_with_topology(constraints, &topology)
}

fn signature_owner_alias_matches(left: &str, right: &str, slot_owners: &[&str]) -> bool {
    if left == right {
        return true;
    }
    let left_normalized = signature_owner_separator_normalized(left);
    let right_normalized = signature_owner_separator_normalized(right);
    if left_normalized == right_normalized {
        return true;
    }
    let (shorter, longer) = if left_normalized.len() < right_normalized.len() {
        (&left_normalized, &right_normalized)
    } else {
        (&right_normalized, &left_normalized)
    };
    if !longer.ends_with(shorter) || longer.as_bytes()[longer.len() - shorter.len() - 1] != b'_' {
        return false;
    }
    let expansions = slot_owners
        .iter()
        .map(|owner| signature_owner_separator_normalized(owner))
        .filter(|owner| {
            owner.len() > shorter.len()
                && owner.ends_with(shorter)
                && owner.as_bytes()[owner.len() - shorter.len() - 1] == b'_'
        })
        .collect::<HashSet<_>>();
    expansions.len() <= 1
}

fn signature_owner_separator_normalized(owner: &str) -> String {
    owner.replace(['.', '$'], "_")
}

fn override_nullability_constraint(constraint: &SignatureConstraint) -> bool {
    matches!(
        constraint,
        SignatureConstraint::RequiredStorageNullability(_)
            | SignatureConstraint::NullableSequenceElement
            | SignatureConstraint::NullableSequenceElementAtDepth(_)
            | SignatureConstraint::NullableValueAtPath(_)
            | SignatureConstraint::NullableMapKey
    )
}

/// Context bodies can prove that an emitted interface/override slot accepts or
/// returns `null`, but their Rust ownership preferences must not reshape the
/// primary compilation unit. Import only that Java value-domain information.
fn merge_support_context_nullability_constraints(
    constraints: &mut SignatureConstraintState,
    support: SignatureConstraintState,
) {
    let mut seen = constraints
        .initializer_storage_edges
        .iter()
        .cloned()
        .collect::<HashSet<_>>();
    constraints.initializer_storage_edges.extend(
        support
            .initializer_storage_edges
            .into_iter()
            .filter(|edge| seen.insert(edge.clone())),
    );
    // A flattened inherited field is still the *same Java storage slot* as
    // its declaration.  Keep the declaring slot's complete shape facts in
    // the support context so every separately translated subtype can reuse
    // one ABI.  Method parameters/results are call boundaries and therefore
    // deliberately import only nullability below; field storage has no such
    // freedom without making hierarchy-carrier projections ill-typed.
    for (key, context_field) in support.fields {
        constraints.fields.entry(key).or_insert(context_field);
    }
    for (key, mut context_method) in support.methods {
        for slot in &mut context_method.params {
            slot.retain(override_nullability_constraint);
        }
        context_method
            .return_constraints
            .retain(override_nullability_constraint);
        context_method.locals.clear();
        context_method.local_index_by_name.clear();
        context_method.local_index_by_binding.clear();
        context_method.receiver.clear();

        if let Some(method) = constraints.methods.get_mut(&key) {
            push_unique_signature_constraints(
                &mut method.return_constraints,
                &context_method.return_constraints,
            );
            for (slot, context_slot) in method.params.iter_mut().zip(&context_method.params) {
                push_unique_signature_constraints(slot, context_slot);
            }
        } else {
            constraints.methods.insert(key, context_method);
        }
    }
}

fn propagate_call_site_constraints(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    let mut pending = Vec::new();
    for (usage_key, method_usage) in usage.method_entries() {
        let Some(caller_key) = method_key_for_usage(constraints, usage_key) else {
            continue;
        };
        if !constraints.methods.contains_key(&caller_key) {
            continue;
        }
        for call_site in method_usage.call_sites() {
            let Some(callee_key) = method_key_for_call_site(constraints, call_site) else {
                continue;
            };
            if !resolved_source_call_propagates_signature_constraints(call_site.boundary()) {
                continue;
            }
            let callee_constraints = constraints.methods.get(&callee_key);
            if let Some(callee_constraints) = callee_constraints {
                if call_site.result_returned() {
                    for constraint in &callee_constraints.return_constraints {
                        if signature_shape_constraint_propagation_policy().allows(constraint) {
                            pending.push((
                                caller_key.clone(),
                                PendingSignatureConstraint::Return(constraint.clone()),
                            ));
                        }
                    }
                }
                for binding in method_usage.all_binding_facts() {
                    for usage in binding.uses() {
                        let BindingUse::PassedToCall {
                            name,
                            arg_index,
                            boundary,
                            ..
                        } = usage
                        else {
                            continue;
                        };
                        if name != call_site.name()
                            || *boundary != call_site.boundary()
                            || !call_site.argument_bindings().iter().any(|(index, id)| {
                                index == arg_index && Some(id) == binding.binding()
                            })
                        {
                            continue;
                        }
                        {
                            for constraint in propagated_callee_argument_constraints_for_binding(
                                callee_constraints,
                                call_site.resolved(),
                                *arg_index,
                                binding.java_ty(),
                            ) {
                                if signature_shape_constraint_propagation_policy()
                                    .allows(&constraint)
                                    || matches!(constraint, SignatureConstraint::MutableBinding)
                                {
                                    pending.push((
                                        caller_key.clone(),
                                        PendingSignatureConstraint::Binding {
                                            binding: binding.clone(),
                                            constraint,
                                        },
                                    ));
                                }
                            }
                        }
                        for constraint in resolved_source_summary_arg_constraints(
                            call_site.resolved(),
                            *arg_index,
                            binding.java_ty(),
                        ) {
                            if signature_shape_constraint_propagation_policy().allows(&constraint) {
                                if *arg_index < callee_constraints.params.len() {
                                    pending.push((
                                        callee_key.clone(),
                                        PendingSignatureConstraint::Param {
                                            index: *arg_index,
                                            constraint: constraint.clone(),
                                        },
                                    ));
                                }
                                pending.push((
                                    caller_key.clone(),
                                    PendingSignatureConstraint::Binding {
                                        binding: binding.clone(),
                                        constraint,
                                    },
                                ));
                            }
                        }
                    }
                }
            } else {
                for binding in method_usage.all_binding_facts() {
                    for usage in binding.uses() {
                        let BindingUse::PassedToCall {
                            name,
                            arg_index,
                            boundary,
                            ..
                        } = usage
                        else {
                            continue;
                        };
                        if name != call_site.name() || *boundary != call_site.boundary() {
                            continue;
                        }
                        for constraint in resolved_source_summary_arg_constraints(
                            call_site.resolved(),
                            *arg_index,
                            binding.java_ty(),
                        ) {
                            pending.push((
                                caller_key.clone(),
                                PendingSignatureConstraint::Binding {
                                    binding: binding.clone(),
                                    constraint,
                                },
                            ));
                        }
                    }
                }
            }
        }
    }
    let mut changed = false;
    for (method_key, constraint) in pending {
        changed |= match constraint {
            PendingSignatureConstraint::Binding {
                binding,
                constraint,
            } => add_method_binding_fact_constraint_scoped(
                constraints,
                &method_key,
                &binding,
                constraint,
                scope,
            ),
            PendingSignatureConstraint::Return(constraint) => {
                add_method_return_constraint_scoped(constraints, &method_key, constraint, scope)
            }
            PendingSignatureConstraint::Param { index, constraint } => {
                add_method_param_index_constraint_scoped(
                    constraints,
                    &method_key,
                    index,
                    constraint,
                    scope,
                )
            }
        };
    }
    changed
}

fn resolved_source_call_propagates_signature_constraints(_boundary: CallArgumentBoundary) -> bool {
    // Once resolution identifies an emitted source declaration, that
    // declaration's solved Rust ABI is authoritative in both directions.
    // `KnownContentRead` is an ownership-optimization classification used for
    // unresolved/external calls; it must not suppress an owned/storage
    // requirement from an exact source callee (notably `T` stored through a
    // generic receiver).
    true
}

fn resolved_source_summary_arg_constraints(
    resolved: Option<&crate::java_ir::ResolvedCall>,
    arg_index: usize,
    binding_java_ty: &JavaType,
) -> Vec<SignatureConstraint> {
    let Some(target_ty) =
        resolved.and_then(|resolved| resolved_call_arg_target_type(resolved, arg_index))
    else {
        return Vec::new();
    };
    if !java_types_have_same_signature_boundary_identity(target_ty, binding_java_ty)
        || is_declared_java_object_type(target_ty)
        || matches!(target_ty, JavaType::Primitive(_) | JavaType::Void)
    {
        return Vec::new();
    }
    if matches!(target_ty, JavaType::String) {
        return vec![
            SignatureConstraint::RequiredOwnership(OwnershipShape::SharedBorrow),
            SignatureConstraint::RequiredDispatch(DispatchShape::Concrete),
            SignatureConstraint::RequiredView(ViewShape::Str),
        ];
    }
    vec![SignatureConstraint::RequiredOwnership(
        OwnershipShape::SharedBorrow,
    )]
}

fn propagate_constructor_call_site_constraints(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    let mut pending = Vec::new();
    for (usage_key, constructor_usage) in usage.constructor_entries() {
        let constructor_key = ConstructorKey::from_usage_key(usage_key);
        let Some(constructor_constraints) = constraints.constructors.get(&constructor_key) else {
            continue;
        };
        if constructor_constraints.public_api {
            continue;
        }
        for call_site in constructor_usage.call_sites() {
            let Some(callee_key) = method_key_for_call_site(constraints, call_site) else {
                continue;
            };
            let Some(callee_constraints) = constraints.methods.get(&callee_key) else {
                continue;
            };
            if !resolved_source_call_propagates_signature_constraints(call_site.boundary()) {
                continue;
            }
            for binding in constructor_usage.all_binding_facts() {
                for usage in binding.uses() {
                    let BindingUse::PassedToCall {
                        name,
                        arg_index,
                        boundary,
                        ..
                    } = usage
                    else {
                        continue;
                    };
                    if name != call_site.name()
                        || *boundary != call_site.boundary()
                        || !call_site
                            .argument_bindings()
                            .iter()
                            .any(|(index, id)| index == arg_index && Some(id) == binding.binding())
                    {
                        continue;
                    }
                    for constraint in propagated_callee_argument_constraints_for_binding(
                        callee_constraints,
                        call_site.resolved(),
                        *arg_index,
                        binding.java_ty(),
                    ) {
                        if signature_shape_constraint_propagation_policy().allows(&constraint)
                            || matches!(constraint, SignatureConstraint::MutableBinding)
                        {
                            pending.push((constructor_key.clone(), binding.clone(), constraint));
                        }
                    }
                }
            }
        }
    }
    let mut changed = false;
    for (constructor_key, binding, constraint) in pending {
        changed |= add_constructor_binding_fact_constraint_scoped(
            constraints,
            &constructor_key,
            &binding,
            constraint,
            scope,
        );
    }
    changed
}

fn propagate_resolved_source_mutable_argument_binding_constraints(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    if scope.is_some_and(|scope| {
        !scope.has_method_binding_target() && !scope.has_constructor_binding_target()
    }) {
        return false;
    }
    let mut pending_methods = Vec::new();
    for (usage_key, method_usage) in usage.method_entries() {
        let Some(caller_key) = method_key_for_usage(constraints, usage_key) else {
            continue;
        };
        if !constraints.methods.contains_key(&caller_key) {
            continue;
        }
        for (binding, requirement) in resolved_mutable_argument_requirements(
            constraints,
            method_usage,
            caller_key.type_name(),
        ) {
            pending_methods.push((caller_key.clone(), binding, requirement));
        }
    }
    let mut pending_constructors = Vec::new();
    for (usage_key, constructor_usage) in usage.constructor_entries() {
        let caller_key = ConstructorKey::from_usage_key(usage_key);
        if !constraints.constructors.contains_key(&caller_key) {
            continue;
        }
        for (binding, requirement) in resolved_mutable_argument_requirements(
            constraints,
            constructor_usage,
            caller_key.type_name(),
        ) {
            pending_constructors.push((caller_key.clone(), binding, requirement));
        }
    }
    let mut changed = false;
    for (key, binding, requirement) in pending_methods {
        changed |= add_method_binding_fact_constraint_scoped(
            constraints,
            &key,
            &binding,
            requirement,
            scope,
        );
    }
    for (key, binding, requirement) in pending_constructors {
        changed |= add_constructor_binding_fact_constraint_scoped(
            constraints,
            &key,
            &binding,
            requirement,
            scope,
        );
    }
    changed
}

/// A local binding needs to permit reborrowing; a forwarding parameter also
/// needs the caller-visible mutable ABI. Merely spelling its binding `mut`
/// cannot turn `&T` into `&mut T`. Use call-site binding identities, not a
/// same-name/boundary search that conflates overloads or shadowed locals.
fn resolved_mutable_argument_requirements(
    constraints: &SignatureConstraintState,
    usage: &MethodUsageFacts,
    caller_owner: &str,
) -> Vec<(BindingUseFacts, SignatureConstraint)> {
    let mut pending = Vec::new();
    let mut collect = |arguments: &[(usize, BindingId)], params: &[Vec<SignatureConstraint>]| {
        for (index, id) in arguments {
            if !params
                .get(*index)
                .is_some_and(|param| callee_param_requires_mutable_binding(param))
            {
                continue;
            }
            let Some(binding) = usage.binding_facts_for_declaration_id(id) else {
                continue;
            };
            pending.push((binding.clone(), SignatureConstraint::MutableBinding));
            if id.kind() == BindingKind::Param {
                pending.push((
                    binding.clone(),
                    SignatureConstraint::RequiredOwnership(OwnershipShape::MutableBorrow),
                ));
            }
        }
    };
    for call in usage.call_sites() {
        let Some(key) = method_key_for_call_site_in_caller(constraints, call, caller_owner) else {
            continue;
        };
        if let Some(callee) = constraints.methods.get(&key) {
            collect(call.argument_bindings(), &callee.params);
        }
    }
    for call in usage.constructor_call_sites() {
        let Some(key) = call.resolved().map(ConstructorKey::resolved_constructor) else {
            continue;
        };
        if let Some(callee) = constraints.constructors.get(&key) {
            collect(call.argument_bindings(), &callee.params);
        }
    }
    pending
}

fn propagate_resolved_source_mutable_receiver_binding_constraints(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    if scope.is_some_and(|scope| {
        !scope.has_method_binding_target()
            && !scope.has_constructor_binding_target()
            && !scope.has_method_receiver_target()
    }) {
        return false;
    }
    let mut pending_methods = Vec::new();
    let mut pending_method_receivers = Vec::new();
    for (usage_key, method_usage) in usage.method_entries() {
        let Some(caller_key) = method_key_for_usage(constraints, usage_key) else {
            continue;
        };
        if !constraints.methods.contains_key(&caller_key) {
            continue;
        }
        for call_site in method_usage.call_sites() {
            let Some(callee_key) =
                method_key_for_call_site_in_caller(constraints, call_site, caller_key.type_name())
            else {
                continue;
            };
            let Some(callee_constraints) = constraints.methods.get(&callee_key) else {
                continue;
            };
            let callee_mutates_receiver = callee_constraints
                .receiver
                .contains(&ReceiverConstraint::MutableReceiver)
                // A bodyless interface method has no direct mutation facts,
                // while trait emission correctly joins receiver capability
                // from its implementations.  Use that same implementation
                // evidence for calls through a self field so the caller and
                // emitted trait cannot disagree (`&self` calling `&mut self`).
                || (call_site.receiver_targets_self_field()
                    && source_method_usage_named_anywhere_mutates(usage, call_site.name()));
            let passes_self_field_to_mutable_param =
                call_site.argument_self_fields().iter().any(|(index, _)| {
                    callee_constraints
                        .params
                        .get(*index)
                        .is_some_and(|param| callee_param_requires_mutable_binding(param))
                });
            if (callee_mutates_receiver
                && (call_site.receiver_is_self() || call_site.receiver_targets_self_field()))
                || passes_self_field_to_mutable_param
            {
                pending_method_receivers.push(caller_key.clone());
            }
            if !callee_mutates_receiver {
                continue;
            }
            for binding in method_usage.all_binding_facts() {
                if binding.uses().iter().any(|usage| {
                    matches!(
                        usage,
                        BindingUse::ReceiverForCall { name, boundary, .. }
                            if name == call_site.name() && *boundary == call_site.boundary()
                    )
                }) {
                    pending_methods.push((
                        caller_key.clone(),
                        binding.clone(),
                        SignatureConstraint::MutableBinding,
                    ));
                    if binding
                        .binding()
                        .is_some_and(|id| id.kind() == BindingKind::Param)
                    {
                        pending_methods.push((
                            caller_key.clone(),
                            binding.clone(),
                            SignatureConstraint::RequiredOwnership(OwnershipShape::MutableBorrow),
                        ));
                    }
                }
            }
        }
    }
    let mut pending_constructors = Vec::new();
    for (usage_key, constructor_usage) in usage.constructor_entries() {
        let caller_key = ConstructorKey::from_usage_key(usage_key);
        if !constraints.constructors.contains_key(&caller_key) {
            continue;
        }
        for call_site in constructor_usage.call_sites() {
            let Some(callee_key) = method_key_for_call_site(constraints, call_site) else {
                continue;
            };
            let Some(callee_constraints) = constraints.methods.get(&callee_key) else {
                continue;
            };
            if !callee_constraints
                .receiver
                .contains(&ReceiverConstraint::MutableReceiver)
            {
                continue;
            }
            for binding in constructor_usage.all_binding_facts() {
                if binding.uses().iter().any(|usage| {
                    matches!(
                        usage,
                        BindingUse::ReceiverForCall { name, boundary, .. }
                            if name == call_site.name() && *boundary == call_site.boundary()
                    )
                }) {
                    pending_constructors.push((
                        caller_key.clone(),
                        binding.clone(),
                        SignatureConstraint::MutableBinding,
                    ));
                    if binding
                        .binding()
                        .is_some_and(|id| id.kind() == BindingKind::Param)
                    {
                        pending_constructors.push((
                            caller_key.clone(),
                            binding.clone(),
                            SignatureConstraint::RequiredOwnership(OwnershipShape::MutableBorrow),
                        ));
                    }
                }
            }
        }
    }
    let mut changed = false;
    for method_key in pending_method_receivers {
        if scope.is_some_and(|scope| {
            !scope.permits(&SignatureDependencyNode::MethodReceiver {
                method: method_key.clone(),
            })
        }) {
            continue;
        }
        let Some(method) = constraints.methods.get_mut(&method_key) else {
            continue;
        };
        if !method
            .receiver
            .contains(&ReceiverConstraint::MutableReceiver)
        {
            method.receiver.push(ReceiverConstraint::MutableReceiver);
            changed = true;
        }
    }
    for (method_key, binding, constraint) in pending_methods {
        changed |= add_method_binding_fact_constraint_scoped(
            constraints,
            &method_key,
            &binding,
            constraint,
            scope,
        );
    }
    for (constructor_key, binding, constraint) in pending_constructors {
        changed |= add_constructor_binding_fact_constraint_scoped(
            constraints,
            &constructor_key,
            &binding,
            constraint,
            scope,
        );
    }
    changed
}

fn callee_param_requires_mutable_binding(constraints: &[SignatureConstraint]) -> bool {
    // The caller must be able to hand out `&mut` even when the callee only
    // mutates an array element and never reassigns its parameter binding.
    // Requiring the callee's own `MutableBinding` flag misses that case.
    mutable_borrow_param_constraints(constraints)
}

fn propagated_callee_param_constraints(
    constraints: &[SignatureConstraint],
) -> Vec<&SignatureConstraint> {
    let mutable_borrow_param = constraints.iter().any(|constraint| {
        matches!(
            constraint,
            SignatureConstraint::RequiredOwnership(OwnershipShape::MutableBorrow)
        )
    }) && constraints
        .iter()
        .any(|constraint| matches!(constraint, SignatureConstraint::MutableBinding));
    constraints
        .iter()
        .filter(|constraint| {
            signature_shape_constraint_propagation_policy().allows(constraint)
                || (mutable_borrow_param
                    && matches!(constraint, SignatureConstraint::MutableBinding))
        })
        .collect()
}

fn propagated_callee_param_constraints_for_binding<'a>(
    constraints: &'a [SignatureConstraint],
    caller_binding_ty: &JavaType,
) -> Vec<&'a SignatureConstraint> {
    let callee_slot_is_erased_object = constraints.iter().any(|constraint| {
        matches!(
            constraint,
            SignatureConstraint::RequiredDispatch(DispatchShape::ErasedObject)
                | SignatureConstraint::RequiredView(ViewShape::ErasedObjectView)
        )
    });
    propagated_callee_param_constraints(constraints)
        .into_iter()
        .filter(|constraint| {
            if !list_interface_constraint_matches_type(constraint, caller_binding_ty) {
                return false;
            }
            // A semantic hash carrier is a physical requirement, not a
            // request to erase an ordered/source collection's operations.
            if matches!(
                constraint,
                SignatureConstraint::RequiredView(ViewShape::JavaSemanticHash)
            ) && crate::slot_render::semantic_hash_collection_base(caller_binding_ty).is_none()
            {
                return false;
            }
            // Array-parameter nullability describes values the callee accepts;
            // it is not a storage fact about the caller's array binding.
            // Propagating it backwards turns a freshly allocated `T[]` local
            // into `Option<Vec<T>>` merely because the callee also accepts
            // null. Other reference bindings still need this propagation: it
            // is how nullable source-call initializers and reused nullable
            // arguments retain their solved optional storage.
            !(matches!(
                constraint,
                SignatureConstraint::RequiredStorageNullability(_)
            ) && crate::types::sequence_element_type(caller_binding_ty).is_some())
                && !callee_erased_object_slot_constraint_should_stay_local(
                    constraint,
                    caller_binding_ty,
                    callee_slot_is_erased_object,
                )
        })
        .collect()
}

fn callee_erased_object_slot_constraint_should_stay_local(
    constraint: &SignatureConstraint,
    caller_binding_ty: &JavaType,
    callee_slot_is_erased_object: bool,
) -> bool {
    if is_declared_java_object_type(caller_binding_ty) || !callee_slot_is_erased_object {
        return false;
    }
    matches!(
        constraint,
        SignatureConstraint::RequiredOwnership(ownership)
            if *ownership != OwnershipShape::MutableBorrow
    ) || matches!(
        constraint,
        SignatureConstraint::RequiredDispatch(DispatchShape::ErasedObject)
            | SignatureConstraint::RequiredView(ViewShape::ErasedObjectView)
            | SignatureConstraint::RequiredStorageNullability(_)
            | SignatureConstraint::StorageSlot
    )
}

fn propagate_constructor_delegation_constraints(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    let mut pending = Vec::new();
    for (usage_key, constructor_usage) in usage.constructor_entries() {
        let constructor_key = ConstructorKey::from_usage_key(usage_key);
        let Some(constructor_constraints) = constraints.constructors.get(&constructor_key) else {
            continue;
        };
        let public_api = constructor_constraints.public_api;
        for call_site in constructor_usage.constructor_call_sites() {
            let Some(resolved) = call_site.resolved() else {
                continue;
            };
            let callee_key = ConstructorKey::resolved_constructor(resolved);
            let Some(callee_constraints) = constraints.constructors.get(&callee_key) else {
                continue;
            };
            for binding in constructor_usage.all_binding_facts() {
                for usage in binding.uses() {
                    let BindingUse::PassedToCall {
                        name,
                        arg_index,
                        boundary,
                        ..
                    } = usage
                    else {
                        continue;
                    };
                    if name != call_site.name()
                        || *boundary != call_site.boundary()
                        || *arg_index >= callee_constraints.params.len()
                    {
                        continue;
                    }
                    for constraint in &callee_constraints.params[*arg_index] {
                        // A public constructor keeps its owned/native ABI, but
                        // it must still accept every Java value that its
                        // resolved source delegate accepts.  In particular a
                        // source `super(param)` whose constructor checks
                        // `param == null` requires an Option carrier in the
                        // child too; flattened constructor lowering replays
                        // that guard in the child's body.
                        if public_api
                            && !matches!(
                                constraint,
                                SignatureConstraint::RequiredStorageNullability(_)
                            )
                        {
                            continue;
                        }
                        if signature_shape_constraint_propagation_policy().allows(constraint) {
                            pending.push((
                                constructor_key.clone(),
                                binding.clone(),
                                constraint.clone(),
                            ));
                        }
                    }
                }
            }
        }
    }
    let mut changed = false;
    for (constructor_key, binding, constraint) in pending {
        changed |= add_constructor_binding_fact_constraint_scoped(
            constraints,
            &constructor_key,
            &binding,
            constraint,
            scope,
        );
    }
    changed
}

fn source_call_argument_constraints_for_caller(
    constraints: &SignatureConstraintState,
    caller: &SignatureCallableKey,
    usage: &MethodUsageFacts,
    pending: &mut Vec<(MethodKey, usize, SignatureConstraint)>,
) {
    let public_api = match caller {
        SignatureCallableKey::Method(key) => constraints.methods.get(key).map(|set| set.public_api),
        SignatureCallableKey::Constructor(key) => {
            constraints.constructors.get(key).map(|set| set.public_api)
        }
    };
    if public_api != Some(false) {
        return;
    }
    for site in usage.call_sites() {
        let Some(resolved) = site.resolved() else {
            continue;
        };
        let Some(callee) = method_key_for_resolved_call(constraints, resolved) else {
            continue;
        };
        let Some(set) = constraints.methods.get(&callee) else {
            continue;
        };
        if !resolved_source_call_propagates_signature_constraints(site.boundary()) {
            continue;
        }
        for (index, id) in site.argument_bindings() {
            if *index >= set.params.len()
                || resolved_call_arg_is_expanded_varargs_element(resolved, set, *index)
            {
                continue;
            }
            let Some(binding) = usage.binding_facts_for_declaration_id(id) else {
                continue;
            };
            let requirements = match caller {
                SignatureCallableKey::Method(key) => {
                    method_binding_fact_slot_requirements(&constraints.methods[key], binding)
                }
                SignatureCallableKey::Constructor(key) => {
                    constructor_binding_fact_slot_requirements(
                        &constraints.constructors[key],
                        binding,
                    )
                }
            };
            for requirement in caller_binding_constraints_for_callee_param(requirements) {
                if should_propagate_caller_binding_constraint_to_callee_param(
                    &requirement,
                    &set.params[*index],
                ) {
                    pending.push((callee.clone(), *index, requirement));
                }
            }
        }
    }
}

fn apply_source_call_argument_constraints(
    constraints: &mut SignatureConstraintState,
    pending: Vec<(MethodKey, usize, SignatureConstraint)>,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    let mut changed = false;
    for (callee, index, requirement) in pending {
        changed |= add_method_param_index_constraint_scoped(
            constraints,
            &callee,
            index,
            requirement,
            scope,
        );
    }
    changed
}

fn propagate_call_argument_constraints_to_callees(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    if scope.is_some_and(|scope| !scope.has_method_binding_target()) {
        return false;
    }
    let mut pending = Vec::new();
    for (key, body) in usage.method_entries() {
        if let Some(key) = method_key_for_usage(constraints, key) {
            source_call_argument_constraints_for_caller(
                constraints,
                &SignatureCallableKey::Method(key),
                body,
                &mut pending,
            );
        }
    }
    apply_source_call_argument_constraints(constraints, pending, scope)
}

fn resolved_call_arg_is_expanded_varargs_element(
    resolved: &ResolvedCall,
    callee: &MethodConstraintSet,
    arg_index: usize,
) -> bool {
    let Some(last) = callee.params.len().checked_sub(1) else {
        return false;
    };
    callee.param_is_varargs.get(last) == Some(&true)
        && arg_index >= last
        && (arg_index > last
            || crate::java_signature::resolved_argument_storage_projection(resolved, arg_index)
                .is_some_and(|(_, path, _, _)| !path.is_empty()))
}

fn propagated_callee_argument_constraints_for_binding(
    callee: &MethodConstraintSet,
    resolved: Option<&ResolvedCall>,
    argument: usize,
    binding_ty: &JavaType,
) -> Vec<SignatureConstraint> {
    let Some(last) = callee.params.len().checked_sub(1) else {
        return Vec::new();
    };
    let expanded = callee.param_is_varargs.get(last) == Some(&true)
        && argument >= last
        && (argument > last
            || resolved.is_some_and(|call| {
                resolved_call_arg_is_expanded_varargs_element(call, callee, argument)
            }));
    let index = if expanded { last } else { argument };
    let Some(requirements) = callee.params.get(index) else {
        return Vec::new();
    };
    let projected = if expanded {
        requirements
            .iter()
            .filter_map(|requirement| match requirement {
                SignatureConstraint::RequiredNestedNativeAllocation { path, placement }
                    if path.first() == Some(&0) =>
                {
                    Some(native_allocation_requirement(
                        path[1..].to_vec(),
                        *placement,
                    ))
                }
                SignatureConstraint::NullableSequenceElement => {
                    Some(nullable_storage_requirement(binding_ty, vec![]))
                }
                SignatureConstraint::NullableSequenceElementAtDepth(depth) if *depth > 0 => Some(
                    SignatureConstraint::NullableSequenceElementAtDepth(depth - 1),
                ),
                SignatureConstraint::NullableValueAtPath(path) if path.first() == Some(&0) => {
                    Some(nullable_storage_requirement(binding_ty, path[1..].to_vec()))
                }
                _ => None,
            })
            .collect::<Vec<_>>()
    } else {
        requirements.clone()
    };
    propagated_callee_param_constraints_for_binding(&projected, binding_ty)
        .into_iter()
        .cloned()
        .collect()
}

fn propagate_call_argument_collection_carrier_java_types_to_callees(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    if scope.is_some_and(|scope| !scope.has_method_binding_target()) {
        return false;
    }
    let mut pending = Vec::new();
    let mut carrier_observations = Vec::new();
    let mut rejected_bound_captures = HashSet::new();
    for (usage_key, method_usage) in usage.method_entries() {
        let Some(caller_key) = method_key_for_usage(constraints, usage_key) else {
            continue;
        };
        let Some(caller_constraints) = constraints.methods.get(&caller_key) else {
            continue;
        };
        for call_site in method_usage.call_sites() {
            let Some(resolved) = call_site.resolved() else {
                continue;
            };
            if !resolved_source_call_propagates_signature_constraints(call_site.boundary()) {
                continue;
            }
            let Some(callee_key) = method_key_for_resolved_call(constraints, resolved) else {
                continue;
            };
            let Some(callee_constraints) = constraints.methods.get(&callee_key) else {
                continue;
            };
            // Collection implementations are runtime value properties in
            // Java. Preserve a unique whole-program carrier even for a
            // publicly declared source method: otherwise a LinkedHashMap
            // passed through `Map` is eagerly collected into HashMap and its
            // observable iteration order is destroyed. Ambiguous call sites
            // remain on the declared interface carrier below.
            for (arg_index, target) in callee_constraints.param_java_types.iter().enumerate() {
                let binding = call_site
                    .argument_bindings()
                    .iter()
                    .find(|(index, _)| *index == arg_index)
                    .and_then(|(_, id)| method_usage.binding_facts_for_declaration_id(id));
                let actual = binding
                    .map(|binding| effective_method_binding_java_type(caller_constraints, binding));
                if let Some(observed) = actual
                    .as_ref()
                    .and_then(|actual| collection_carrier_consensus_witness(actual, target))
                {
                    carrier_observations.push((callee_key.clone(), arg_index, observed));
                }
                let bound_capture = actual
                    .as_ref()
                    .zip(resolved.arg_target_types.get(arg_index))
                    .and_then(|(actual, instantiated)| {
                        exact_bound_capture_java_type_for_slot(actual, target, instantiated)
                    });
                if bounded_capture_java_type_for_slot(target).is_some() && bound_capture.is_none() {
                    // One non-exact or unmodeled observed call is enough to
                    // reject declaration-wide capture elimination.
                    rejected_bound_captures.insert((callee_key.clone(), arg_index));
                }
                let refined = actual
                    .as_ref()
                    .and_then(|actual| refined_internal_call_java_type_for_slot(actual, target))
                    .or(bound_capture);
                if let Some(refined) = refined {
                    if crate::stdlib::java_collection_kind_for_type(&refined)
                        != crate::stdlib::java_collection_kind_for_type(target)
                    {
                        continue;
                    }
                    pending.push((callee_key.clone(), arg_index, refined));
                }
            }
        }
    }
    let mut changed = false;
    for (callee_key, index, observed) in carrier_observations {
        let Some(callee) = constraints.methods.get_mut(&callee_key) else {
            continue;
        };
        let Some(current) = callee.param_java_types.get_mut(index) else {
            continue;
        };
        changed |= join_collection_carrier_consensus(
            &mut callee.collection_carrier_consensus,
            index,
            current,
            observed,
        );
    }
    for (callee_key, arg_index, refined) in unique_unambiguous_param_java_type_refinements(pending)
    {
        if rejected_bound_captures.contains(&(callee_key.clone(), arg_index)) {
            continue;
        }
        let Some(callee_constraints) = constraints.methods.get_mut(&callee_key) else {
            continue;
        };
        let Some(current) = callee_constraints.param_java_types.get_mut(arg_index) else {
            continue;
        };
        if *current == refined {
            continue;
        }
        if refined_internal_call_java_type_for_slot(&refined, current).is_none()
            && bounded_capture_java_type_for_slot(current).as_ref() != Some(&refined)
        {
            continue;
        }
        *current = refined;
        changed = true;
    }
    changed
}

fn propagate_constructor_argument_collection_carrier_java_types_to_callees(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    if scope.is_some_and(|scope| !scope.has_constructor_binding_target()) {
        return false;
    }
    let mut pending = Vec::new();
    let mut carrier_observations = Vec::new();
    for (usage_key, method_usage) in usage.method_entries() {
        let Some(caller_key) = method_key_for_usage(constraints, usage_key) else {
            continue;
        };
        let Some(caller_constraints) = constraints.methods.get(&caller_key) else {
            continue;
        };
        for call_site in method_usage.constructor_call_sites() {
            let Some(callee_key) = call_site
                .resolved()
                .map(ConstructorKey::resolved_constructor)
            else {
                continue;
            };
            let Some(callee_constraints) = constraints.constructors.get(&callee_key) else {
                continue;
            };
            if callee_constraints.public_api {
                continue;
            }
            for (index, binding_id) in call_site.argument_bindings() {
                let Some(binding) = method_usage.binding_facts_for_declaration_id(binding_id)
                else {
                    continue;
                };
                let Some(target) = callee_constraints.param_java_types.get(*index) else {
                    continue;
                };
                let actual = effective_method_binding_java_type(caller_constraints, binding);
                if let Some(observed) = collection_carrier_consensus_witness(&actual, target) {
                    carrier_observations.push((callee_key.clone(), *index, observed));
                }
                if let Some(refined) = refined_internal_call_java_type_for_slot(&actual, target) {
                    if crate::stdlib::java_collection_kind_for_type(&refined)
                        != crate::stdlib::java_collection_kind_for_type(target)
                    {
                        continue;
                    }
                    pending.push((callee_key.clone(), *index, refined));
                }
            }
        }
    }
    let mut grouped = HashMap::<(ConstructorKey, usize), Vec<JavaType>>::new();
    for (key, index, java_ty) in pending {
        grouped.entry((key, index)).or_default().push(java_ty);
    }
    let mut changed = false;
    for (callee_key, index, observed) in carrier_observations {
        let Some(callee) = constraints.constructors.get_mut(&callee_key) else {
            continue;
        };
        let Some(current) = callee.param_java_types.get_mut(index) else {
            continue;
        };
        changed |= join_collection_carrier_consensus(
            &mut callee.collection_carrier_consensus,
            index,
            current,
            observed,
        );
    }
    for ((key, index), types) in grouped {
        let Some(refined) = types.first() else {
            continue;
        };
        if types.iter().any(|ty| ty != refined) {
            continue;
        }
        let Some(current) = constraints
            .constructors
            .get_mut(&key)
            .and_then(|constructor| constructor.param_java_types.get_mut(index))
        else {
            continue;
        };
        if *current != *refined
            && refined_internal_call_java_type_for_slot(refined, current).is_some()
        {
            *current = refined.clone();
            changed = true;
        }
    }
    changed
}

fn effective_method_binding_java_type(
    method_constraints: &MethodConstraintSet,
    binding: &BindingUseFacts,
) -> JavaType {
    if let Some(binding_id) = binding.binding() {
        if let Some(local) = method_constraints.local_by_binding(binding_id) {
            return local.java_ty.clone();
        }
    } else if let Some(local) = method_constraints.idless_compatibility_local(binding.name()) {
        return local.java_ty.clone();
    }
    if let Some(index) = method_constraints.param_index(binding.name())
        && let Some(java_ty) = method_constraints.param_java_types.get(index)
    {
        return java_ty.clone();
    }
    binding.java_ty().clone()
}

fn unique_unambiguous_param_java_type_refinements(
    pending: Vec<(MethodKey, usize, JavaType)>,
) -> Vec<(MethodKey, usize, JavaType)> {
    let mut grouped: Vec<(MethodKey, usize, Vec<JavaType>)> = Vec::new();
    for (key, index, java_ty) in pending {
        if let Some((_, _, types)) = grouped
            .iter_mut()
            .find(|(existing_key, existing_index, _)| {
                existing_key == &key && *existing_index == index
            })
        {
            if !types.contains(&java_ty) {
                types.push(java_ty);
            }
        } else {
            grouped.push((key, index, vec![java_ty]));
        }
    }
    grouped
        .into_iter()
        .filter_map(|(key, index, mut types)| {
            (types.len() == 1).then(|| (key, index, types.remove(0)))
        })
        .collect()
}

fn propagate_constructor_call_argument_constraints_to_callees(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    if scope.is_some_and(|scope| !scope.has_method_binding_target()) {
        return false;
    }
    let mut pending = Vec::new();
    for (key, body) in usage.constructor_entries() {
        source_call_argument_constraints_for_caller(
            constraints,
            &SignatureCallableKey::Constructor(ConstructorKey::from_usage_key(key)),
            body,
            &mut pending,
        );
    }
    apply_source_call_argument_constraints(constraints, pending, scope)
}

fn should_propagate_caller_binding_constraint_to_callee_param(
    constraint: &SignatureConstraint,
    callee_param_constraints: &[SignatureConstraint],
) -> bool {
    if matches!(constraint, SignatureConstraint::StorageSlot)
        && callee_param_constraints.contains(&SignatureConstraint::StorageSlot)
    {
        return false;
    }
    if matches!(
        constraint,
        SignatureConstraint::RequiredOwnership(OwnershipShape::Owned)
    ) && callee_param_constraints.iter().any(|callee_constraint| {
        matches!(
            callee_constraint,
            SignatureConstraint::RequiredOwnership(
                OwnershipShape::SharedBorrow | OwnershipShape::MutableBorrow
            )
        )
    }) {
        return false;
    }
    if matches!(
        constraint,
        SignatureConstraint::RequiredOwnership(OwnershipShape::MutableBorrow)
    ) && callee_param_constraints.iter().any(|callee_constraint| {
        matches!(
            callee_constraint,
            SignatureConstraint::RequiredOwnership(OwnershipShape::SharedBorrow)
        )
    }) && !callee_param_constraints.iter().any(|callee_constraint| {
        matches!(
            callee_constraint,
            SignatureConstraint::RequiredOwnership(OwnershipShape::MutableBorrow)
        )
    }) {
        return false;
    }
    true
}

fn caller_binding_constraints_for_callee_param(
    constraints: Vec<&SignatureConstraint>,
) -> Vec<SignatureConstraint> {
    let mut propagated = Vec::new();
    if constraints
        .iter()
        .any(|constraint| matches!(constraint, SignatureConstraint::StorageSlot))
    {
        push_unique_signature_constraints(
            &mut propagated,
            &[
                SignatureConstraint::StorageSlot,
                SignatureConstraint::RequiredView(ViewShape::Native),
                SignatureConstraint::RequiredOwnership(OwnershipShape::Owned),
            ],
        );
    }
    for constraint in constraints {
        if signature_shape_constraint_propagation_policy().allows(constraint) {
            push_unique_signature_constraints(&mut propagated, &[constraint.clone()]);
        }
    }
    propagated
}

fn propagate_constructor_delegation_argument_constraints_to_callees(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    if scope.is_some_and(|scope| !scope.has_constructor_binding_target()) {
        return false;
    }
    let mut pending = Vec::new();
    for (usage_key, constructor_usage) in usage.constructor_entries() {
        let constructor_key = ConstructorKey::from_usage_key(usage_key);
        let Some(constructor_constraints) = constraints.constructors.get(&constructor_key) else {
            continue;
        };
        if constructor_constraints.public_api {
            continue;
        }
        for call_site in constructor_usage.constructor_call_sites() {
            if call_site.boundary() != CallArgumentBoundary::InternalSameType {
                continue;
            }
            let Some(resolved) = call_site.resolved() else {
                continue;
            };
            let callee_key = ConstructorKey::resolved_constructor(resolved);
            if !constraints.constructors.contains_key(&callee_key) {
                continue;
            }
            for binding in constructor_usage.all_binding_facts() {
                for usage in binding.uses() {
                    let BindingUse::PassedToCall {
                        name,
                        arg_index,
                        boundary,
                        ..
                    } = usage
                    else {
                        continue;
                    };
                    if name != call_site.name() || *boundary != call_site.boundary() {
                        continue;
                    }
                    for constraint in caller_binding_constraints_for_callee_param(
                        constructor_binding_fact_slot_requirements(
                            constructor_constraints,
                            binding,
                        ),
                    ) {
                        pending.push((callee_key.clone(), *arg_index, constraint));
                    }
                }
            }
        }
    }
    let mut changed = false;
    for (callee_key, arg_index, constraint) in pending {
        let param_name = constraints
            .constructors
            .get(&callee_key)
            .and_then(|constructor_constraints| constructor_constraints.param_names.get(arg_index))
            .cloned();
        if let Some(param_name) = param_name {
            changed |= add_constructor_param_constraint_scoped(
                constraints,
                &callee_key,
                &param_name,
                constraint,
                scope,
            );
        }
    }
    changed
}

fn propagate_null_call_argument_constraints_to_callees(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    let mut method_pending = Vec::new();
    let mut constructor_pending = Vec::new();
    for (caller_usage_key, method_usage) in usage.method_entries() {
        let caller_constraints = method_key_for_usage(constraints, caller_usage_key)
            .and_then(|key| constraints.methods.get(&key));
        for call_site in method_usage.call_sites() {
            let Some(resolved) = call_site.resolved() else {
                continue;
            };
            let Some(callee_key) = method_key_for_resolved_call(constraints, resolved) else {
                continue;
            };
            if !constraints.methods.contains_key(&callee_key) {
                continue;
            }
            let nullable_binding_arg_indices = call_site
                .argument_bindings()
                .iter()
                .filter_map(|(index, binding_id)| {
                    let binding = method_usage.binding_facts_for_declaration_id(binding_id)?;
                    caller_constraints
                        .is_some_and(|caller| method_binding_has_nullable_storage(caller, binding))
                        .then_some(index)
                })
                .collect::<Vec<_>>();
            for arg_index in call_site
                .null_arg_indices()
                .iter()
                .chain(call_site.nullable_source_call_arg_indices().iter())
                .chain(nullable_binding_arg_indices)
            {
                method_pending.push((callee_key.clone(), *arg_index));
            }
        }
        for call_site in method_usage.constructor_call_sites() {
            if call_site.boundary() != CallArgumentBoundary::InternalSameType {
                continue;
            }
            let Some(resolved) = call_site.resolved() else {
                continue;
            };
            let callee_key = ConstructorKey::resolved_constructor(resolved);
            if !constraints.constructors.contains_key(&callee_key) {
                continue;
            }
            let nullable_binding_arg_indices = call_site
                .argument_bindings()
                .iter()
                .filter_map(|(index, binding_id)| {
                    let binding = method_usage.binding_facts_for_declaration_id(binding_id)?;
                    caller_constraints
                        .is_some_and(|caller| method_binding_has_nullable_storage(caller, binding))
                        .then_some(index)
                })
                .collect::<Vec<_>>();
            for arg_index in call_site
                .null_arg_indices()
                .iter()
                .chain(call_site.nullable_source_call_arg_indices().iter())
                .chain(nullable_binding_arg_indices)
            {
                constructor_pending.push((callee_key.clone(), *arg_index));
            }
        }
    }
    for (caller_usage_key, constructor_usage) in usage.constructor_entries() {
        let caller_constraints = constraints
            .constructors
            .get(&ConstructorKey::from_usage_key(caller_usage_key));
        for call_site in constructor_usage.call_sites() {
            let Some(resolved) = call_site.resolved() else {
                continue;
            };
            let Some(callee_key) = method_key_for_resolved_call(constraints, resolved) else {
                continue;
            };
            if !constraints.methods.contains_key(&callee_key) {
                continue;
            }
            for arg_index in call_site
                .null_arg_indices()
                .iter()
                .chain(call_site.nullable_source_call_arg_indices().iter())
            {
                method_pending.push((callee_key.clone(), *arg_index));
            }
        }
        for call_site in constructor_usage.constructor_call_sites() {
            if call_site.boundary() != CallArgumentBoundary::InternalSameType {
                continue;
            }
            let Some(resolved) = call_site.resolved() else {
                continue;
            };
            let callee_key = ConstructorKey::resolved_constructor(resolved);
            if !constraints.constructors.contains_key(&callee_key) {
                continue;
            }
            let nullable_binding_arg_indices = call_site
                .argument_bindings()
                .iter()
                .filter_map(|(index, binding_id)| {
                    let binding = constructor_usage.binding_facts_for_declaration_id(binding_id)?;
                    caller_constraints
                        .is_some_and(|caller| {
                            constructor_binding_has_nullable_storage(caller, binding)
                        })
                        .then_some(index)
                })
                .collect::<Vec<_>>();
            for arg_index in call_site
                .null_arg_indices()
                .iter()
                .chain(call_site.nullable_source_call_arg_indices().iter())
                .chain(nullable_binding_arg_indices)
            {
                constructor_pending.push((callee_key.clone(), *arg_index));
            }
        }
    }

    let nullability = SignatureConstraint::RequiredStorageNullability(NullabilityState::MaybeNull);
    let mut changed = false;
    for (callee_key, arg_index) in method_pending {
        let param_name = constraints
            .methods
            .get(&callee_key)
            .and_then(|method_constraints| method_constraints.param_names.get(arg_index))
            .cloned();
        if let Some(param_name) = param_name {
            changed |= add_method_param_constraint_scoped(
                constraints,
                &callee_key,
                &param_name,
                nullability.clone(),
                scope,
            );
        }
    }
    for (callee_key, arg_index) in constructor_pending {
        let param_name = constraints
            .constructors
            .get(&callee_key)
            .and_then(|constructor_constraints| constructor_constraints.param_names.get(arg_index))
            .cloned();
        if let Some(param_name) = param_name {
            changed |= add_constructor_param_constraint_scoped(
                constraints,
                &callee_key,
                &param_name,
                nullability.clone(),
                scope,
            );
        }
    }
    changed
}

fn method_binding_has_nullable_storage(
    method: &MethodConstraintSet,
    binding: &BindingUseFacts,
) -> bool {
    let constraints = match binding.binding().map(BindingId::kind) {
        Some(BindingKind::Local | BindingKind::LoopVariable | BindingKind::CatchParam) => method
            .local_by_binding(binding.binding().expect("local binding id"))
            .map(|local| local.constraints.as_slice()),
        Some(BindingKind::Param) => method
            .param_index(binding.name())
            .and_then(|index| method.params.get(index))
            .map(Vec::as_slice),
        _ => None,
    };
    constraints.is_some_and(|constraints| {
        constraints.iter().any(|constraint| {
            matches!(
                constraint,
                SignatureConstraint::RequiredStorageNullability(
                    NullabilityState::DefinitelyNull | NullabilityState::MaybeNull
                )
            )
        })
    })
}

fn method_binding_has_constraint(
    method: &MethodConstraintSet,
    binding: &BindingUseFacts,
    expected: &SignatureConstraint,
) -> bool {
    let constraints = match binding.binding().map(BindingId::kind) {
        Some(BindingKind::Local | BindingKind::LoopVariable | BindingKind::CatchParam) => method
            .local_by_binding(binding.binding().expect("local binding id"))
            .map(|local| local.constraints.as_slice()),
        Some(BindingKind::Param) => method
            .param_index(binding.name())
            .and_then(|index| method.params.get(index))
            .map(Vec::as_slice),
        _ => None,
    };
    constraints.is_some_and(|constraints| constraints.contains(expected))
}

fn constructor_binding_has_nullable_storage(
    constructor: &ConstructorConstraintSet,
    binding: &BindingUseFacts,
) -> bool {
    let constraints = match binding.binding().map(BindingId::kind) {
        Some(BindingKind::Local | BindingKind::LoopVariable | BindingKind::CatchParam) => {
            constructor
                .local_by_binding(binding.binding().expect("local binding id"))
                .map(|local| local.constraints.as_slice())
        }
        Some(BindingKind::Param) => constructor
            .param_index(binding.name())
            .and_then(|index| constructor.params.get(index))
            .map(Vec::as_slice),
        _ => None,
    };
    constraints.is_some_and(|constraints| {
        constraints.iter().any(|constraint| {
            matches!(
                constraint,
                SignatureConstraint::RequiredStorageNullability(
                    NullabilityState::DefinitelyNull | NullabilityState::MaybeNull
                )
            )
        })
    })
}

fn constructor_binding_has_constraint(
    constructor: &ConstructorConstraintSet,
    binding: &BindingUseFacts,
    expected: &SignatureConstraint,
) -> bool {
    let constraints = match binding.binding().map(BindingId::kind) {
        Some(BindingKind::Local | BindingKind::LoopVariable | BindingKind::CatchParam) => {
            constructor
                .local_by_binding(binding.binding().expect("local binding id"))
                .map(|local| local.constraints.as_slice())
        }
        Some(BindingKind::Param) => constructor
            .param_index(binding.name())
            .and_then(|index| constructor.params.get(index))
            .map(Vec::as_slice),
        _ => None,
    };
    constraints.is_some_and(|constraints| constraints.contains(expected))
}

fn propagate_nullable_map_key_carriers(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    let mut pending = Vec::new();
    let mut constructor_pending = Vec::new();
    let mut callee_param_pending = Vec::new();
    for (usage_key, method_usage) in usage.method_entries() {
        let Some(caller_key) = method_key_for_usage(constraints, usage_key) else {
            continue;
        };
        let Some(caller_constraints) = constraints.methods.get(&caller_key) else {
            continue;
        };
        for map_binding in method_usage.all_binding_facts() {
            if map_binding.binding().is_none() {
                continue;
            }
            if matches!(
                crate::stdlib::java_collection_kind_for_type(map_binding.java_ty()),
                Some(crate::stdlib::JavaCollectionKind::SortedMap)
            ) || crate::stdlib::java_map_type_args(map_binding.java_ty()).is_none()
            {
                continue;
            }
            let nullable_key_put = map_binding.uses().iter().any(|usage| {
                let BindingUse::ReceiverForCall {
                    name,
                    argument_bindings,
                    non_null_arg_indices,
                    ..
                } = usage
                else {
                    return false;
                };
                matches!(name.as_str(), "put" | "putIfAbsent" | "put_if_absent")
                    && argument_bindings.iter().any(|(index, key_binding)| {
                        *index == 0
                            && !non_null_arg_indices.contains(index)
                            && method_usage
                                .binding_facts_for_declaration_id(key_binding)
                                .is_some_and(|key| {
                                    method_binding_has_nullable_storage(caller_constraints, key)
                                })
                    })
            });
            if nullable_key_put {
                pending.push((caller_key.clone(), map_binding.clone()));
            }
        }
        for call_site in method_usage.call_sites() {
            let Some(callee_key) = call_site
                .resolved()
                .and_then(|resolved| method_key_for_resolved_call(constraints, resolved))
            else {
                continue;
            };
            let Some(callee_constraints) = constraints.methods.get(&callee_key) else {
                continue;
            };
            for (index, binding_id) in call_site.argument_bindings() {
                if let Some(binding) = method_usage.binding_facts_for_declaration_id(binding_id)
                    && method_binding_has_constraint(
                        caller_constraints,
                        binding,
                        &SignatureConstraint::NullableMapKey,
                    )
                    && let Some(param_name) = callee_constraints.param_names.get(*index)
                {
                    callee_param_pending.push((callee_key.clone(), param_name.clone()));
                }
                if !callee_constraints
                    .params
                    .get(*index)
                    .is_some_and(|param| param.contains(&SignatureConstraint::NullableMapKey))
                {
                    continue;
                }
                if let Some(binding) = method_usage.binding_facts_for_declaration_id(binding_id) {
                    pending.push((caller_key.clone(), binding.clone()));
                }
            }
        }
        for call_site in method_usage.constructor_call_sites() {
            let Some(callee_key) = call_site
                .resolved()
                .map(ConstructorKey::resolved_constructor)
            else {
                continue;
            };
            let Some(callee_constraints) = constraints.constructors.get(&callee_key) else {
                continue;
            };
            for (index, binding_id) in call_site.argument_bindings() {
                if !callee_constraints
                    .params
                    .get(*index)
                    .is_some_and(|param| param.contains(&SignatureConstraint::NullableMapKey))
                {
                    continue;
                }
                if let Some(binding) = method_usage.binding_facts_for_declaration_id(binding_id) {
                    pending.push((caller_key.clone(), binding.clone()));
                }
            }
        }
    }
    for (usage_key, constructor_usage) in usage.constructor_entries() {
        let caller_key = ConstructorKey::from_usage_key(usage_key);
        let Some(caller_constraints) = constraints.constructors.get(&caller_key) else {
            continue;
        };
        for map_binding in constructor_usage.all_binding_facts() {
            if map_binding.binding().is_none()
                || matches!(
                    crate::stdlib::java_collection_kind_for_type(map_binding.java_ty()),
                    Some(crate::stdlib::JavaCollectionKind::SortedMap)
                )
                || crate::stdlib::java_map_type_args(map_binding.java_ty()).is_none()
            {
                continue;
            }
            let nullable_key_put = map_binding.uses().iter().any(|usage| {
                let BindingUse::ReceiverForCall {
                    name,
                    argument_bindings,
                    non_null_arg_indices,
                    ..
                } = usage
                else {
                    return false;
                };
                matches!(name.as_str(), "put" | "putIfAbsent" | "put_if_absent")
                    && argument_bindings.iter().any(|(index, key_binding)| {
                        *index == 0
                            && !non_null_arg_indices.contains(index)
                            && constructor_usage
                                .binding_facts_for_declaration_id(key_binding)
                                .is_some_and(|key| {
                                    constructor_binding_has_nullable_storage(
                                        caller_constraints,
                                        key,
                                    )
                                })
                    })
            });
            if nullable_key_put {
                constructor_pending.push((caller_key.clone(), map_binding.clone()));
            }
        }
        for call_site in constructor_usage.constructor_call_sites() {
            let Some(callee_key) = call_site
                .resolved()
                .map(ConstructorKey::resolved_constructor)
            else {
                continue;
            };
            let Some(callee_constraints) = constraints.constructors.get(&callee_key) else {
                continue;
            };
            for (index, binding_id) in call_site.argument_bindings() {
                if !callee_constraints
                    .params
                    .get(*index)
                    .is_some_and(|param| param.contains(&SignatureConstraint::NullableMapKey))
                {
                    continue;
                }
                if let Some(binding) =
                    constructor_usage.binding_facts_for_declaration_id(binding_id)
                {
                    constructor_pending.push((caller_key.clone(), binding.clone()));
                }
            }
        }
    }
    let mut changed = false;
    for (method_key, binding) in pending {
        changed |= add_method_binding_fact_constraint_scoped(
            constraints,
            &method_key,
            &binding,
            SignatureConstraint::NullableMapKey,
            scope,
        );
    }
    for (constructor_key, binding) in constructor_pending {
        changed |= add_constructor_binding_fact_constraint_scoped(
            constraints,
            &constructor_key,
            &binding,
            SignatureConstraint::NullableMapKey,
            scope,
        );
    }
    for (method_key, param_name) in callee_param_pending {
        changed |= add_method_param_constraint_scoped(
            constraints,
            &method_key,
            &param_name,
            SignatureConstraint::NullableMapKey,
            scope,
        );
    }
    changed
}

/// Java collection arguments alias the producer's storage. The same edges
/// drive SCC scheduling and nullable-carrier saturation, including expressions
/// which have no local binding to carry a PassedToCall usage fact.
fn collection_argument_storage_edges(
    constraints: &SignatureConstraintState,
    usage: &UsageFacts,
) -> Vec<(SignatureDependencyNode, SignatureDependencyNode)> {
    fn origin_node(
        constraints: &SignatureConstraintState,
        origin: &crate::usage::CollectionArgumentOrigin,
    ) -> Option<SignatureDependencyNode> {
        match origin {
            crate::usage::CollectionArgumentOrigin::MethodReturn(call) => {
                Some(SignatureDependencyNode::MethodReturn {
                    method: method_key_for_resolved_call(constraints, call)?,
                })
            }
            crate::usage::CollectionArgumentOrigin::Field { owner, name } => {
                field_key_for_resolved_source(constraints, owner, name)
                    .map(|field| SignatureDependencyNode::Field { field })
            }
        }
    }
    let collection = |ty: &JavaType| {
        crate::stdlib::java_collection_kind_for_type(
            &optional_element_type(ty).unwrap_or_else(|| ty.clone()),
        )
        .is_some()
    };
    let mut edges = Vec::new();
    for caller in usage
        .method_entries()
        .map(|(_, entry)| entry)
        .chain(usage.constructor_entries().map(|(_, entry)| entry))
    {
        for call in caller.call_sites() {
            let Some(callee) = call
                .resolved()
                .and_then(|call| method_key_for_resolved_call(constraints, call))
            else {
                continue;
            };
            let Some(params) = constraints.methods.get(&callee) else {
                continue;
            };
            for (index, origin) in call.collection_argument_origins() {
                let Some(name) = params.param_names.get(*index) else {
                    continue;
                };
                if !params.param_java_types.get(*index).is_some_and(collection) {
                    continue;
                }
                if let Some(source) = origin_node(constraints, origin) {
                    edges.push((
                        source,
                        SignatureDependencyNode::MethodParam {
                            method: callee.clone(),
                            name: name.clone(),
                            index: *index,
                        },
                    ));
                }
            }
        }
        for call in caller.constructor_call_sites() {
            let Some(callee) = call.resolved().map(ConstructorKey::resolved_constructor) else {
                continue;
            };
            let Some(params) = constraints.constructors.get(&callee) else {
                continue;
            };
            for (index, origin) in call.collection_argument_origins() {
                let Some(name) = params.param_names.get(*index) else {
                    continue;
                };
                if !params.param_java_types.get(*index).is_some_and(collection) {
                    continue;
                }
                if let Some(source) = origin_node(constraints, origin) {
                    edges.push((
                        source,
                        SignatureDependencyNode::ConstructorParam {
                            constructor: callee.clone(),
                            name: name.clone(),
                            index: *index,
                        },
                    ));
                }
            }
        }
    }
    edges
}

/// Reference-valued nested calls have no local binding. Keep their solved
/// return-to-parameter dependency explicit so late field/return lifting reaches
/// both method and constructor arguments in the same scheduled fixpoint.
fn call_result_argument_nullability_edges(
    constraints: &SignatureConstraintState,
    usage: &UsageFacts,
) -> Vec<(SignatureDependencyNode, SignatureDependencyNode)> {
    let mut edges = Vec::new();
    for caller in usage
        .method_entries()
        .map(|(_, u)| u)
        .chain(usage.constructor_entries().map(|(_, u)| u))
    {
        for call in caller.call_sites() {
            let Some(resolved) = call.resolved() else {
                continue;
            };
            let Some(callee) = method_key_for_resolved_call(constraints, resolved) else {
                continue;
            };
            let Some(params) = constraints.methods.get(&callee) else {
                continue;
            };
            for (index, result) in call.argument_result_calls() {
                let Some(name) = params.param_names.get(*index) else {
                    continue;
                };
                if matches!(
                    params.param_java_types.get(*index),
                    Some(JavaType::Primitive(_))
                ) || resolved_call_arg_is_expanded_varargs_element(resolved, params, *index)
                {
                    continue;
                }
                let Some(producer) = method_key_for_resolved_call(constraints, result) else {
                    continue;
                };
                edges.push((
                    SignatureDependencyNode::MethodReturn { method: producer },
                    SignatureDependencyNode::MethodParam {
                        method: callee.clone(),
                        name: name.clone(),
                        index: *index,
                    },
                ));
            }
        }
        for call in caller.constructor_call_sites() {
            let Some(resolved) = call.resolved() else {
                continue;
            };
            let callee = ConstructorKey::resolved_constructor(resolved);
            let Some(params) = constraints.constructors.get(&callee) else {
                continue;
            };
            for (index, result) in call.argument_result_calls() {
                let Some(name) = params.param_names.get(*index) else {
                    continue;
                };
                if matches!(
                    params.param_java_types.get(*index),
                    Some(JavaType::Primitive(_))
                ) || (resolved.params.get(*index).is_some_and(|p| p.is_varargs)
                    && !matches!(result.return_type, JavaType::Array(_)))
                {
                    continue;
                }
                let Some(producer) = method_key_for_resolved_call(constraints, result) else {
                    continue;
                };
                edges.push((
                    SignatureDependencyNode::MethodReturn { method: producer },
                    SignatureDependencyNode::ConstructorParam {
                        constructor: callee.clone(),
                        name: name.clone(),
                        index: *index,
                    },
                ));
            }
        }
    }
    edges
}

fn propagate_call_result_argument_nullability(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    let pending = call_result_argument_nullability_edges(constraints, usage)
        .into_iter()
        .filter_map(|(source, target)| {
            constraints_require_nullable_storage(
                collection_storage_node_constraints(constraints, &source).unwrap_or_default(),
            )
            .then_some(target)
        })
        .collect::<Vec<_>>();
    let mut changed = false;
    for target in pending {
        changed |= add_collection_storage_constraint_scoped(
            constraints,
            &target,
            SignatureConstraint::RequiredStorageNullability(NullabilityState::MaybeNull),
            scope,
        );
    }
    changed
}

fn call_result_storage_edges(
    constraints: &SignatureConstraintState,
    usage: &UsageFacts,
) -> Vec<(SignatureDependencyNode, SignatureDependencyNode)> {
    fn append(
        constraints: &SignatureConstraintState,
        facts: &MethodUsageFacts,
        caller: SignatureCallableKey,
        edges: &mut Vec<(SignatureDependencyNode, SignatureDependencyNode)>,
    ) {
        for assigned in facts.assigned_call_results() {
            let Some(resolved) = assigned.call.resolved() else {
                continue;
            };
            let Some(callee) = method_key_for_resolved_call(constraints, resolved) else {
                continue;
            };
            let Some(binding) = facts.binding_facts_for_declaration_id(&assigned.binding) else {
                continue;
            };
            let source = match &caller {
                SignatureCallableKey::Method(method) => {
                    method_binding_fact_dependency_node(constraints, method, binding)
                }
                SignatureCallableKey::Constructor(constructor) => {
                    constructor_binding_fact_dependency_node(constraints, constructor, binding)
                }
            };
            if let Some(source) = source {
                edges.push((
                    source,
                    SignatureDependencyNode::MethodReturn { method: callee },
                ));
            }
        }
    }
    let mut edges = constraints.initializer_storage_edges.clone();
    for (key, facts) in usage.method_entries() {
        if let Some(method) = method_key_for_usage(constraints, key) {
            // Returned calls (including conditional arms) forward the same
            // reference. Join placement demands before emitting either ABI.
            for returned in facts.returned_call_results() {
                let Some(resolved) = returned.resolved() else {
                    continue;
                };
                if matches!(
                    resolved.return_type,
                    JavaType::Void | JavaType::Primitive(_)
                ) {
                    continue;
                }
                if let Some(callee) = method_key_for_resolved_call(constraints, resolved) {
                    edges.push((
                        SignatureDependencyNode::MethodReturn {
                            method: method.clone(),
                        },
                        SignatureDependencyNode::MethodReturn { method: callee },
                    ));
                }
            }
            append(
                constraints,
                facts,
                SignatureCallableKey::Method(method),
                &mut edges,
            );
        }
    }
    for (key, facts) in usage.constructor_entries() {
        let constructor = ConstructorKey::from_usage_key(key);
        if constraints.constructors.contains_key(&constructor) {
            append(
                constraints,
                facts,
                SignatureCallableKey::Constructor(constructor),
                &mut edges,
            );
        }
    }
    edges
}

fn propagate_assigned_call_native_allocation(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    let mut pending = Vec::new();
    for (left, right) in call_result_storage_edges(constraints, usage) {
        let list_view = [&left, &right].iter().any(|node| {
            collection_storage_node_constraints(constraints, node)
                .unwrap_or_default()
                .contains(&SignatureConstraint::RequiredView(ViewShape::ListInterface))
        });
        for (source, target) in [(&left, &right), (&right, &left)] {
            for requirement in
                collection_storage_node_constraints(constraints, source).unwrap_or_default()
            {
                if matches!(
                    requirement,
                    SignatureConstraint::RequiredNativeAllocation(_)
                        | SignatureConstraint::RequiredNestedNativeAllocation { .. }
                        | SignatureConstraint::RequiredView(ViewShape::ListInterface)
                ) || (list_view && bulk_collection_element_constraint(requirement).is_some())
                {
                    pending.push((target.clone(), requirement.clone()));
                }
            }
        }
    }
    let mut changed = false;
    for (target, requirement) in pending {
        changed |=
            add_collection_storage_constraint_scoped(constraints, &target, requirement, scope);
    }
    changed
}

#[derive(Clone, Copy)]
enum CollectionStorageProjection {
    Value,
    Alias,
    MapView(usize),
    CallbackCapture,
    CallbackEnvironment,
}

type NativeCollectionStorageEndpoint = (SignatureDependencyNode, Vec<usize>, JavaType, JavaType);
type NativeCollectionStorageEdge = (
    NativeCollectionStorageEndpoint,
    NativeCollectionStorageEndpoint,
    bool,
    // View roots retain placement; the index maps a qualified map child to
    // collection element zero without joining unrelated key/value domains.
    CollectionStorageProjection,
);

fn native_collection_storage_edges(
    constraints: &SignatureConstraintState,
    usage: &UsageFacts,
) -> Vec<NativeCollectionStorageEdge> {
    collection_storage_edges(
        constraints,
        usage,
        CollectionStorageEdgeKind::NativeAllocation,
    )
}

#[derive(Clone, Copy)]
enum CollectionStorageEdgeKind {
    NativeAllocation,
    NullableTransfer,
    All,
}

/// Runtime and resolved Java owners can use dotted, binary or flattened
/// nested spellings. Preserve the complete source suffix and require a unique
/// field owner; a leaf-only Builder lookup cannot identify this storage node.
fn field_key_for_resolved_source(
    constraints: &SignatureConstraintState,
    owner: &str,
    name: &str,
) -> Option<FieldKey> {
    let exact = FieldKey::rust_identity(owner, name);
    if constraints.fields.contains_key(&exact) {
        return Some(exact);
    }
    let candidates = if let Some(index) = constraints.method_lookup_index.as_deref() {
        index
            .fields_by_name
            .get(&exact.field_name)
            .cloned()
            .unwrap_or_default()
    } else {
        constraints
            .fields
            .keys()
            .filter(|key| key.field_name == exact.field_name)
            .cloned()
            .collect()
    };
    let mut matching = candidates.into_iter().filter(|key| {
        crate::java_signature::nested_source_type_suffix_alias_matches(owner, key.type_name())
    });
    let first = matching.next()?;
    matching.next().is_none().then_some(first)
}

fn collection_storage_slot_dependency_node(
    constraints: &SignatureConstraintState,
    facts: &MethodUsageFacts,
    caller: &SignatureCallableKey,
    slot: &crate::usage::NativeCollectionStorageSlot,
) -> Option<SignatureDependencyNode> {
    use crate::usage::{CollectionArgumentOrigin, NativeCollectionStorageRoot};
    match &slot.root {
        NativeCollectionStorageRoot::MethodArgument { call, index } => {
            let method = method_key_for_resolved_call(constraints, call)?;
            let name = constraints
                .methods
                .get(&method)?
                .param_names
                .get(*index)?
                .clone();
            Some(SignatureDependencyNode::MethodParam {
                method,
                name,
                index: *index,
            })
        }
        NativeCollectionStorageRoot::ConstructorArgument { call, index } => {
            let constructor = ConstructorKey::resolved_constructor(call);
            let name = constraints
                .constructors
                .get(&constructor)?
                .param_names
                .get(*index)?
                .clone();
            Some(SignatureDependencyNode::ConstructorParam {
                constructor,
                name,
                index: *index,
            })
        }
        NativeCollectionStorageRoot::Return => match caller {
            SignatureCallableKey::Method(method) => Some(SignatureDependencyNode::MethodReturn {
                method: method.clone(),
            }),
            SignatureCallableKey::Constructor(_) => None,
        },
        NativeCollectionStorageRoot::Binding(binding) => {
            let binding = facts.binding_facts_for_declaration_id(binding)?;
            match caller {
                SignatureCallableKey::Method(method) => {
                    method_binding_fact_dependency_node(constraints, method, binding)
                }
                SignatureCallableKey::Constructor(constructor) => {
                    constructor_binding_fact_dependency_node(constraints, constructor, binding)
                }
            }
        }
        NativeCollectionStorageRoot::Origin(CollectionArgumentOrigin::MethodReturn(call)) => {
            Some(SignatureDependencyNode::MethodReturn {
                method: method_key_for_resolved_call(constraints, call)?,
            })
        }
        NativeCollectionStorageRoot::Origin(CollectionArgumentOrigin::Field { owner, name }) => {
            field_key_for_resolved_source(constraints, owner, name)
                .map(|field| SignatureDependencyNode::Field { field })
        }
    }
}

fn seed_native_list_projection_slots(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
) {
    let mut pending = Vec::new();
    let mut append = |facts: &MethodUsageFacts, caller: SignatureCallableKey| {
        for slot in facts.native_list_projection_slots() {
            if let Some(node) =
                collection_storage_slot_dependency_node(constraints, facts, &caller, slot)
            {
                pending.push(node);
            }
        }
    };
    for (key, facts) in usage.method_entries() {
        if let Some(key) = method_key_for_usage(constraints, key) {
            append(facts, SignatureCallableKey::Method(key));
        }
    }
    for (key, facts) in usage.constructor_entries() {
        let key = ConstructorKey::from_usage_key(key);
        if constraints.constructors.contains_key(&key) {
            append(facts, SignatureCallableKey::Constructor(key));
        }
    }
    for node in pending {
        add_collection_storage_constraint_scoped(
            constraints,
            &node,
            SignatureConstraint::RequiredView(ViewShape::ListInterface),
            None,
        );
    }
}

fn collection_storage_edges(
    constraints: &SignatureConstraintState,
    usage: &UsageFacts,
    kind: CollectionStorageEdgeKind,
) -> Vec<NativeCollectionStorageEdge> {
    let mut edges = Vec::new();
    let mut append = |facts: &MethodUsageFacts, caller: SignatureCallableKey| {
        for slot in facts
            .native_collection_retention_requirements()
            .iter()
            .filter(|_| !matches!(kind, CollectionStorageEdgeKind::NullableTransfer))
        {
            if let Some(node) =
                collection_storage_slot_dependency_node(constraints, facts, &caller, slot)
            {
                // A unary retention demand is a self-edge in the same
                // monotone storage graph; ordinary flow propagation can seed
                // it without a second field/return-specific solver.
                let endpoint = (
                    node,
                    slot.path.clone(),
                    slot.ty.clone(),
                    slot.root_ty.clone(),
                );
                edges.push((
                    endpoint.clone(),
                    endpoint,
                    true,
                    CollectionStorageProjection::Value,
                ));
            }
        }
        let additional = if !matches!(kind, CollectionStorageEdgeKind::NativeAllocation) {
            facts.nullable_collection_storage_flows()
        } else {
            &[]
        };
        for ((left, right), retain, projection) in facts
            .native_collection_storage_flows()
            .iter()
            .map(|edge| (edge, true, CollectionStorageProjection::Alias))
            .chain(
                facts
                    .native_collection_reference_transfers()
                    .iter()
                    .map(|edge| (edge, false, CollectionStorageProjection::Alias)),
            )
            .chain(
                additional
                    .iter()
                    .map(|edge| (edge, false, CollectionStorageProjection::Value)),
            )
            .chain(
                facts
                    .native_callback_capture_domains()
                    .iter()
                    .filter(|_| matches!(kind, CollectionStorageEdgeKind::NativeAllocation))
                    .map(|edge| (edge, false, CollectionStorageProjection::CallbackCapture)),
            )
            .chain(
                facts
                    .native_callback_environment_domains()
                    .iter()
                    .filter(|_| matches!(kind, CollectionStorageEdgeKind::NativeAllocation))
                    .map(|edge| {
                        (
                            edge,
                            false,
                            CollectionStorageProjection::CallbackEnvironment,
                        )
                    }),
            )
        {
            if let (Some(left_node), Some(right_node)) = (
                collection_storage_slot_dependency_node(constraints, facts, &caller, left),
                collection_storage_slot_dependency_node(constraints, facts, &caller, right),
            ) {
                edges.push((
                    (
                        left_node,
                        left.path.clone(),
                        left.ty.clone(),
                        left.root_ty.clone(),
                    ),
                    (
                        right_node,
                        right.path.clone(),
                        right.ty.clone(),
                        right.root_ty.clone(),
                    ),
                    retain,
                    projection,
                ));
            }
        }
        {
            for (left, right, child) in facts.native_collection_view_backings() {
                if let (Some(left_node), Some(right_node)) = (
                    collection_storage_slot_dependency_node(constraints, facts, &caller, left),
                    collection_storage_slot_dependency_node(constraints, facts, &caller, right),
                ) {
                    edges.push((
                        (
                            left_node,
                            left.path.clone(),
                            left.ty.clone(),
                            left.root_ty.clone(),
                        ),
                        (
                            right_node,
                            right.path.clone(),
                            right.ty.clone(),
                            right.root_ty.clone(),
                        ),
                        true,
                        CollectionStorageProjection::MapView(*child),
                    ));
                }
            }
        }
    };
    for (key, facts) in usage.method_entries() {
        if let Some(method) = method_key_for_usage(constraints, key) {
            append(facts, SignatureCallableKey::Method(method));
        }
    }
    for (key, facts) in usage.constructor_entries() {
        let constructor = ConstructorKey::from_usage_key(key);
        if constraints.constructors.contains_key(&constructor) {
            append(facts, SignatureCallableKey::Constructor(constructor));
        }
    }
    edges
}

fn add_collection_storage_constraint_scoped(
    constraints: &mut SignatureConstraintState,
    target: &SignatureDependencyNode,
    requirement: SignatureConstraint,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    match target {
        SignatureDependencyNode::MethodReturn { method } => {
            add_method_return_constraint_scoped(constraints, method, requirement, scope)
        }
        SignatureDependencyNode::MethodParam { method, index, .. } => {
            add_method_param_index_constraint_scoped(
                constraints,
                method,
                *index,
                requirement,
                scope,
            )
        }
        SignatureDependencyNode::ConstructorParam {
            constructor, name, ..
        } => add_constructor_param_constraint_scoped(
            constraints,
            constructor,
            name,
            requirement,
            scope,
        ),
        SignatureDependencyNode::MethodLocal {
            method,
            name,
            binding: Some(binding),
        } => add_method_local_constraint_by_binding_scoped(
            constraints,
            method,
            binding,
            name,
            requirement,
            scope,
        ),
        SignatureDependencyNode::ConstructorLocal {
            constructor,
            name,
            binding: Some(binding),
        } => add_constructor_local_constraint_by_binding_scoped(
            constraints,
            constructor,
            binding,
            name,
            requirement,
            scope,
        ),
        SignatureDependencyNode::Field { field } => add_field_constraint_scoped(
            constraints,
            field.owner.as_str(),
            &field.field_name,
            requirement,
            scope,
        ),
        _ => false,
    }
}

fn native_allocation_requirement(
    path: Vec<usize>,
    placement: crate::storage_strategy::StoragePlacement,
) -> SignatureConstraint {
    if path.is_empty() {
        SignatureConstraint::RequiredNativeAllocation(placement)
    } else {
        SignatureConstraint::RequiredNestedNativeAllocation { path, placement }
    }
}

/// Materialized Java array rows are nullable references, not rectangular
/// numeric views. Express that distinction in the existing child-nullability
/// vocabulary so rendering, construction and access consume the same shape.
fn native_array_row_nullability_requirement(
    root: &JavaType,
    path: &[usize],
) -> Option<SignatureConstraint> {
    let (&index, parent_path) = path.split_last()?;
    let parent = RustSlotShape::native_child_type_at_path(root, parent_path)?;
    let parent = optional_element_type(&parent).unwrap_or(parent);
    let JavaType::Array(row) = parent else {
        return None;
    };
    let row = optional_element_type(&row).unwrap_or(*row);
    (index == 0 && matches!(row, JavaType::Array(_)))
        .then(|| nullable_storage_requirement(root, path.to_vec()))
}

fn propagate_source_generic_allocations(
    constraints: &mut SignatureConstraintState,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    let mut pending = Vec::new();
    for edge in constraints.generic_allocation_edges.iter() {
        for requirement in
            collection_storage_node_constraints(constraints, &edge.source).unwrap_or_default()
        {
            let (path, placement) = match requirement {
                SignatureConstraint::RequiredNativeAllocation(placement) => (&[][..], *placement),
                SignatureConstraint::RequiredNestedNativeAllocation { path, placement } => {
                    (path.as_slice(), *placement)
                }
                _ => continue,
            };
            let Some(suffix) = path.strip_prefix(edge.source_path.as_slice()) else {
                continue;
            };
            if edge.source_argument.as_ref().is_some_and(|argument| {
                !crate::source_generic_allocations::native_argument_allocation_target(
                    argument, suffix,
                )
            }) {
                continue;
            }
            if edge.target_argument.as_ref().is_some_and(|argument| {
                !crate::source_generic_allocations::native_argument_allocation_target(
                    argument, suffix,
                )
            }) {
                continue;
            }
            let mut path = edge.target_path.clone();
            path.extend_from_slice(suffix);
            pending.push((
                edge.target.clone(),
                native_allocation_requirement(path, placement),
            ));
        }
    }
    let mut changed = false;
    for (target, requirement) in pending {
        changed |=
            add_collection_storage_constraint_scoped(constraints, &target, requirement, scope);
    }
    changed
}

fn propagate_native_collection_child_allocations(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    let mut pending = Vec::new();
    for (left, right, retain, root_only) in native_collection_storage_edges(constraints, usage) {
        // Java collection/array elements retain references even without an
        // Iterable view. Moving a copied Vec/Set here would lose later writes.
        let retained = crate::storage_strategy::StoragePlacement::new(true, true, false);
        for (direction, (source, target)) in
            [(&left, &right), (&right, &left)].into_iter().enumerate()
        {
            if matches!(root_only, CollectionStorageProjection::CallbackEnvironment)
                && direction == 0
            {
                // A synchronized callback requires synchronized captured
                // state; a local callback may freely retain an Arc. The
                // captured allocation does not force its other users to Sync.
                continue;
            }
            if retain {
                if let Some(requirement) =
                    native_array_row_nullability_requirement(&target.3, &target.1)
                {
                    pending.push((target.0.clone(), requirement));
                }
                pending.push((
                    target.0.clone(),
                    native_allocation_requirement(target.1.clone(), retained),
                ));
            }
            for constraint in
                collection_storage_node_constraints(constraints, &source.0).unwrap_or_default()
            {
                let (path, placement) = match constraint {
                    SignatureConstraint::RequiredNativeAllocation(placement) => {
                        (&[][..], *placement)
                    }
                    SignatureConstraint::RequiredNestedNativeAllocation { path, placement } => {
                        (path.as_slice(), *placement)
                    }
                    _ => continue,
                };
                if let Some(suffix) = path.strip_prefix(source.1.as_slice()) {
                    if matches!(
                        root_only,
                        CollectionStorageProjection::MapView(_)
                            | CollectionStorageProjection::CallbackCapture
                            | CollectionStorageProjection::CallbackEnvironment
                    ) && !suffix.is_empty()
                    {
                        continue;
                    }
                    if !RustSlotShape::native_child_type_at_path(&target.2, suffix).is_some_and(
                        |ty| {
                            let ty = optional_element_type(&ty).unwrap_or(ty);
                            matches!(ty, JavaType::Array(_))
                                || crate::stdlib::java_collection_kind_for_type(&ty).is_some()
                                || java_type_name_for_signature_dispatch(&ty).is_some_and(|name| {
                                    crate::stdlib::functional_interface_shape(
                                        &crate::stdlib::canonical_external_receiver_type_key(name),
                                    )
                                    .is_some()
                                })
                        },
                    ) {
                        continue;
                    }
                    let mut path = target.1.clone();
                    path.extend_from_slice(suffix);
                    if let Some(requirement) =
                        native_array_row_nullability_requirement(&target.3, &path)
                    {
                        pending.push((target.0.clone(), requirement));
                    }
                    pending.push((
                        target.0.clone(),
                        native_allocation_requirement(path, placement),
                    ));
                }
            }
        }
    }
    let mut changed = false;
    for (target, requirement) in pending {
        changed |=
            add_collection_storage_constraint_scoped(constraints, &target, requirement, scope);
    }
    changed
}

fn nullable_storage_constraint_path(
    root: &JavaType,
    constraint: &SignatureConstraint,
) -> Option<Vec<usize>> {
    let depth = match constraint {
        SignatureConstraint::NullableValueAtPath(path) => return Some(path.clone()),
        SignatureConstraint::NullableMapKey => return Some(vec![0]),
        SignatureConstraint::NullableSequenceElement => 0,
        SignatureConstraint::NullableSequenceElementAtDepth(depth) => *depth,
        _ => return None,
    };
    let mut ty = root.clone();
    let mut path = Vec::new();
    for _ in 0..=depth {
        let base = optional_element_type(&ty).unwrap_or(ty);
        let child = usize::from(crate::stdlib::java_map_type_args(&base).is_some());
        ty = RustSlotShape::native_child_type_at_path(&base, &[child])?;
        path.push(child);
    }
    Some(path)
}

fn nullable_storage_requirement(root: &JavaType, path: Vec<usize>) -> SignatureConstraint {
    if path.is_empty() {
        return SignatureConstraint::RequiredStorageNullability(NullabilityState::MaybeNull);
    }
    let base = optional_element_type(root).unwrap_or_else(|| root.clone());
    let map = crate::stdlib::java_map_type_args(&base).is_some();
    if path == [0] && map {
        SignatureConstraint::NullableMapKey
    } else if path == [usize::from(map)]
        && (map || crate::types::sequence_element_type(&base).is_some())
    {
        SignatureConstraint::NullableSequenceElement
    } else {
        SignatureConstraint::NullableValueAtPath(path)
    }
}

fn propagate_collection_element_transfer_nullability(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    fn sequence_path(ty: &JavaType, depth: usize) -> Option<Vec<usize>> {
        let mut ty = ty.clone();
        let mut path = Vec::new();
        for _ in 0..=depth {
            let base = optional_element_type(&ty).unwrap_or(ty);
            let child = usize::from(crate::stdlib::java_map_type_args(&base).is_some());
            ty = RustSlotShape::native_child_type_at_path(&base, &[child])?;
            path.push(child);
        }
        Some(path)
    }
    fn contains_map(ty: &JavaType) -> bool {
        crate::stdlib::java_map_type_args(ty).is_some()
            || match ty {
                JavaType::Named { args, .. } | JavaType::Intersection(args) => {
                    args.iter().any(contains_map)
                }
                JavaType::Array(element) => contains_map(element),
                _ => false,
            }
    }
    let mut pending = Vec::new();
    for (source, target, _, root_only) in collection_storage_edges(
        constraints,
        usage,
        CollectionStorageEdgeKind::NullableTransfer,
    ) {
        if matches!(root_only, CollectionStorageProjection::Alias) {
            for (source, target) in [(&source, &target), (&target, &source)] {
                for constraint in
                    collection_storage_node_constraints(constraints, &source.0).unwrap_or_default()
                {
                    let Some(path) = nullable_storage_constraint_path(&source.3, constraint) else {
                        continue;
                    };
                    let Some(suffix) = path.strip_prefix(source.1.as_slice()) else {
                        continue;
                    };
                    // Shared allocations have one descendant storage domain.
                    // Nullability of the reference binding itself is not a
                    // write into that allocation (a missing map result is not
                    // evidence that the map stores null at this key).
                    if suffix.is_empty() {
                        continue;
                    }
                    let mut path = target.1.clone();
                    path.extend_from_slice(suffix);
                    if RustSlotShape::native_child_type_at_path(&target.3, &path)
                        .is_some_and(|ty| !matches!(ty, JavaType::Primitive(_) | JavaType::Void))
                    {
                        pending.push((
                            target.0.clone(),
                            nullable_storage_requirement(&target.3, path),
                        ));
                    }
                }
            }
            continue;
        }
        if let CollectionStorageProjection::MapView(view_child) = root_only {
            // A key view maps the qualified key child, not the legacy
            // NullableSequenceElement constraint used for a map's values.
            for (source, target) in [(&source, &target), (&target, &source)] {
                let base = optional_element_type(&source.2).unwrap_or_else(|| source.2.clone());
                let source_map = crate::stdlib::java_map_type_args(&base).is_some();
                let target_base =
                    optional_element_type(&target.2).unwrap_or_else(|| target.2.clone());
                let target_map = crate::stdlib::java_map_type_args(&target_base).is_some();
                let source_child = if source_map { view_child } else { 0 };
                let target_child = if target_map { view_child } else { 0 };
                let mut nullable_paths = Vec::new();
                if RustSlotShape::native_child_type_at_path(&source.2, &[source_child])
                    .is_some_and(|ty| optional_element_type(&ty).is_some())
                {
                    let mut path = source.1.clone();
                    path.push(source_child);
                    nullable_paths.push(path);
                }
                for constraint in
                    collection_storage_node_constraints(constraints, &source.0).unwrap_or_default()
                {
                    let path = match constraint {
                        SignatureConstraint::NullableMapKey
                            if source_map && source_child == 0 && source.1.is_empty() =>
                        {
                            vec![0]
                        }
                        SignatureConstraint::NullableSequenceElement
                            if (!source_map || source_child == 1) && source.1.is_empty() =>
                        {
                            vec![source_child]
                        }
                        SignatureConstraint::NullableSequenceElementAtDepth(depth)
                            if (!source_map || source_child == 1) && source.1.is_empty() =>
                        {
                            let Some(path) = sequence_path(&source.2, *depth) else {
                                continue;
                            };
                            path
                        }
                        SignatureConstraint::NullableValueAtPath(path) => path.clone(),
                        _ => continue,
                    };
                    nullable_paths.push(path);
                }
                let mut key_prefix = source.1.clone();
                key_prefix.push(source_child);
                for path in nullable_paths {
                    let Some(suffix) = path.strip_prefix(key_prefix.as_slice()) else {
                        continue;
                    };
                    let Some(key) =
                        RustSlotShape::native_child_type_at_path(&target.2, &[target_child])
                    else {
                        continue;
                    };
                    let Some(ty) = RustSlotShape::native_child_type_at_path(&key, suffix) else {
                        continue;
                    };
                    if matches!(ty, JavaType::Primitive(_) | JavaType::Void) {
                        continue;
                    }
                    let mut path = target.1.clone();
                    path.push(target_child);
                    path.extend_from_slice(suffix);
                    let requirement = nullable_storage_requirement(&target.3, path);
                    pending.push((target.0.clone(), requirement));
                }
            }
            continue;
        }
        // Sequence depth constraints address map values differently from
        // structural child indexes. Leave map-key/value qualification to its
        // existing dedicated solver until that mapping is explicit here.
        if contains_map(&source.2) || contains_map(&target.2) {
            continue;
        }
        // Projected storage can carry an intrinsic Option before a node has
        // an explicit nullable constraint (reference-array elements do).
        // Transfer that domain without reinterpreting or copying its payload.
        if crate::types::optional_element_type(&source.2).is_some()
            && !matches!(target.2, JavaType::Primitive(_) | JavaType::Void)
        {
            let requirement = nullable_storage_requirement(&target.3, target.1.clone());
            pending.push((target.0.clone(), requirement));
        }
        // A copied element flows only from source to destination. The native
        // allocation graph also includes retention and insertion edges; those
        // constrain physical placement, not bidirectional nullable value flow.
        // Reusing them here would let an unrelated nullable destination widen
        // every upstream collection, including non-null filtered sources.
        {
            for constraint in
                collection_storage_node_constraints(constraints, &source.0).unwrap_or_default()
            {
                let path = match constraint {
                    SignatureConstraint::RequiredStorageNullability(
                        NullabilityState::DefinitelyNull | NullabilityState::MaybeNull,
                    ) => vec![],
                    SignatureConstraint::NullableSequenceElement => vec![0],
                    SignatureConstraint::NullableSequenceElementAtDepth(depth) => {
                        vec![0; depth + 1]
                    }
                    SignatureConstraint::NullableValueAtPath(path) => path.clone(),
                    _ => continue,
                };
                let Some(suffix) = path.strip_prefix(source.1.as_slice()) else {
                    continue;
                };
                // Qualifiers cannot grow beyond the declared child shape.
                // Primitive/unboxed values cannot acquire Java null storage.
                let Some(ty) = RustSlotShape::native_child_type_at_path(&target.2, suffix) else {
                    continue;
                };
                if matches!(ty, JavaType::Primitive(_) | JavaType::Void) {
                    continue;
                }
                let mut path = target.1.clone();
                path.extend_from_slice(suffix);
                let requirement = nullable_storage_requirement(&target.3, path);
                pending.push((target.0.clone(), requirement));
            }
        }
    }
    let mut changed = false;
    for (target, requirement) in pending {
        changed |=
            add_collection_storage_constraint_scoped(constraints, &target, requirement, scope);
    }
    changed
}

fn collection_storage_node_constraints<'a>(
    constraints: &'a SignatureConstraintState,
    node: &SignatureDependencyNode,
) -> Option<&'a [SignatureConstraint]> {
    match node {
        SignatureDependencyNode::MethodReturn { method } => {
            Some(&constraints.methods.get(method)?.return_constraints)
        }
        SignatureDependencyNode::MethodParam { method, index, .. } => {
            Some(constraints.methods.get(method)?.params.get(*index)?)
        }
        SignatureDependencyNode::ConstructorParam {
            constructor, index, ..
        } => Some(
            constraints
                .constructors
                .get(constructor)?
                .params
                .get(*index)?,
        ),
        SignatureDependencyNode::Field { field } => Some(constraints.fields.get(field)?),
        SignatureDependencyNode::MethodLocal {
            method,
            binding: Some(binding),
            ..
        } => Some(
            &constraints
                .methods
                .get(method)?
                .local_by_binding(binding)?
                .constraints,
        ),
        SignatureDependencyNode::ConstructorLocal {
            constructor,
            binding: Some(binding),
            ..
        } => Some(
            &constraints
                .constructors
                .get(constructor)?
                .local_by_binding(binding)?
                .constraints,
        ),
        _ => None,
    }
}

fn propagate_collection_argument_origin_storage(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    let mut pending = Vec::new();
    for (left, right) in collection_argument_storage_edges(constraints, usage) {
        for (source, target) in [(&left, &right), (&right, &left)] {
            for constraint in
                collection_storage_node_constraints(constraints, source).unwrap_or_default()
            {
                if matches!(
                    constraint,
                    SignatureConstraint::NullableSequenceElement
                        | SignatureConstraint::NullableSequenceElementAtDepth(_)
                        | SignatureConstraint::NullableValueAtPath(_)
                        | SignatureConstraint::NullableMapKey
                        | SignatureConstraint::RequiredNativeAllocation(_)
                        | SignatureConstraint::RequiredNestedNativeAllocation { .. }
                ) {
                    pending.push((target.clone(), constraint.clone()));
                }
            }
        }
    }
    let mut changed = false;
    for (target, constraint) in pending {
        changed |= match target {
            SignatureDependencyNode::MethodReturn { method } => {
                add_method_return_constraint_scoped(constraints, &method, constraint, scope)
            }
            SignatureDependencyNode::MethodParam { method, index, .. } => {
                add_method_param_index_constraint_scoped(
                    constraints,
                    &method,
                    index,
                    constraint,
                    scope,
                )
            }
            SignatureDependencyNode::ConstructorParam {
                constructor, name, ..
            } => add_constructor_param_constraint_scoped(
                constraints,
                &constructor,
                &name,
                constraint,
                scope,
            ),
            SignatureDependencyNode::Field { field } => add_field_constraint_scoped(
                constraints,
                field.owner.as_str(),
                &field.field_name,
                constraint,
                scope,
            ),
            _ => false,
        };
    }
    changed
}

fn bulk_collection_argument_index(
    kind: crate::stdlib::JavaCollectionKind,
    method_name: &str,
    arg_count: usize,
) -> Option<usize> {
    use crate::stdlib::JavaCollectionKind;

    match kind {
        JavaCollectionKind::List => match (method_name, arg_count) {
            ("addAll" | "add_all", 1) => Some(0),
            ("addAll" | "add_all", 2) => Some(1),
            _ => None,
        },
        JavaCollectionKind::Set | JavaCollectionKind::InsertionOrderedSet => {
            matches!((method_name, arg_count), ("addAll" | "add_all", 1)).then_some(0)
        }
        JavaCollectionKind::Map
        | JavaCollectionKind::SortedMap
        | JavaCollectionKind::InsertionOrderedMap
        | JavaCollectionKind::SortedSet => None,
    }
}

fn bulk_collection_element_constraint(
    constraint: &SignatureConstraint,
) -> Option<SignatureConstraint> {
    matches!(
        constraint,
        SignatureConstraint::NullableSequenceElement
            | SignatureConstraint::NullableSequenceElementAtDepth(_)
            | SignatureConstraint::NullableValueAtPath(_)
    )
    .then(|| constraint.clone())
}

fn binding_stores_nullable_collection_element(
    collection: &BindingUseFacts,
    usage: &MethodUsageFacts,
    constraints: &MethodConstraintSet,
) -> bool {
    let Some(kind) = crate::stdlib::java_collection_kind_for_type(collection.java_ty()) else {
        return false;
    };
    collection.uses().iter().any(|receiver_use| {
        let BindingUse::ReceiverForCall {
            name,
            arg_count,
            literal_null_arg_indices,
            argument_bindings,
            nullable_source_call_arg_indices,
            ..
        } = receiver_use
        else {
            return false;
        };
        let Some(element_index) =
            nullable_collection_element_argument_index(kind, name, *arg_count)
        else {
            return false;
        };
        literal_null_arg_indices.contains(&element_index)
            || nullable_source_call_arg_indices.contains(&element_index)
            || argument_bindings.iter().any(|(index, argument_binding)| {
                *index == element_index
                    && usage
                        .binding_facts_for_declaration_id(argument_binding)
                        .is_some_and(|argument| {
                            method_binding_has_nullable_storage(constraints, argument)
                        })
            })
    })
}

fn constructor_binding_stores_nullable_collection_element(
    collection: &BindingUseFacts,
    usage: &MethodUsageFacts,
    constraints: &ConstructorConstraintSet,
) -> bool {
    let Some(kind) = crate::stdlib::java_collection_kind_for_type(collection.java_ty()) else {
        return false;
    };
    collection.uses().iter().any(|receiver_use| {
        let BindingUse::ReceiverForCall {
            name,
            arg_count,
            literal_null_arg_indices,
            argument_bindings,
            nullable_source_call_arg_indices,
            ..
        } = receiver_use
        else {
            return false;
        };
        let Some(element_index) =
            nullable_collection_element_argument_index(kind, name, *arg_count)
        else {
            return false;
        };
        literal_null_arg_indices.contains(&element_index)
            || nullable_source_call_arg_indices.contains(&element_index)
            || argument_bindings.iter().any(|(index, argument_binding)| {
                *index == element_index
                    && usage
                        .binding_facts_for_declaration_id(argument_binding)
                        .is_some_and(|argument| {
                            constructor_binding_has_nullable_storage(constraints, argument)
                        })
            })
    })
}

fn binding_receives_call_named(binding: &BindingUseFacts, expected: &str) -> bool {
    binding
        .uses()
        .iter()
        .any(|usage| matches!(usage, BindingUse::AssignedFromCall { name, .. } if name == expected))
}

fn binding_is_nullable_sequence_call_receiver(
    binding: &BindingUseFacts,
    expected: &str,
    has_constraint: impl Fn(&BindingUseFacts) -> bool,
) -> bool {
    has_constraint(binding)
        && binding.uses().iter().any(
            |usage| matches!(usage, BindingUse::ReceiverForCall { name, .. } if name == expected),
        )
}

fn propagate_nullable_collection_element_carriers(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    let element_constraint = SignatureConstraint::NullableSequenceElement;
    let mut method_bindings = Vec::new();
    let mut constructor_bindings = Vec::new();
    let mut method_params = Vec::new();
    let mut constructor_params = Vec::new();
    let mut fields = Vec::new();
    let mut nullable_method_results = Vec::new();
    let mut nullable_constructor_results = Vec::new();

    for (usage_key, method_usage) in usage.method_entries() {
        let Some(caller_key) = method_key_for_usage(constraints, usage_key) else {
            continue;
        };
        let Some(caller_constraints) = constraints.methods.get(&caller_key) else {
            continue;
        };
        for binding in method_usage.all_binding_facts() {
            if binding.binding().is_some()
                && binding_stores_nullable_collection_element(
                    binding,
                    method_usage,
                    caller_constraints,
                )
            {
                method_bindings.push((caller_key.clone(), binding.clone()));
            }
            let Some(kind) = crate::stdlib::java_collection_kind_for_type(binding.java_ty()) else {
                continue;
            };
            for binding_use in binding.uses() {
                let BindingUse::ReceiverForCall {
                    name,
                    arg_count,
                    argument_bindings,
                    ..
                } = binding_use
                else {
                    continue;
                };
                let Some(element_index) = bulk_collection_argument_index(kind, name, *arg_count)
                else {
                    continue;
                };
                let Some((_, source_binding_id)) = argument_bindings
                    .iter()
                    .find(|(index, _)| *index == element_index)
                else {
                    continue;
                };
                let Some(source_binding) =
                    method_usage.binding_facts_for_declaration_id(source_binding_id)
                else {
                    continue;
                };
                if method_binding_fact_slot_requirements(caller_constraints, source_binding)
                    .into_iter()
                    .any(|constraint| bulk_collection_element_constraint(constraint).is_some())
                {
                    method_bindings.push((caller_key.clone(), binding.clone()));
                }
            }
        }
        let nullable_iterator_created =
            method_usage.all_binding_facts().into_iter().any(|binding| {
                binding_is_nullable_sequence_call_receiver(binding, "iterator", |binding| {
                    method_binding_has_constraint(caller_constraints, binding, &element_constraint)
                })
            });
        if nullable_iterator_created {
            method_bindings.extend(
                method_usage
                    .all_binding_facts()
                    .into_iter()
                    .filter(|binding| binding_receives_call_named(binding, "iterator"))
                    .map(|binding| (caller_key.clone(), binding.clone())),
            );
        }
        let nullable_iterator_advanced =
            method_usage.all_binding_facts().into_iter().any(|binding| {
                binding_is_nullable_sequence_call_receiver(binding, "next", |binding| {
                    method_binding_has_constraint(caller_constraints, binding, &element_constraint)
                })
            });
        if nullable_iterator_advanced {
            nullable_method_results.extend(
                method_usage
                    .all_binding_facts()
                    .into_iter()
                    .filter(|binding| binding_receives_call_named(binding, "next"))
                    .map(|binding| (caller_key.clone(), binding.clone())),
            );
        }
        for call_site in method_usage.call_sites() {
            let Some(callee_key) = call_site
                .resolved()
                .and_then(|resolved| method_key_for_resolved_call(constraints, resolved))
            else {
                continue;
            };
            let Some(callee_constraints) = constraints.methods.get(&callee_key) else {
                continue;
            };
            for (index, binding_id) in call_site.argument_bindings() {
                let Some(binding) = method_usage.binding_facts_for_declaration_id(binding_id)
                else {
                    continue;
                };
                if method_binding_has_constraint(caller_constraints, binding, &element_constraint)
                    && let Some(param_name) = callee_constraints.param_names.get(*index)
                {
                    method_params.push((callee_key.clone(), param_name.clone()));
                }
                if callee_constraints
                    .params
                    .get(*index)
                    .is_some_and(|param| param.contains(&element_constraint))
                {
                    method_bindings.push((caller_key.clone(), binding.clone()));
                }
            }
            for (index, field_name) in call_site.argument_self_fields() {
                let field_key = FieldKey::rust_identity(caller_key.type_name(), field_name);
                if constraints
                    .fields
                    .get(&field_key)
                    .is_some_and(|field| field.contains(&element_constraint))
                    && let Some(param_name) = callee_constraints.param_names.get(*index)
                {
                    method_params.push((callee_key.clone(), param_name.clone()));
                }
                if callee_constraints
                    .params
                    .get(*index)
                    .is_some_and(|param| param.contains(&element_constraint))
                {
                    fields.push((caller_key.type_name().to_string(), field_name.clone()));
                }
            }
        }
        for call_site in method_usage.constructor_call_sites() {
            let Some(callee_key) = call_site
                .resolved()
                .map(ConstructorKey::resolved_constructor)
            else {
                continue;
            };
            let Some(callee_constraints) = constraints.constructors.get(&callee_key) else {
                continue;
            };
            for (index, binding_id) in call_site.argument_bindings() {
                let Some(binding) = method_usage.binding_facts_for_declaration_id(binding_id)
                else {
                    continue;
                };
                if method_binding_has_constraint(caller_constraints, binding, &element_constraint)
                    && let Some(param_name) = callee_constraints.param_names.get(*index)
                {
                    constructor_params.push((callee_key.clone(), param_name.clone()));
                }
                if callee_constraints
                    .params
                    .get(*index)
                    .is_some_and(|param| param.contains(&element_constraint))
                {
                    method_bindings.push((caller_key.clone(), binding.clone()));
                }
            }
            for (index, field_name) in call_site.argument_self_fields() {
                let field_key = FieldKey::rust_identity(caller_key.type_name(), field_name);
                if constraints
                    .fields
                    .get(&field_key)
                    .is_some_and(|field| field.contains(&element_constraint))
                    && let Some(param_name) = callee_constraints.param_names.get(*index)
                {
                    constructor_params.push((callee_key.clone(), param_name.clone()));
                }
                if callee_constraints
                    .params
                    .get(*index)
                    .is_some_and(|param| param.contains(&element_constraint))
                {
                    fields.push((caller_key.type_name().to_string(), field_name.clone()));
                }
            }
        }
    }

    for (usage_key, constructor_usage) in usage.constructor_entries() {
        let caller_key = ConstructorKey::from_usage_key(usage_key);
        let Some(caller_constraints) = constraints.constructors.get(&caller_key) else {
            continue;
        };
        for binding in constructor_usage.all_binding_facts() {
            if binding.binding().is_some()
                && constructor_binding_stores_nullable_collection_element(
                    binding,
                    constructor_usage,
                    caller_constraints,
                )
            {
                constructor_bindings.push((caller_key.clone(), binding.clone()));
            }
            let Some(kind) = crate::stdlib::java_collection_kind_for_type(binding.java_ty()) else {
                continue;
            };
            for binding_use in binding.uses() {
                let BindingUse::ReceiverForCall {
                    name,
                    arg_count,
                    argument_bindings,
                    ..
                } = binding_use
                else {
                    continue;
                };
                let Some(element_index) = bulk_collection_argument_index(kind, name, *arg_count)
                else {
                    continue;
                };
                let Some((_, source_binding_id)) = argument_bindings
                    .iter()
                    .find(|(index, _)| *index == element_index)
                else {
                    continue;
                };
                let Some(source_binding) =
                    constructor_usage.binding_facts_for_declaration_id(source_binding_id)
                else {
                    continue;
                };
                if constructor_binding_fact_slot_requirements(caller_constraints, source_binding)
                    .into_iter()
                    .any(|constraint| bulk_collection_element_constraint(constraint).is_some())
                {
                    constructor_bindings.push((caller_key.clone(), binding.clone()));
                }
            }
        }
        let nullable_iterator_created =
            constructor_usage
                .all_binding_facts()
                .into_iter()
                .any(|binding| {
                    binding_is_nullable_sequence_call_receiver(binding, "iterator", |binding| {
                        constructor_binding_has_constraint(
                            caller_constraints,
                            binding,
                            &element_constraint,
                        )
                    })
                });
        if nullable_iterator_created {
            constructor_bindings.extend(
                constructor_usage
                    .all_binding_facts()
                    .into_iter()
                    .filter(|binding| binding_receives_call_named(binding, "iterator"))
                    .map(|binding| (caller_key.clone(), binding.clone())),
            );
        }
        let nullable_iterator_advanced =
            constructor_usage
                .all_binding_facts()
                .into_iter()
                .any(|binding| {
                    binding_is_nullable_sequence_call_receiver(binding, "next", |binding| {
                        constructor_binding_has_constraint(
                            caller_constraints,
                            binding,
                            &element_constraint,
                        )
                    })
                });
        if nullable_iterator_advanced {
            nullable_constructor_results.extend(
                constructor_usage
                    .all_binding_facts()
                    .into_iter()
                    .filter(|binding| binding_receives_call_named(binding, "next"))
                    .map(|binding| (caller_key.clone(), binding.clone())),
            );
        }
        for call_site in constructor_usage.call_sites() {
            let Some(callee_key) = call_site
                .resolved()
                .and_then(|resolved| method_key_for_resolved_call(constraints, resolved))
            else {
                continue;
            };
            let Some(callee_constraints) = constraints.methods.get(&callee_key) else {
                continue;
            };
            for (index, binding_id) in call_site.argument_bindings() {
                let Some(binding) = constructor_usage.binding_facts_for_declaration_id(binding_id)
                else {
                    continue;
                };
                if constructor_binding_has_constraint(
                    caller_constraints,
                    binding,
                    &element_constraint,
                ) && let Some(param_name) = callee_constraints.param_names.get(*index)
                {
                    method_params.push((callee_key.clone(), param_name.clone()));
                }
                if callee_constraints
                    .params
                    .get(*index)
                    .is_some_and(|param| param.contains(&element_constraint))
                {
                    constructor_bindings.push((caller_key.clone(), binding.clone()));
                }
            }
            for (index, field_name) in call_site.argument_self_fields() {
                let field_key = FieldKey::rust_identity(caller_key.type_name(), field_name);
                if constraints
                    .fields
                    .get(&field_key)
                    .is_some_and(|field| field.contains(&element_constraint))
                    && let Some(param_name) = callee_constraints.param_names.get(*index)
                {
                    method_params.push((callee_key.clone(), param_name.clone()));
                }
                if callee_constraints
                    .params
                    .get(*index)
                    .is_some_and(|param| param.contains(&element_constraint))
                {
                    fields.push((caller_key.type_name().to_string(), field_name.clone()));
                }
            }
        }
        for call_site in constructor_usage.constructor_call_sites() {
            let Some(callee_key) = call_site
                .resolved()
                .map(ConstructorKey::resolved_constructor)
            else {
                continue;
            };
            let Some(callee_constraints) = constraints.constructors.get(&callee_key) else {
                continue;
            };
            for (index, binding_id) in call_site.argument_bindings() {
                let Some(binding) = constructor_usage.binding_facts_for_declaration_id(binding_id)
                else {
                    continue;
                };
                if constructor_binding_has_constraint(
                    caller_constraints,
                    binding,
                    &element_constraint,
                ) && let Some(param_name) = callee_constraints.param_names.get(*index)
                {
                    constructor_params.push((callee_key.clone(), param_name.clone()));
                }
                if callee_constraints
                    .params
                    .get(*index)
                    .is_some_and(|param| param.contains(&element_constraint))
                {
                    constructor_bindings.push((caller_key.clone(), binding.clone()));
                }
            }
            for (index, field_name) in call_site.argument_self_fields() {
                let field_key = FieldKey::rust_identity(caller_key.type_name(), field_name);
                if constraints
                    .fields
                    .get(&field_key)
                    .is_some_and(|field| field.contains(&element_constraint))
                    && let Some(param_name) = callee_constraints.param_names.get(*index)
                {
                    constructor_params.push((callee_key.clone(), param_name.clone()));
                }
                if callee_constraints
                    .params
                    .get(*index)
                    .is_some_and(|param| param.contains(&element_constraint))
                {
                    fields.push((caller_key.type_name().to_string(), field_name.clone()));
                }
            }
        }
    }

    let mut changed = false;
    for (key, binding) in method_bindings {
        changed |= add_method_binding_fact_constraint_scoped(
            constraints,
            &key,
            &binding,
            element_constraint.clone(),
            scope,
        );
    }
    for (key, binding) in constructor_bindings {
        changed |= add_constructor_binding_fact_constraint_scoped(
            constraints,
            &key,
            &binding,
            element_constraint.clone(),
            scope,
        );
    }
    for (key, binding) in nullable_method_results {
        changed |= add_method_binding_fact_constraint_scoped(
            constraints,
            &key,
            &binding,
            SignatureConstraint::RequiredStorageNullability(NullabilityState::MaybeNull),
            scope,
        );
    }
    for (key, binding) in nullable_constructor_results {
        changed |= add_constructor_binding_fact_constraint_scoped(
            constraints,
            &key,
            &binding,
            SignatureConstraint::RequiredStorageNullability(NullabilityState::MaybeNull),
            scope,
        );
    }
    for (key, param_name) in method_params {
        changed |= add_method_param_constraint_scoped(
            constraints,
            &key,
            &param_name,
            element_constraint.clone(),
            scope,
        );
    }
    for (key, param_name) in constructor_params {
        changed |= add_constructor_param_constraint_scoped(
            constraints,
            &key,
            &param_name,
            element_constraint.clone(),
            scope,
        );
    }
    for (type_name, field_name) in fields {
        changed |= add_field_constraint_scoped(
            constraints,
            &type_name,
            &field_name,
            element_constraint.clone(),
            scope,
        );
    }
    changed
}

fn nested_collection_constraint_from_argument(
    constraint: &SignatureConstraint,
    kind: crate::stdlib::JavaCollectionKind,
) -> Option<SignatureConstraint> {
    match constraint {
        SignatureConstraint::RequiredStorageNullability(
            NullabilityState::DefinitelyNull | NullabilityState::MaybeNull,
        ) => Some(SignatureConstraint::NullableSequenceElement),
        SignatureConstraint::NullableSequenceElement => {
            Some(SignatureConstraint::NullableSequenceElementAtDepth(1))
        }
        SignatureConstraint::NullableSequenceElementAtDepth(depth) => Some(
            SignatureConstraint::NullableSequenceElementAtDepth(depth + 1),
        ),
        SignatureConstraint::NullableValueAtPath(path) => {
            let child = if matches!(
                kind,
                crate::stdlib::JavaCollectionKind::Map
                    | crate::stdlib::JavaCollectionKind::SortedMap
                    | crate::stdlib::JavaCollectionKind::InsertionOrderedMap
            ) {
                1
            } else {
                0
            };
            let mut nested = vec![child];
            nested.extend_from_slice(path);
            Some(SignatureConstraint::NullableValueAtPath(nested))
        }
        _ => None,
    }
}

fn propagate_nested_nullable_collection_element_carriers(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    if scope.is_some_and(|scope| !scope.has_field_target()) {
        return false;
    }
    let mut pending = Vec::new();
    for (usage_key, method_usage) in usage.method_entries() {
        let Some(method_key) = method_key_for_usage(constraints, usage_key) else {
            continue;
        };
        let Some(method_constraints) = constraints.methods.get(&method_key) else {
            continue;
        };
        for field_use in method_usage.field_uses() {
            let FieldUse::ReceiverForCall {
                field_name,
                receiver_type: Some(receiver_type),
                name,
                arg_count,
                literal_null_arg_indices,
                argument_bindings,
                non_null_arg_indices,
                nullable_source_call_arg_indices,
            } = field_use
            else {
                continue;
            };
            let Some(kind) = crate::stdlib::java_collection_kind_for_type(receiver_type) else {
                continue;
            };
            if let Some(element_index) = bulk_collection_argument_index(kind, name, *arg_count)
                && let Some((_, argument_binding)) = argument_bindings
                    .iter()
                    .find(|(index, _)| *index == element_index)
                && let Some(binding) =
                    method_usage.binding_facts_for_declaration_id(argument_binding)
            {
                for constraint in method_binding_fact_slot_requirements(method_constraints, binding)
                {
                    if let Some(element_constraint) = bulk_collection_element_constraint(constraint)
                    {
                        pending.push((
                            method_key.type_name().to_string(),
                            field_name.clone(),
                            element_constraint,
                        ));
                    }
                }
            }
            let Some(element_index) =
                nullable_collection_element_argument_index(kind, name, *arg_count)
            else {
                continue;
            };
            if literal_null_arg_indices.contains(&element_index)
                || nullable_source_call_arg_indices.contains(&element_index)
            {
                pending.push((
                    method_key.type_name().to_string(),
                    field_name.clone(),
                    SignatureConstraint::NullableSequenceElement,
                ));
            }
            if non_null_arg_indices.contains(&element_index) {
                continue;
            }
            let Some((_, argument_binding)) = argument_bindings
                .iter()
                .find(|(index, _)| *index == element_index)
            else {
                continue;
            };
            let Some(binding) = method_usage.binding_facts_for_declaration_id(argument_binding)
            else {
                continue;
            };
            for constraint in method_binding_fact_slot_requirements(method_constraints, binding) {
                if let Some(nested) = nested_collection_constraint_from_argument(constraint, kind) {
                    pending.push((
                        method_key.type_name().to_string(),
                        field_name.clone(),
                        nested,
                    ));
                }
            }
        }
    }
    for (usage_key, constructor_usage) in usage.constructor_entries() {
        let key = ConstructorKey::from_usage_key(usage_key);
        let Some(constructor_constraints) = constraints.constructors.get(&key) else {
            continue;
        };
        for field_use in constructor_usage.field_uses() {
            let FieldUse::ReceiverForCall {
                field_name,
                receiver_type: Some(receiver_type),
                name,
                arg_count,
                literal_null_arg_indices,
                argument_bindings,
                non_null_arg_indices,
                nullable_source_call_arg_indices,
            } = field_use
            else {
                continue;
            };
            let Some(kind) = crate::stdlib::java_collection_kind_for_type(receiver_type) else {
                continue;
            };
            if let Some(element_index) = bulk_collection_argument_index(kind, name, *arg_count)
                && let Some((_, argument_binding)) = argument_bindings
                    .iter()
                    .find(|(index, _)| *index == element_index)
                && let Some(binding) =
                    constructor_usage.binding_facts_for_declaration_id(argument_binding)
            {
                for constraint in
                    constructor_binding_fact_slot_requirements(constructor_constraints, binding)
                {
                    if let Some(element_constraint) = bulk_collection_element_constraint(constraint)
                    {
                        pending.push((
                            key.type_name().to_string(),
                            field_name.clone(),
                            element_constraint,
                        ));
                    }
                }
            }
            let Some(element_index) =
                nullable_collection_element_argument_index(kind, name, *arg_count)
            else {
                continue;
            };
            if literal_null_arg_indices.contains(&element_index)
                || nullable_source_call_arg_indices.contains(&element_index)
            {
                pending.push((
                    key.type_name().to_string(),
                    field_name.clone(),
                    SignatureConstraint::NullableSequenceElement,
                ));
            }
            if non_null_arg_indices.contains(&element_index) {
                continue;
            }
            let Some((_, argument_binding)) = argument_bindings
                .iter()
                .find(|(index, _)| *index == element_index)
            else {
                continue;
            };
            let Some(binding) =
                constructor_usage.binding_facts_for_declaration_id(argument_binding)
            else {
                continue;
            };
            for constraint in
                constructor_binding_fact_slot_requirements(constructor_constraints, binding)
            {
                if let Some(nested) = nested_collection_constraint_from_argument(constraint, kind) {
                    pending.push((key.type_name().to_string(), field_name.clone(), nested));
                }
            }
        }
    }
    let mut changed = false;
    for (type_name, field_name, constraint) in pending {
        changed |=
            add_field_constraint_scoped(constraints, &type_name, &field_name, constraint, scope);
    }
    changed
}

fn propagate_call_result_constraints_to_bindings(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    if scope.is_some_and(|scope| !scope.has_method_binding_target()) {
        return false;
    }
    let mut pending = Vec::new();
    for (usage_key, method_usage) in usage.method_entries() {
        let Some(method_key) = method_key_for_usage(constraints, usage_key) else {
            continue;
        };
        for binding in method_usage.all_binding_facts() {
            for use_site in binding.uses() {
                let BindingUse::AssignedFromCall { name, boundary, .. } = use_site else {
                    continue;
                };
                for constraint in internal_call_return_constraints_for_binding(
                    constraints,
                    method_usage,
                    name,
                    *boundary,
                    binding,
                    Some(method_key.type_name()),
                ) {
                    pending.push((method_key.clone(), binding.clone(), constraint.clone()));
                }
            }
        }
    }
    let mut changed = false;
    for (method_key, binding, constraint) in pending {
        let applied = add_method_binding_fact_constraint_scoped(
            constraints,
            &method_key,
            &binding,
            constraint.clone(),
            scope,
        );
        changed |= applied;
        if !applied
            && constraints
                .methods
                .get(&method_key)
                .and_then(|method_constraints| method_constraints.param_index(binding.name()))
                .is_some()
        {
            changed |=
                add_method_param_constraint(constraints, &method_key, binding.name(), constraint);
        }
    }
    changed
}

fn propagate_constructor_call_result_constraints_to_bindings(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    if scope.is_some_and(|scope| !scope.has_constructor_binding_target()) {
        return false;
    }
    let mut pending = Vec::new();
    for (constructor_key, constructor_usage) in usage.constructor_entries() {
        let key = ConstructorKey::from_usage_key(constructor_key);
        for binding in constructor_usage.all_binding_facts() {
            for use_site in binding.uses() {
                let BindingUse::AssignedFromCall { name, boundary, .. } = use_site else {
                    continue;
                };
                for constraint in internal_call_return_constraints_for_binding(
                    constraints,
                    constructor_usage,
                    name,
                    *boundary,
                    binding,
                    Some(key.type_name()),
                ) {
                    pending.push((key.clone(), binding.clone(), constraint.clone()));
                }
            }
        }
    }
    let mut changed = false;
    for (constructor_key, binding, constraint) in pending {
        changed |= add_constructor_binding_fact_constraint_scoped(
            constraints,
            &constructor_key,
            &binding,
            constraint,
            scope,
        );
    }
    changed
}

fn propagate_call_result_constraints_to_fields(
    constraints: &mut SignatureConstraintState,
    usage: &UsageFacts,
    scope: Option<SignatureMutationScope<'_>>,
) -> bool {
    if scope.is_some_and(|scope| !scope.has_field_target()) {
        return false;
    }
    let mut pending = Vec::new();
    for (usage_key, method_usage) in usage.method_entries() {
        let Some(method_key) = method_key_for_usage(constraints, usage_key) else {
            continue;
        };
        for field_use in method_usage.field_uses() {
            let FieldUse::AssignedFromCall {
                field_name,
                name,
                boundary,
                ..
            } = field_use
            else {
                continue;
            };
            if !scope_permits_field_target(scope, method_key.type_name(), field_name) {
                continue;
            }
            for constraint in internal_call_return_constraints(
                constraints,
                method_usage.call_sites(),
                name,
                *boundary,
                Some(method_key.type_name()),
            ) {
                pending.push((
                    method_key.type_name().to_string(),
                    field_name.clone(),
                    constraint.clone(),
                ));
            }
        }
    }
    let mut changed = false;
    for (type_name, field_name, constraint) in pending {
        changed |=
            add_field_constraint_scoped(constraints, &type_name, &field_name, constraint, scope);
    }
    changed
}

