    #[test]
    fn parsed_try_return_value_then_trailing_null_solves_optional_return_shape() {
        let parsed = crate::parser::parse_java_source(
            r#"
class TryReturnFallthroughCatchFallback {
    String manifestValue(SourceURL url) {
        try {
            Connection connection = url.openConnection();
            Manifest manifest = connection.getManifest();
            return manifest.getValue("Build-Timestamp");
        } catch (Exception e) {
            String message = "failed: " + e.getMessage();
        }
        return null;
    }
}

class SourceURL {
    Connection openConnection() throws Exception { return new Connection(); }
}

class Connection {
    Manifest getManifest() throws Exception { return new Manifest(); }
}

class Manifest {
    String getValue(String key) { return key; }
}
"#,
        );
        let resolved = crate::resolve::resolve_program(&parsed.program, parsed.diagnostics);
        let representations =
            crate::representation::plan_representations(&resolved.program, &resolved.facts);
        let usage = crate::usage::analyze_usage_with_facts(&resolved.program, &resolved.facts);
        let signatures = solve_signatures_with_facts(
            &resolved.program,
            &representations,
            &usage,
            &resolved.facts,
        );
        let ty = resolved
            .program
            .types
            .iter()
            .find(|ty| ty.name == "TryReturnFallthroughCatchFallback")
            .expect("owner type");
        let method = ty
            .members
            .iter()
            .find_map(|member| match member {
                crate::java_ir::Member::Method(method) if method.name == "manifestValue" => {
                    Some(method)
                }
                _ => None,
            })
            .expect("manifestValue method");
        assert!(
            method_return_shape_constraints(ty, method, &usage, &resolved.facts).contains(
                &SignatureConstraint::RequiredStorageNullability(NullabilityState::MaybeNull)
            ),
            "parsed source return constraints must preserve the trailing null"
        );
        let return_shape = signatures
            .required_method_signature(ty, method)
            .return_shape
            .as_ref()
            .expect("string method should have a return shape");

        assert_eq!(
            crate::slot_render::rust_type_for_slot_with_facts(return_shape, &resolved.facts),
            RustType::Option(Box::new(RustType::String))
        );
    }

    #[test]
    fn public_source_map_lookup_return_preserves_nullable_shared_handle() {
        let parsed = crate::parser::parse_java_source(
            r#"
import java.util.HashMap;
import java.util.Map;

class PublicMapValue {}

class PublicMapLookup {
    private static PublicMapLookup instance = new PublicMapLookup();
    private Map<String, PublicMapValue> values = new HashMap<String, PublicMapValue>();

    public PublicMapValue get(String key) {
        return values.get(key);
    }

    public boolean contains(String key) {
        return get(key) != null;
    }
}
"#,
        );
        let resolved = crate::resolve::resolve_program(&parsed.program, parsed.diagnostics);
        let external_facts = FactSet::default();
        let semantic = crate::semantic_analysis::analyze_program(
            &resolved.program,
            &resolved.facts,
            &external_facts,
        );
        let representations =
            crate::representation::plan_representations(&resolved.program, &semantic.facts);
        let owner = resolved
            .program
            .types
            .iter()
            .find(|ty| ty.name == "PublicMapLookup")
            .expect("owner type");
        let method = owner
            .members
            .iter()
            .find_map(|member| match member {
                crate::java_ir::Member::Method(method) if method.name == "get" => Some(method),
                _ => None,
            })
            .expect("get method");
        let nullable = SignatureConstraint::RequiredStorageNullability(NullabilityState::MaybeNull);
        let initial = collect_signature_constraints_with_representations(
            &resolved.program,
            &representations,
            &semantic.usage,
            &semantic.facts,
        );
        let key = MethodKey::source_method(owner, method);
        assert!(
            initial
                .methods
                .get(&key)
                .expect("method constraints")
                .return_constraints
                .contains(&nullable),
            "public map lookup must start nullable"
        );
        let (solved_constraints, _) =
            solve_signature_constraints_to_fixpoint(initial.clone(), &semantic.usage);
        let solved_return_constraints = solved_constraints
            .methods
            .get(&key)
            .expect("solved method constraints")
            .return_constraints
            .clone();
        let signatures = solve_signatures_with_facts(
            &resolved.program,
            &representations,
            &semantic.usage,
            &semantic.facts,
        );
        let return_shape = signatures
            .required_method_signature(owner, method)
            .return_shape
            .as_ref()
            .expect("reference return shape");
        assert!(
            return_shape.optional_element_type().is_some(),
            "public map lookup must remain nullable after saturation: {return_shape:?}; constraints={solved_return_constraints:?}"
        );
    }

