    #[test]
    fn string_return_borrow_requires_parameter_provenance_not_a_resolved_callee_borrow() {
        let parsed = crate::parser::parse_java_source(
            r#"
            class Provenance {
                static String relay(String value) { return value; }
                static String temporary() { return relay(new String("x")); }
                static String mixed(boolean choose, String value) {
                    if (choose) return value;
                    return new String("other");
                }
            }
        "#,
        );
        let resolved = crate::resolve::resolve_program(&parsed.program, parsed.diagnostics);
        assert!(
            !resolved.diagnostics.has_errors(),
            "{:?}",
            resolved.diagnostics
        );
        for member in &resolved.program.types[0].members {
            let Member::Method(method) = member else {
                continue;
            };
            let names: Vec<_> = method.params.iter().map(|p| p.name.clone()).collect();
            let constraints = MethodConstraintSet {
                param_names: names.clone(),
                param_index_by_name: index_names(&names),
                param_java_types: method.params.iter().map(|p| p.ty.clone()).collect(),
                params: method
                    .params
                    .iter()
                    .map(|_| {
                        vec![SignatureConstraint::RequiredOwnership(
                            OwnershipShape::SharedBorrow,
                        )]
                    })
                    .collect(),
                return_constraints: vec![SignatureConstraint::RequiredOwnership(
                    OwnershipShape::SharedBorrow,
                )],
                ..MethodConstraintSet::default()
            };
            assert_eq!(
                string_return_can_use_borrowed_view(method, Some(&constraints)),
                method.name == "relay",
                "{}",
                method.name
            );
            assert!(!string_return_can_use_borrowed_view(method, None));
        }
    }

    #[test]
    fn returned_object_alias_constraints_use_param_binding_not_shadow_name() {
        let binding = BindingId::new(BindingKind::Param, "value", 0);
        let param = string_param(binding.clone());
        let method = private_static_returning_param_method(param);
        let ty = test_owner_type();
        let facts = FactSet::default();

        let returned_only = usage_with_param_and_shadow_facts(
            &ty,
            &method,
            binding.clone(),
            vec![BindingUse::Returned],
        );
        assert_eq!(
            internal_returned_object_alias_borrow_constraints(&ty, &method, &returned_only, &facts),
            vec![SignatureConstraint::RequiredOwnership(
                OwnershipShape::SharedBorrow,
            )],
            "a same-name shadow local must not veto the resolver-bound returned parameter"
        );

        let mutated_exact = usage_with_param_and_shadow_facts(
            &ty,
            &method,
            binding,
            vec![BindingUse::Returned, BindingUse::Mutated],
        );
        assert!(
            internal_returned_object_alias_borrow_constraints(&ty, &method, &mutated_exact, &facts)
                .is_empty(),
            "mutation of the exact parameter binding still rejects shared-borrow return"
        );

        let forwarded_binding = BindingId::new(BindingKind::Param, "value", 0);
        let internally_forwarded = usage_with_param_and_shadow_facts(
            &ty,
            &method,
            forwarded_binding,
            vec![
                BindingUse::Returned,
                BindingUse::PassedToCall {
                    name: "helper".to_string(),
                    receiver_type: None,
                    arg_count: 1,
                    arg_index: 0,
                    boundary: CallArgumentBoundary::InternalSameType,
                },
            ],
        );
        assert!(
            internal_returned_object_alias_borrow_constraints(
                &ty,
                &method,
                &internally_forwarded,
                &facts,
            )
            .is_empty(),
            "a returned alias forwarded into an internal call must wait for the callee signature instead of independently forcing shared borrow"
        );
    }

    #[test]
    fn method_signature_presence_fails_closed_for_ambiguous_simple_package_owner() {
        let method = MethodSignaturePlan::new(Vec::new(), None, Vec::new(), ReceiverPlan::None);
        let mut plan = SignaturePlan::default();
        plan.methods
            .insert(MethodKey::rust_identity("a.Item", "other"), method.clone());
        plan.methods
            .insert(MethodKey::rust_identity("b.Item", "who"), method.clone());

        assert!(plan.has_method_signature_by_base_name_accepting_arity("a.Item", "other", 0));
        assert!(plan.has_method_signature_by_base_name_accepting_arity("b.Item", "who", 0));
        assert!(
            !plan.has_method_signature_by_base_name_accepting_arity("Item", "who", 0),
            "bare same-simple owners must not report presence when multiple package peers exist, even if only one has the method"
        );
    }

    #[test]
    fn receiver_lookup_joins_unambiguous_package_alias_but_not_peer_packages() {
        let shared = MethodSignaturePlan::new(Vec::new(), None, Vec::new(), ReceiverPlan::Shared);
        let mutable = MethodSignaturePlan::new(Vec::new(), None, Vec::new(), ReceiverPlan::Mutable);
        let mut plan = SignaturePlan::default();
        plan.methods
            .insert(MethodKey::rust_identity("Item", "close"), shared.clone());
        plan.methods
            .insert(MethodKey::rust_identity("a.Item", "close"), mutable.clone());

        assert_eq!(
            plan.method_receiver_by_rust_name("Item", "close"),
            Some(ReceiverPlan::Mutable)
        );

        plan.methods
            .insert(MethodKey::rust_identity("b.Item", "close"), mutable);
        assert_eq!(
            plan.method_receiver_by_rust_name("Item", "close"),
            Some(ReceiverPlan::Shared),
            "a bare owner must not join receiver capabilities across peer packages"
        );
    }

    #[test]
    fn receiver_fixpoint_joins_flattened_nested_owner_without_crossing_package_peers() {
        let shared = MethodConstraintSet::default();
        let mutable = MethodConstraintSet {
            receiver: vec![ReceiverConstraint::MutableReceiver],
            ..MethodConstraintSet::default()
        };
        let mut constraints = SignatureConstraintState::default()
            .with_method_constraints(
                MethodKey::rust_identity("Outer_Inner", "write"),
                shared.clone(),
            )
            .with_method_constraints(
                MethodKey::rust_identity("Outer.Inner", "write"),
                mutable.clone(),
            );

        assert!(equalize_source_owner_alias_receiver_constraints(
            &mut constraints
        ));
        assert!(
            constraints
                .methods
                .get(&MethodKey::rust_identity("Outer_Inner", "write"))
                .expect("flattened nested method")
                .receiver
                .contains(&ReceiverConstraint::MutableReceiver)
        );

        let mut ambiguous = SignatureConstraintState::default()
            .with_method_constraints(MethodKey::rust_identity("Item", "write"), shared)
            .with_method_constraints(MethodKey::rust_identity("a.Item", "write"), mutable.clone())
            .with_method_constraints(MethodKey::rust_identity("b.Item", "write"), mutable);
        assert!(!equalize_source_owner_alias_receiver_constraints(
            &mut ambiguous
        ));
        assert!(
            !ambiguous
                .methods
                .get(&MethodKey::rust_identity("Item", "write"))
                .expect("bare method")
                .receiver
                .contains(&ReceiverConstraint::MutableReceiver),
            "ambiguous package peers must not widen the bare owner"
        );
    }

    #[test]
    fn late_mutable_receiver_requires_parameter_borrow_without_poisoning_other_owners() {
        let parsed = crate::parser::parse_java_source(
            r#"
class Sink { void write() {} }
class Reader { void write() {} }
class Forwarder {
    static void forward(Sink sink) { sink.write(); }
    static void read(Reader reader) { reader.write(); }
}
class Holder { Holder(Sink sink) { sink.write(); } }
"#,
        );
        let resolved = crate::resolve::resolve_program(&parsed.program, parsed.diagnostics);
        let usage = crate::usage::analyze_usage(&resolved.program);
        let mut constraints =
            collect_signature_constraints(&resolved.program, &usage, &FactSet::default());
        fn method<'a>(ty: &'a TypeDecl, name: &str) -> &'a MethodDecl {
            ty.members
                .iter()
                .find_map(|member| match member {
                    Member::Method(method) if method.name == name => Some(method),
                    _ => None,
                })
                .unwrap()
        }
        let sink = &resolved.program.types[0];
        constraints
            .methods
            .get_mut(&MethodKey::source_method(sink, method(sink, "write")))
            .unwrap()
            .receiver
            .push(ReceiverConstraint::MutableReceiver);
        constraints.rebuild_method_lookup_index();
        let graph = build_signature_dependency_graph(&constraints, &usage);
        let analysis = analyze_signature_dependency_sccs(&graph);
        let passes = plan_signature_solver_passes(&analysis);
        execute_signature_solver_pass_plan(&mut constraints, &usage, &analysis, &passes);
        let owner = &resolved.program.types[2];
        let mutable = SignatureConstraint::RequiredOwnership(OwnershipShape::MutableBorrow);
        assert!(
            constraints.methods[&MethodKey::source_method(owner, method(owner, "forward"))].params
                [0]
            .contains(&mutable)
        );
        assert!(
            !constraints.methods[&MethodKey::source_method(owner, method(owner, "read"))].params[0]
                .contains(&mutable)
        );
        let holder = &resolved.program.types[3];
        let constructor = holder
            .members
            .iter()
            .find_map(|member| match member {
                Member::Constructor(constructor) => Some(constructor),
                _ => None,
            })
            .unwrap();
        assert!(
            constraints.constructors[&ConstructorKey::source_constructor(holder, constructor)]
                .params[0]
                .contains(&mutable)
        );
    }

    #[test]
    fn public_collection_forwarding_uses_advisory_not_retention_ownership() {
        let parsed = crate::parser::parse_java_source(
            r#"
import java.util.List;
class Forwarders {
    static List<String> saved;
    public static <T> void leaf(List<T> items) { items.set(0, items.get(1)); }
    public static <T> void middle(List<T> items) { leaf(items); }
    public static <T> void outer(List<T> items) { middle(items); }
    public static void store(List<String> items) { saved = items; Other.sink(items); }
    public static <T> List<T> returned(List<T> items) { Other.sink(items); return items; }
    public static <T> void aliased(List<T> items) { List<T> copy = items; Other.sink(copy); }
    public static <T> void opaque(List<T> items) { Unknown.consume(items); Other.sink(items); }
}
class Other { public static <T> void sink(List<T> items) { items.set(0, items.get(1)); } }
"#,
        );
        let resolved = crate::resolve::resolve_program(&parsed.program, parsed.diagnostics);
        let semantic = crate::semantic_analysis::analyze_program(
            &resolved.program,
            &resolved.facts,
            &FactSet::default(),
        );
        let usage = semantic.usage;
        let mut constraints =
            collect_signature_constraints(&resolved.program, &usage, &semantic.facts);
        let owner = &resolved.program.types[0];
        let methods = owner
            .members
            .iter()
            .filter_map(|member| match member {
                Member::Method(method) => Some(method),
                _ => None,
            })
            .collect::<Vec<_>>();
        for method in &methods[1..3] {
            assert!(
                constraints.methods[&MethodKey::source_method(owner, method)].params[0]
                    .contains(&SignatureConstraint::ApiOwnedFallback),
                "{} should carry only an API fallback",
                method.name
            );
        }
        for method in &methods[3..] {
            assert!(
                !constraints.methods[&MethodKey::source_method(owner, method)].params[0]
                    .contains(&SignatureConstraint::ApiOwnedFallback),
                "{} must not weaken an escape/alias boundary",
                method.name
            );
        }
        let graph = build_signature_dependency_graph(&constraints, &usage);
        let analysis = analyze_signature_dependency_sccs(&graph);
        let passes = plan_signature_solver_passes(&analysis);
        execute_signature_solver_pass_plan(&mut constraints, &usage, &analysis, &passes);
        for method in &methods[1..3] {
            let shape = MergedSignatureConstraints::from_constraints(
                &constraints.methods[&MethodKey::source_method(owner, method)].params[0],
            )
            .apply_to_shape(RustSlotShape::for_storage(method.params[0].ty.clone()));
            assert_eq!(
                shape.ownership,
                OwnershipShape::MutableBorrow,
                "{} lost caller-visible mutation: {:?}; leaf: {:?}",
                method.name,
                constraints.methods[&MethodKey::source_method(owner, method)].params[0],
                constraints.methods[&MethodKey::source_method(owner, methods[0])].params[0],
            );
        }
        for requirements in [
            vec![
                SignatureConstraint::ApiOwnedFallback,
                SignatureConstraint::RequiredOwnership(OwnershipShape::MutableBorrow),
            ],
            vec![
                SignatureConstraint::RequiredOwnership(OwnershipShape::MutableBorrow),
                SignatureConstraint::ApiOwnedFallback,
            ],
        ] {
            let mut requirements = requirements;
            let shape = RustSlotShape::for_storage(JavaType::String);
            assert_eq!(
                MergedSignatureConstraints::from_constraints(&requirements)
                    .apply_to_shape(shape.clone())
                    .ownership,
                OwnershipShape::MutableBorrow
            );
            requirements.push(SignatureConstraint::RequiredOwnership(
                OwnershipShape::Owned,
            ));
            assert_eq!(
                MergedSignatureConstraints::from_constraints(&requirements)
                    .apply_to_shape(shape)
                    .ownership,
                OwnershipShape::Owned
            );
        }
        assert!(
            !signature_shape_constraint_propagation_policy()
                .allows(&SignatureConstraint::ApiOwnedFallback)
        );
    }

    #[test]
    fn late_mutable_arguments_propagate_capability_through_exact_forwarding_slots() {
        let parsed = crate::parser::parse_java_source(
            r#"
class Sink {}
class Reader {}
class Ops {
    static void apply(Sink sink, int ignored) {}
    static void apply(Reader reader, int ignored) {}
    static void middle(Sink sink) { apply(sink, 0); }
    static void outer(Sink sink) { middle(sink); }
    static void read(Reader reader) { apply(reader, 0); }
}
class Holder { public Holder(Sink sink) { Ops.apply(sink, 0); } }
"#,
        );
        let resolved = crate::resolve::resolve_program(&parsed.program, parsed.diagnostics);
        assert!(
            !resolved.diagnostics.has_errors(),
            "{:?}",
            resolved.diagnostics
        );
        let usage = crate::usage::analyze_usage(&resolved.program);
        let mut constraints =
            collect_signature_constraints(&resolved.program, &usage, &FactSet::default());
        let owner = &resolved.program.types[2];
        let methods = owner
            .members
            .iter()
            .filter_map(|member| match member {
                Member::Method(method) => Some(method),
                _ => None,
            })
            .collect::<Vec<_>>();
        let mutable = SignatureConstraint::RequiredOwnership(OwnershipShape::MutableBorrow);
        constraints
            .methods
            .get_mut(&MethodKey::source_method(owner, methods[0]))
            .unwrap()
            .params[0]
            .push(mutable.clone());
        constraints.rebuild_method_lookup_index();
        let graph = build_signature_dependency_graph(&constraints, &usage);
        let analysis = analyze_signature_dependency_sccs(&graph);
        let passes = plan_signature_solver_passes(&analysis);
        execute_signature_solver_pass_plan(&mut constraints, &usage, &analysis, &passes);
        for method in &methods[2..4] {
            assert!(
                constraints.methods[&MethodKey::source_method(owner, method)].params[0]
                    .contains(&mutable),
                "{} lost mutable forwarding capability",
                method.name
            );
        }
        for method in [methods[1], methods[4]] {
            assert!(
                !constraints.methods[&MethodKey::source_method(owner, method)].params[0]
                    .contains(&mutable),
                "{} inherited unrelated overload mutation",
                method.name
            );
        }
        let holder = &resolved.program.types[3];
        let ctor = holder
            .members
            .iter()
            .find_map(|member| match member {
                Member::Constructor(ctor) => Some(ctor),
                _ => None,
            })
            .unwrap();
        assert!(
            constraints.constructors[&ConstructorKey::source_constructor(holder, ctor)].params[0]
                .contains(&mutable)
        );
    }

    #[test]
    fn signature_pass_propagates_late_mutable_receiver_to_same_receiver_caller() {
        let parsed = crate::parser::parse_java_source(
            "class LateReceiver { void write() { deflate(0); } void deflate(int mode) {} }",
        );
        let resolved = crate::resolve::resolve_program(&parsed.program, parsed.diagnostics);
        let usage = crate::usage::analyze_usage(&resolved.program);
        let facts = FactSet::default();
        let mut constraints = collect_signature_constraints(&resolved.program, &usage, &facts);
        let owner = &resolved.program.types[0];
        let deflate = owner
            .members
            .iter()
            .find_map(|member| match member {
                Member::Method(method) if method.name == "deflate" => Some(method),
                _ => None,
            })
            .expect("deflate method");
        let write = owner
            .members
            .iter()
            .find_map(|member| match member {
                Member::Method(method) if method.name == "write" => Some(method),
                _ => None,
            })
            .expect("write method");
        constraints
            .methods
            .get_mut(&MethodKey::source_method(owner, deflate))
            .expect("deflate constraints")
            .receiver
            .push(ReceiverConstraint::MutableReceiver);
        constraints.rebuild_method_lookup_index();

        let graph = build_signature_dependency_graph(&constraints, &usage);
        let analysis = analyze_signature_dependency_sccs(&graph);
        let pass_plan = plan_signature_solver_passes(&analysis);
        assert!(execute_signature_solver_pass_plan(
            &mut constraints,
            &usage,
            &analysis,
            &pass_plan,
        ));
        assert!(
            constraints
                .methods
                .get(&MethodKey::source_method(owner, write))
                .expect("write constraints")
                .receiver
                .contains(&ReceiverConstraint::MutableReceiver)
        );
    }

    #[test]
    fn dependency_graph_deduplicates_edges_without_reordering_first_insertions() {
        let left = SignatureDependencyNode::MethodReturn {
            method: MethodKey::rust_identity("Owner", "left"),
        };
        let right = SignatureDependencyNode::MethodReturn {
            method: MethodKey::rust_identity("Owner", "right"),
        };
        let mut graph = SignatureDependencyGraph::default();

        add_signature_dependency_edge(
            &mut graph,
            left.clone(),
            right.clone(),
            SignatureDependencyEdgeKind::MethodReturn,
        );
        add_signature_dependency_edge(
            &mut graph,
            left.clone(),
            right.clone(),
            SignatureDependencyEdgeKind::MethodReturn,
        );
        add_signature_dependency_edge(
            &mut graph,
            right.clone(),
            left.clone(),
            SignatureDependencyEdgeKind::Receiver,
        );

        assert_eq!(graph.edges().len(), 2);
        assert_eq!(graph.edges()[0].from(), &left);
        assert_eq!(graph.edges()[0].to(), &right);
        assert_eq!(graph.edges()[1].from(), &right);
        assert_eq!(graph.edges()[1].to(), &left);
    }

